        return YES;
    }
    if (n < 2 || n % 2 == 0) {
        return NO;
    }
    double d = sqrt(n);
    for (int i = 3; i <= d; i += 2) {
        if (n % i == 0) {
            return NO;
        }
    }
    return YES;
}

@end

