#import <Foundation/Foundation.h>

@interface PriorityQueue : NSObject
@property (nonatomic, strong) NSMutableArray *elements;

- (instancetype)init;
- (void)add:(NSInteger)element;
- (NSInteger)poll;
@end

@implementation PriorityQueue
- (instancetype)init {
    self = [super init];
    if (self) {
        _elements = [[NSMutableArray alloc] init];
    }
    return self;
}

- (void)add:(NSInteger)element {
    [_elements addObject:@(element * -1)];
    [self heapifyUp:_elements.count - 1];
}

- (NSInteger)poll {
    if (_elements.count == 0) {
        return 0;
    }
    NSInteger root = [_elements[0] integerValue];
    [_elements[0] setValue:@(_elements.lastObject)];
    [_elements removeLastObject];
    [self heapifyDown:0];
    return root * -1;
}

- (void)heapifyUp:(NSInteger)index {
    NSInteger parentIndex = (index - 1) / 2;
    while (index > 0 && [_elements[index] integerValue] < [_elements[parentIndex] integerValue]) {
        [_elements[index] setValue:@(_elements[parentIndex])];
        [_elements[parentIndex] setValue:@(_elements[index])];
        index = parentIndex;
        parentIndex = (index - 1) / 2;
    }
}

- (void)heapifyDown:(NSInteger)index {
    NSInteger leftChildIndex = index * 2 + 1;
    NSInteger rightChildIndex = index * 2 + 2;
    NSInteger smallestIndex = index;

    if (leftChildIndex < _elements.count && [_elements[leftChildIndex] integerValue] < [_elements[smallestIndex] integerValue]) {
        smallestIndex = leftChildIndex;
    }

    if (rightChildIndex < _elements.count && [_elements[rightChildIndex] integerValue] < [_elements[smallestIndex] integerValue]) {
        smallestIndex = rightChildIndex;
    }

    if (smallestIndex != index) {
        [_elements[index] setValue:@(_elements[smallestIndex])];
        [_elements[smallestIndex] setValue:@(_elements[index])];
        [self heapifyDown:smallestIndex];
    }
}
@end

