@interface PriorityQueue : NSObject

@property (nonatomic, strong) NSMutableArray *elements;

- (instancetype)init;
- (void)add:(NSNumber *)element;
- (NSNumber *)poll;

@end

@implementation PriorityQueue

- (instancetype)init {
    self = [super init];
    if (self) {
        _elements = [[NSMutableArray alloc] init];
    }
    return self;
}

- (void)add:(NSNumber *)element {
    [_elements addObject:element];
    [self heapifyUp];
}

- (NSNumber *)poll {
    if (_elements.count == 0) {
        return nil;
    }
    NSNumber *result = _elements[0];
    [_elements[0] setValue:_elements.lastObject];
    [_elements removeLastObject];
    [self heapifyDown];
    return result;
}

- (void)heapifyUp {
    NSInteger index = _elements.count - 1;
    while (index > 0) {
        NSInteger parentIndex = (index - 1) / 2;
        if ([_elements[index] intValue] >= [_elements[parentIndex] intValue]) {
            break;
        }
        NSNumber *temp = _elements[index];
        [_elements[index] setValue:_elements[parentIndex]];
        [_elements[parentIndex] setValue:temp];
        index = parentIndex;
    }
}

- (void)heapifyDown {
    NSInteger index = 0;
    while (index < _elements.count) {
        NSInteger leftChildIndex = 2 * index + 1;
        NSInteger rightChildIndex = 2 * index + 2;
        NSInteger smallestIndex = index;
        if (leftChildIndex < _elements.count && [_elements[leftChildIndex] intValue] < [_elements[smallestIndex] intValue]) {
            smallestIndex = leftChildIndex;
        }
        if (rightChildIndex < _elements.count && [_elements[rightChildIndex] intValue] < [_elements[smallestIndex] intValue]) {
            smallestIndex = rightChildIndex;
        }
        if (smallestIndex == index) {
            break;
        }
        NSNumber *temp = _elements[index];
        [_elements[index] setValue:_elements[smallestIndex]];
        [_elements[smallestIndex] setValue:temp];
        index = smallestIndex;
    }
}

@end

