- (NSString *)readLine {
    if (self.lineIndex >= self.lineCount) {
        [self.data setLength:0];
        self.lineIndex = 0;
        self.lineCount = 0;
        self.lineNumber = 0;
        self.lineOffset = 0;
        [self.inputStream open];
        [self.inputStream read:self.data.mutableBytes maxLength:self.data.length];
        [self.inputStream close];
        if (self.data.length == 0) {
            return nil;
        }
        self.lineCount = [self.data length];
    }
    NSInteger offset = self.lineIndex + self.lineOffset;
    while (offset < self.lineCount && self.data[offset] != '\n') {
        offset++;
    }
    NSString *line = [[NSString alloc] initWithBytes:self.data.mutableBytes + self.lineIndex length:offset - self.lineIndex encoding:NSUTF8StringEncoding];
    self.lineIndex = offset + 1;
    self.lineOffset = self.lineIndex;
    return line;
}

