    void solve() throws IOException {
      Scanner sc = new Scanner(System.in);
      while(sc.hasNext()){
        int a = sc.nextInt();
        int b = sc.nextInt();
        int sum = a + b;
        int cnt = 0;

        while (true) {
          sum /= 10;
          cnt++;
          if (sum == 0) {
            break;
          }
        }

        out.println(cnt);
      }

    }

