#import <Foundation/Foundation.h>

@interface InputReader : NSObject

- (int)nextInt;
- (long long)nextLong;
- (NSString *)next;
- (double)nextDouble;

@end

@implementation InputReader

- (int)nextInt {
  NSString *line = [self next];
  return [line intValue];
}

- (long long)nextLong {
  NSString *line = [self next];
  return [line longLongValue];
}

- (NSString *)next {
  static NSMutableString *line = nil;
  static NSUInteger pos = 0;
  static NSError *error = nil;

  if (!line) {
    line = [[NSMutableString alloc] init];
    error = nil;
    [[NSFileHandle fileHandleWithStandardInput] readDataOfLength:1 intoBuffer:&pos error:&error];
    pos = 0;
  }

  while (pos < line.length && ![line characterAtIndex:pos] isWhitespace] {
    pos++;
  }

  while (pos < line.length && ![line characterAtIndex:pos] isWhitespace]) {
    pos++;
  }

  if (pos == line.length) {
    line = nil;
    return [self next];
  }

  return [line substringWithRange:NSMakeRange(pos, line.length - pos)];
}

- (double)nextDouble {
  NSString *line = [self next];
  return [line doubleValue];
}

@end

