    if (![self hasNext]) throw [NSException exceptionWithName:@"NoNextException" reason:@"No more elements to read" userInfo:nil];
    BOOL minus = NO;
    int temp = [self readByte];
    if (temp == '-') {
        minus = YES;
        temp = [self readByte];
    }
    if (temp < '0' || '9' < temp) throw [NSException exceptionWithName:@"NumberFormatException" reason:@"Invalid number format" userInfo:nil];
    long long n = 0;
    while ([[self isPrintable:temp] boolValue]) {
        if ('0' <= temp && temp <= '9') {
            n *= 10;
            n += temp - '0';
        }
        else throw [NSException exceptionWithName:@"NumberFormatException" reason:@"Invalid number format" userInfo:nil];
        temp = [self readByte];
    }
    return minus ? -n : n;
}

