@implementation FastScanner

- (instancetype)initWithInputStream:(NSInputStream *)stream {
    self = [super init];
    if (self) {
        _in = stream;
    }
    return self;
}

- (BOOL)hasNextByte {
    if (_p < _length) return YES;
    else {
        _p = 0;
        _length = [_in read:_buffer maxLength:1024];
        if (_length <= 0) return NO;
    }
    return YES;
}

- (int)readByte {
    if ([self hasNextByte] == YES) return _buffer[_p++];
    return -1;
}

- (BOOL)isPrintable:(int)n {
    return 33 <= n && n <= 126;
}

- (void)skip {
    while ([self hasNextByte] && ![self isPrintable:_buffer[_p]]) _p++;
}

- (BOOL)hasNext {
    [self skip];
    return [self hasNextByte];
}

- (NSString *)next {
    if (![self hasNext]) throw [NSException exceptionWithName:@"NoSuchElementException" reason:@"No more elements" userInfo:nil];
    NSMutableString *sb = [NSMutableString string];
    int t = [self readByte];
    while ([self isPrintable:t]) {
        [sb appendFormat:@"%c", (char)t];
        t = [self readByte];
    }
    return sb;
}

- (NSArray *)nextArray:(int)n {
    NSMutableArray *ar = [NSMutableArray array];
    for (int i=0; i<n; i++) [ar addObject:[self next]];
    return ar;
}

- (int)nextInt {
    return (int)[self nextLong];
}

- (NSArray *)nextIntArray:(int)n {
    NSMutableArray *ar = [NSMutableArray array];
    for (int i=0; i<n; i++) [ar addObject:@([self nextInt])];
    return ar;
}

- (long long)nextLong {
    if (![self hasNext]) throw [NSException exceptionWithName:@"NoSuchElementException" reason:@"No more elements" userInfo:nil];
    BOOL minus = NO;
    int temp = [self readByte];
    if (temp == '-') {
        minus = YES;
        temp = [self readByte];
    }
    if (temp < '0' || temp > '9') throw [NSException exceptionWithName:@"NumberFormatException" reason:@"Invalid character" userInfo:nil];
    long long n = 0;
    while ([self isPrintable:temp]) {
        if ('0' <= temp && temp <= '9') {
            n *= 10;
            n += temp - '0';
        }
        else throw [NSException exceptionWithName:@"NumberFormatException" reason:@"Invalid character" userInfo:nil];
        temp = [self readByte];
    }
    return minus ? -n : n;
}

- (NSArray *)nextLongArray:(int)n {
    NSMutableArray *ar = [NSMutableArray array];
    for (int i=0; i<n; i++) [ar addObject:@([self nextLong])];
    return ar;
}

- (double)nextDouble {
