#import <Foundation/Foundation.h>

@interface InputReader : NSObject
- (int)nextInt;
- (long long)nextLong;
- (NSString *)next;
- (double)nextDouble;
@end

@implementation InputReader

- (int)nextInt {
    int result = 0;
    int sign = 1;
    int c = [self readChar];
    while (c == ' ' || c == '\n' || c == '\r' || c == '\t') {
        c = [self readChar];
    }
    if (c == '-') {
        sign = -1;
        c = [self readChar];
    }
    while (c >= '0' && c <= '9') {
        result = result * 10 + c - '0';
        c = [self readChar];
    }
    return result * sign;
}

- (long long)nextLong {
    long long result = 0;
    int sign = 1;
    int c = [self readChar];
    while (c == ' ' || c == '\n' || c == '\r' || c == '\t') {
        c = [self readChar];
    }
    if (c == '-') {
        sign = -1;
        c = [self readChar];
    }
    while (c >= '0' && c <= '9') {
        result = result * 10 + c - '0';
        c = [self readChar];
    }
    return result * sign;
}

- (NSString *)next {
    NSMutableString *result = [NSMutableString string];
    int c = [self readChar];
    while (c == ' ' || c == '\n' || c == '\r' || c == '\t') {
        c = [self readChar];
    }
    while (c != ' ' && c != '\n' && c != '\r' && c != '\t') {
        [result appendString:[NSString stringWithFormat:@"%c", c]];
        c = [self readChar];
    }
    return result;
}

- (double)nextDouble {
    double result = 0.0;
    int sign = 1;
