double *gaussJordan(double A[2][2], double b[2]) {
    double B[2][3] = {{0,0,0},{0,0,0}};
    for (int i=0;i<2;i++) {
        for (int j=0;j<2;j++) {
            B[i][j] = A[i][j];
        }
        B[i][2] = b[i];
