        for (int r=pivot;r<2;r++) {
            if (fabs(B[r][v])>fabs(B[pivot][v])) {
                pivot = r;
            }
        }

        swapRowD(B, v, pivot);
        for (int c=v+1;c<3;c++) {
            B[v][c] /= B[v][v];
        }
        for (int r=0;r<2;r++) {
