+ (double *)gaussJordan:(double *)A b:(double *)b {
    int n = 2;
    double *B = (double *)malloc(sizeof(double) * (n * (n + 1)));
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < n; j++) {
            B[i * (n + 1) + j] = A[i * n + j];
        }
        B[i * (n + 1) + n] = b[i];
    }

    for (int v = 0; v < n; v++) {
        int pivot = v;
        for (int r = v; r < n; r++) {
            if (fabs(B[r * (n + 1) + v]) > fabs(B[pivot * (n + 1) + v])) {
                pivot = r;
            }
        }

        [self swapRowD:B m:v n:pivot];
        for (int c = v + 1; c < n + 1; c++) {
            B[v * (n + 1) + c] /= B[v * (n + 1) + v];
        }
        for (int r = 0; r < n; r++) {
            if (r == v) continue;
            for (int c = v + 1; c < n + 1; c++) {
                B[r * (n + 1) + c] -= B[v * (n + 1) + c] * B[r * (n + 1) + v];
            }
        }
    }

    double *res = (double *)malloc(sizeof(double) * n);
    for (int i = 0; i < n; i++) {
        res[i] = B[i * (n + 1) + n];
    }
    free(B);
    return res;
}

+ (void)swapRowD:(double *)A m:(int)m n:(int)n {
    double *tmp = A + m * (n + 1);
    for (int i = 0; i < n + 1; i++) {
        double temp = tmp[i];
        tmp[i] = A[n * (n + 1) + i];
        A[n * (n + 1) + i] = temp;
    }
}

