    if (self) {
        self.in = source;
        self.buffer = [[NSMutableData alloc] init];
        self.ptr = 0;
        self.buflen = 0;
    }
    return self;
}

- (BOOL)hasNextByte {
    if (self.ptr < self.buflen) return YES;
    else {
        self.ptr = 0;
        [self.in read:self.buffer.mutableBytes maxLength:self.buffer.length];
        if (self.buflen <= 0) return NO;
    }
    return YES;
}

- (int)readByte {
    if ([self hasNextByte]) return [self.buffer bytes][self.ptr++];
    else return -1;
}

- (BOOL)isPrintableChar:(int)c {
    return c >= 33 && c <= 126;
}

- (void)skipUnprintable {
    while ([self hasNextByte] && ![self isPrintableChar:[self.buffer bytes][self.ptr]]) self.ptr++;
}

- (BOOL)hasNext {
    [self skipUnprintable];
    return [self hasNextByte];
}

- (long long)nextLong {
    if (![self hasNext]) {
        NSLog(@"No more input");
        return 0;
    }
    long long n = 0;
    BOOL minus = NO;
    int b = [self readByte];
    if (b == '-') {
        minus = YES;
        b = [self readByte];
    }
    if (b < '0' || b > '9') {
        NSLog(@"Invalid input");
        return 0;
