            n *= 10;
            n += b - '0';
        } else if (b == -1 || ![self isPrintableChar:b]) {
            return minus ? -n : n;
        } else {
            NSLog(@"Invalid input");
            return 0;
        }
        b = [self readByte];
    }
}

