        [self inputStream].readBuffer[0] = 0;
    }
    while ([self inputStream].readBuffer[0] >= '0' && [self inputStream].readBuffer[0] <= '9') {
        n *= 10;
        n += [self inputStream].readBuffer[0] - '0';
        [self inputStream].readBuffer[0] = 0;
    }
    return minus ? -n : n;
}

- (void)close {
    [self inputStream].close;
    [self outputStream].close;
}

