@implementation InputReader

- (instancetype)initWithInputStream:(NSInputStream *)inputStream outputStream:(NSOutputStream *)outputStream {
    self = [super init];
    if (self) {
        _inputStream = inputStream;
        _outputStream = outputStream;
        _currentLine = @"";
        _tokens = [NSMutableArray array];
    }
    return self;
}

- (NSString *)nextLine {
    if (_currentLine.length == 0) {
        char buffer[1024];
        NSInteger bytesRead = [_inputStream read:buffer maxLength:1024];
        if (bytesRead > 0) {
            _currentLine = [NSString stringWithUTF8String:buffer];
        }
    }
    return _currentLine;
}

- (NSString *)nextToken {
    if (_tokens.count == 0) {
        NSString *line = [self nextLine];
        if (line.length > 0) {
            NSArray *components = [line componentsSeparatedByCharactersInSet:[NSCharacterSet whitespaceCharacterSet]];
            _tokens = [components mutableCopy];
        }
    }
    if (_tokens.count > 0) {
        NSString *token = _tokens[0];
        [_tokens removeObjectAtIndex:0];
        return token;
    }
    return @"";
}

- (int)nextInt {
    NSString *token = [self nextToken];
    return [token intValue];
}

- (long long)nextLong {
    NSString *token = [self nextToken];
    return [token longLongValue];
}

- (double)nextDouble {
