        char c = [self.br get];
        if (c == '-') {
            isNegative = YES;
        } else if (c >= '0' && c <= '9') {
            result = result * 10 + (c - '0');
        } else if (c == '\n' || c == '\r' || c == ' ') {
            break;
        }
    }
    return isNegative ? -result : result;
}

- (long long)nextLong {
    long long result = 0;
    BOOL isNegative = NO;
    while (1) {
        char c = [self.br get];
        if (c == '-') {
            isNegative = YES;
        } else if (c >= '0' && c <= '9') {
            result = result * 10 + (c - '0');
        } else if (c == '\n' || c == '\r' || c == ' ') {
