    while (1) {
        char c = [self.br get];
        if (c == '\n' || c == '\r' || c == ' ') {
            break;
        }
        [result appendString:[NSString stringWithFormat:@"%c", c]];
    }
    return result;
}

- (double)nextDouble {
    double result = 0.0;
    BOOL isNegative = NO;
    BOOL isDecimal = NO;
    int decimalPlaces = 0;
    while (1) {
        char c = [self.br get];
        if (c == '-') {
            isNegative = YES;
        } else if (c >= '0' && c <= '9') {
