        self.outputStream = [[NSOutputStream alloc] initToFileAtPath:@"/dev/stdout" append:NO];

        [self.inputStream open];
        [self.outputStream open];
    }
    return self;
}

- (void)run {
    int count;
    [self.inputStream read:&count maxLength:sizeof(int)];
    long money = 100000;
    while (count-- != 0) {
        money *= 1.05;
        if (money % 1000 != 0) {
            money += 1000;
        }
        money -= money % 1000;
    }
    [self.outputStream write:(const uint8_t *)&money maxLength:sizeof(long)];
    [self.outputStream close];
    [self.inputStream close];
}

@end

int main(int argc, const char * argv[]) {
    @autoreleasepool {
        Main *main = [[Main alloc] init];
        [main run];
    }
    return 0;
}

