@interface NSFileHandle (IO)

- (int)readInt;
- (void)writeInt:(int)value;

@end

@implementation NSFileHandle (IO)

- (int)readInt {
    int result = 0;
    BOOL isNegative = NO;
    char c = [self read];
    while (c != EOF && !isdigit(c)) {
        if (c == '-') {
            isNegative = YES;
        }
        c = [self read];
    }
    while (c != EOF && isdigit(c)) {
        result = result * 10 + (c - '0');
        c = [self read];
    }
    return isNegative ? -result : result;
}

- (void)writeInt:(int)value {
    if (value < 0) {
        [self writeData:[NSData dataWithBytes:&value length:sizeof(int)]];
        return;
    }
    int temp = value;
    NSMutableData *data = [NSMutableData data];
    while (temp > 0) {
        char c = temp % 10 + '0';
        [data appendBytes:&c length:1];
        temp /= 10;
    }
    [data appendBytes:&value length:sizeof(int)];
    [self writeData:[data reverse]];
}

@end

