}

- (NSMutableDictionary<NSNumber *, NSNumber *> *)factorize:(long)num {
    NSMutableDictionary<NSNumber *, NSNumber *> *fact;

    if (num == 1) return [[NSMutableDictionary alloc] init];

    long sqrt = (long)floor(sqrt(num));

    for (NSNumber *p in [self getPrimes:sqrt]) {
        if (num % [p longValue] == 0) {
            fact = [self factorize:num/[p longValue]];
            if (fact[[p longValue]]) {
                fact[[p longValue]] = @(fact[[p longValue]] + 1);
            } else {
                fact[[p longValue]] = @1;
            }
            return fact;
        }
    }

    fact = [[NSMutableDictionary alloc] init];
    fact[@(num)] = @1;
    return fact;
}

+ (NSArray<NSNumber *> *)getPrimes:(long)min {
    static NSMutableArray<NSNumber *> *primes = [NSMutableArray arrayWithObject:@2];

    if ([primes lastObject].longValue < min)
        [self genPrime:min];

    int index = 0;
    for (NSNumber *p in primes) {
        if ([p longValue] > min) break;
        index++;
    }

    return [primes subarrayWithRange:NSMakeRange(0, index)];
}

