    }

    for (id key in self.factorization.allKeys) {
        NSMutableDictionary<NSNumber *, NSNumber *> *copy = [self.factorization mutableCopy];
        copy[key] = nil;
        NSArray<NSNumber *> *divs = [self divisors:copy];
        for (NSNumber *div in divs) {
            for (int i = 0; i <= [self.factorization[key] intValue]; i++) {
