@interface Triangle : NSObject

- (instancetype)initWithA:(CGPoint)a B:(CGPoint)b C:(CGPoint)c;

- (double)getCenterX;
- (double)getCenterY;
- (double)getR;

@end

@implementation Triangle

- (instancetype)initWithA:(CGPoint)a B:(CGPoint)b C:(CGPoint)c {
    self = [super init];
    if (self) {
        self.A = a;
        self.B = b;
        self.C = c;

        self.c = sqrt(pow(a.x - b.x, 2) + pow(a.y - b.y, 2));
        self.a = sqrt(pow(c.x - b.x, 2) + pow(c.y - b.y, 2));
        self.b = sqrt(pow(a.x - c.x, 2) + pow(a.y - c.y, 2));

        self.ang_a = acos((self.b * self.b + self.c * self.c - self.a * self.a) / (2 * self.b * self.c));
        self.ang_b = acos((self.a * self.a + self.c * self.c - self.b * self.b) / (2 * self.a * self.c));
        self.ang_c = acos((self.b * self.b + self.a * self.a - self.c * self.c) / (2 * self.b * self.a));

        self.s2a = sin(2.0 * self.ang_a);
        self.s2b = sin(2.0 * self.ang_b);
        self.s2c = sin(2.0 * self.ang_c);
    }
    return self;
}

- (double)getCenterX {
    double x = (self.A.x * self.s2a + self.B.x * self.s2b + self.C.x * self.s2c) / (self.s2a + self.s2b + self.s2c);
    return x;
}

- (double)getCenterY {
    double y = (self.A.y * self.s2a + self.B.y * self.s2b + self.C.y * self.s2c) / (self.s2a + self.s2b + self.s2c);
    return y;
}

- (double)getR {
    double r = self.a/sin(self.ang_a)/2.0;
    return r;
}

@end

