Point calculateIntersection(double x1, double y1, double x2, double y2, double x3, double y3) {
    Point p;
    double ax = (x1 + x2) / 2.0;
    double ay = (y1 + y2) / 2.0;
    double bx = (x1 + x3) / 2.0;
    double by = (y1 + y3) / 2.0;
    double l1x = x1 - x2;
    double l1y = y1 - y2;
    double l2x = x1 - x3;
    double l2y = y1 - y3;

    p.x = ((ax * l1x + ay * l1y) * l2y + (bx * l2x + by * l2y) * (-l1y)) / (l1x * l2y - l2x * l1y);
    p.y = ((ax * l1x + ay * l1y) * (-l2x) + (bx * l2x + by * l2y) * l1x) / (l1x * l2y - l2x * l1y);

    return p;
}

double calculateRadius(double x1, double y1, double px, double py) {
    return sqrt((px - x1) * (px - x1) + (py - y1) * (py - y1));
}

