#import <Foundation/Foundation.h>

#define SCALE 16

@interface Point : NSObject

@property (nonatomic, strong) NSDecimalNumber *x;
@property (nonatomic, strong) NSDecimalNumber *y;

- (instancetype)initWithX:(NSDecimalNumber *)x y:(NSDecimalNumber *)y;
- (NSDecimalNumber *)calculateTilt:(Point *)opponent;
- (NSDecimalNumber *)calculateDistance:(Point *)opponent;
- (NSArray *)calculateMidperpendicular:(Point *)opponent;
- (Point *)calculateMiddlePoint:(Point *)opponent;

@end

@implementation Point

- (instancetype)initWithX:(NSDecimalNumber *)x y:(NSDecimalNumber *)y {
    self = [super init];
    if (self) {
        _x = x;
        _y = y;
    }
    return self;
}

- (NSDecimalNumber *)calculateTilt:(Point *)opponent {
    NSDecimalNumber *distanceX = [self.x decimalNumberBySubtracting:opponent.x];
    NSDecimalNumber *distanceY = [self.y decimalNumberBySubtracting:opponent.y];

    if ([distanceX compare:0.0] == NSOrderedSame) {
        return nil;
    }

    NSDecimalNumber *tilt = [distanceY decimalNumberByDividingBy:distanceX withBehavior:@{
        NSDecimalNumberRoundingModeKey: NSDecimalNumberRoundingModeHalfUp,
        NSDecimalNumberMaximumFractionDigitsKey: SCALE
    }];
    return tilt;
}

- (NSDecimalNumber *)calculateDistance:(Point *)opponent {
    NSDecimalNumber *distanceX = [self.x decimalNumberBySubtracting:opponent.x];
    NSDecimalNumber *distanceY = [self.y decimalNumberBySubtracting:opponent.y];
    NSDecimalNumber *distance = [distanceX decimalNumberByRaisingToPower:2];
    distance = [distance decimalNumberByAdding:[distanceY decimalNumberByRaisingToPower:2]];
    distance = [distance decimalNumberBySquareRootWithBehavior:@{
        NSDecimalNumberRoundingModeKey: NSDecimalNumberRoundingModeHalfUp,
        NSDecimalNumberMaximumFractionDigitsKey: SCALE
    }];
    return distance;
}

- (NSArray *)calculateMidperpendicular:(Point *)opponent {
    NSDecimalNumber *tilt = [self calculateTilt:opponent];
    Point *middle = [self calculateMiddlePoint:opponent];

    NSArray *equation;
    if (tilt == nil) {
        equation = @[@0.0, @1.0, middle.y];
    } else if ([tilt compare:0.0] == NSOrderedSame) {
        equation = @[@1.0, @0.0, middle.x];
    } else {
        NSDecimalNumber *equation0 = [NSDecimalNumber decimalNumberWithDecimal:[NSDecimalNumber decimalNumberWithDecimal:1.0]];
        equation0 = [equation0 decimalNumberByDividingBy:tilt withBehavior:@{
            NSDecimalNumberRoundingModeKey: NSDecimalNumberRoundingModeHalfUp,
            NSDecimalNumberMaximumFractionDigitsKey: SCALE
        }];
        equation = @[equation0, @1.0, [equation0 decimalNumberByMultiplyingBy:middle.x] decimalNumberByAdding:middle.y];
    }

    return equation;
}

- (Point *)calculateMiddlePoint:(Point *)opponent {
    NSDecimalNumber *TWO = [NSDecimalNumber decimalNumberWithDecimal:2.0];
    NSDecimalNumber *middleX = [self.x decimalNumberByAdding:opponent.x];
    middleX = [middleX decimalNumberByDividingBy:TWO withBehavior:@{
        NSDecimalNumberRoundingModeKey: NSDecimalNumberRoundingModeHalfUp,
        NSDecimalNumberMaximumFractionDigitsKey: SCALE
    }];
    NSDecimalNumber *middleY = [self.y decimalNumberByAdding:opponent.y];
    middleY = [middleY decimalNumberByDividingBy:TWO withBehavior:@{
        NSDecimalNumberRoundingModeKey: NSDecimalNumberRoundingModeHalfUp,
        NSDecimalNumberMaximumFractionDigitsKey: SCALE
    }];
    Point *middlePoint = [[Point alloc] initWithX:middleX y:middleY];
    return middlePoint;
}

@end

@interface Triangle : NSObject

@property (nonatomic, strong) Point *a;
@property (nonatomic, strong) Point *b;
@property (nonatomic, strong) Point *c;

