        _b = [[Point alloc] initWithX:[points[2] decimalNumberValue] y:[points[3] decimalNumberValue]];
        _c = [[Point alloc] initWithX:[points[4] decimalNumberValue] y:[points[5] decimalNumberValue]];
    }
    return self;
}

- (CircumscribedCircle *)calculateCircumscribedCircle {
    NSArray *simultaneousEquation = @[
        [self.a calculateMidperpendicular:self.b],
