    self = [super init];
    if (self) {
        self.x = x;
        self.y = y;
    }
    return self;
}

- (NSNumber *)calculateTilt:(Point *)opponent {
    NSNumber *distanceX = [self.x subtract:opponent.x];
    NSNumber *distanceY = [self.y subtract:opponent.y];

    if ([distanceX compare:0] == NSOrderedSame) {
        return nil;
    }
    return [distanceY divideBy:distanceX scale:SCALE roundingMode:NSNumberRoundingModeHalfUp];
}

- (NSNumber *)calculateDistance:(Point *)opponent {
    NSNumber *distanceX = [self.x subtract:opponent.x];
    NSNumber *distanceY = [self.y subtract:opponent.y];
    return [self sqrt:[distanceX pow:2].add:[distanceY pow:2]]];
}

- (NSArray<NSNumber *> *)calculateMidperpendicular:(Point *)opponent {
    NSNumber *tilt = [self calculateTilt:opponent];
    Point *middle = [self calculateMiddlePoint:opponent];

    NSArray<NSNumber *> *equation = [[NSMutableArray alloc] init];
    if (tilt == nil) {

        equation[0] = [NSNumber numberWithFloat:0];
        equation[1] = [NSNumber numberWithFloat:1];
        equation[2] = middle.y;
    } else if ([tilt compare:0] == NSOrderedSame) {

        equation[0] = [NSNumber numberWithFloat:1];
        equation[1] = [NSNumber numberWithFloat:0];
        equation[2] = middle.x;
    } else {

        equation[0] = [NSNumber numberWithFloat:1 / [tilt floatValue]];
        equation[1] = [NSNumber numberWithFloat:1];
        equation[2] = [equation[0] multiplyBy:middle.x].add(middle.y);
    }

    return equation;
}

- (Point *)calculateMiddlePoint:(Point *)opponent {
    NSNumber *TWO = [NSNumber numberWithFloat:2];
    NSNumber *middleX = [self.x add:opponent.x].divideBy:TWO scale:SCALE roundingMode:NSNumberRoundingModeHalfUp;
    NSNumber *middleY = [self.y add:opponent.y].divideBy:TWO scale:SCALE roundingMode:NSNumberRoundingModeHalfUp;
    return [[Point alloc] initWithX:middleX y:middleY];
}

