#import <Foundation/Foundation.h>
#import <math.h>

@interface Main : NSObject {
    NSInputStream *inputStream;
    NSOutputStream *outputStream;
}

- (void)init;
- (void)main;
- (void)AOJ0010;

@end

@implementation Main

- (void)init {
    [self AOJ0010];
}

- (void)main {
    [self init];
}

- (void)AOJ0010 {
    int n = [[NSInputStream inputStreamWithURL:[NSURL URLWithString:@"http://example.com"]] read];
    while (--n >= 0) {
        [self solve];
    }
}

- (void)solve {
    CGPoint p1 = CGPointMake([[NSInputStream inputStreamWithURL:[NSURL URLWithString:@"http://example.com"]] read], [[NSInputStream inputStreamWithURL:[NSURL URLWithString:@"http://example.com"]] read]);
    CGPoint p2 = CGPointMake([[NSInputStream inputStreamWithURL:[NSURL URLWithString:@"http://example.com"]] read], [[NSInputStream inputStreamWithURL:[NSURL URLWithString:@"http://example.com"]] read]);
    CGPoint p3 = CGPointMake([[NSInputStream inputStreamWithURL:[NSURL URLWithString:@"http://example.com"]] read], [[NSInputStream inputStreamWithURL:[NSURL URLWithString:@"http://example.com"]] read]);
    CGPoint p = [self intersectionPoint:[self perpendicularBisector:p1:p2] [self perpendicularBisector:p2:p3]];
    NSString *result = [NSString stringWithFormat:@"%.3f %.3f %.3f", p.x, p.y, [self distance:p1:p]];
    [outputStream write:[result UTF8String]];
}

- (double)cross:(CGPoint)p1:(CGPoint)p2 {
    return p1.x * p2.y - p2.x * p1.y;
}

- (double)dot:(CGPoint)p1:(CGPoint)p2 {
    return p1.x * p2.x + p2.y * p2.y;
}

- (CGPoint)sum:(CGPoint)p1:(CGPoint)p2 {
    return CGPointMake(p1.x + p2.x, p1.y + p2.y);
}

- (CGPoint)diff:(CGPoint)p1:(CGPoint)p2 {
    return CGPointMake(p1.x - p2.x, p1.y - p2.y);
}

- (CGPoint)mul:(CGPoint)p1:(double)n {
    return CGPointMake(p1.x * n, p1.y * n);
}

- (double)abs:(CGPoint)p1 {
    return sqrt(p1.x * p1.x + p1.y * p1.y);
}

- (double)angleR:(CGPoint)p1:(CGPoint)p2 {
    return acos([self dot:p1:p2] / [self abs:p1] / [self abs:p2]);
}

- (double)angleD:(CGPoint)p1:(CGPoint)p2 {
    return [self angleR:p1:p2] * 180 / M_PI;
}

- (CGPoint)mid:(CGPoint)p1:(CGPoint)p2 {
    return CGPointMake((p1.x + p2.x) / 2, (p1.y + p2.y) / 2);
}

- (Line2D *)perpendicularBisector:(CGPoint)p1:(CGPoint)p2 {
    CGPoint mid = [self mid:p1:p2];
    CGPoint diff = [self diff:p1:p2];
    return [Line2D lineWithStartPoint:mid endPoint:[self sum:mid:CGPointMake(diff.y, -diff.x)]];
}

- (CGPoint)intersectionPoint:(Line2D *)l1:(Line2D *)l2 {
    return [self intersectionPoint:[self perpendicularBisector:l1] [self perpendicularBisector:l2]];
}

- (CGPoint)intersectionPoint:(CGPoint)a1:(CGPoint)a2:(CGPoint)b1:(CGPoint)b2 {
    CGPoint a = [self diff:a2:a1];
    CGPoint b = [self diff:b2:b1];
    return [self sum:a1:CGPointMake([self cross:b:[self diff:b1:a1]] / [self cross:b:a], 0)];
}

- (NSString *)lineToStr:(Line2D *)l {
    return [NSString stringWithFormat:@"Line2D %@-%@", l.startPoint, l.endPoint];
}

