#import <Foundation/Foundation.h>
#import <math.h>

@interface Main : NSObject
{
    NSInputStream *inputStream;
    NSOutputStream *outputStream;
}

- (void)run;

@end

@implementation Main

- (void)run {
    NSFileHandle *fileHandle = [NSFileHandle fileHandleForReadingAtPath:@"/dev/stdin"];
    inputStream = [NSInputStream inputStreamWithFileHandle:fileHandle];
    outputStream = [NSOutputStream outputStreamWithFileHandle:fileHandle];

    [inputStream open];
    [outputStream open];

    while (YES) {
        NSString *line = [[NSString alloc] initWithData:[inputStream readDataToEndOfFile] encoding:NSUTF8StringEncoding];
        if (line.length == 0) {
            break;
        }

        NSArray *components = [line componentsSeparatedByString:@" "];
        int n = [components[0] intValue];
        for (int i = 0; i < n; i++) {
            double x1 = [components[1 + i * 3] doubleValue];
            double y1 = [components[2 + i * 3] doubleValue];
            double x2 = [components[3 + i * 3] doubleValue];
            double y2 = [components[4 + i * 3] doubleValue];
            double x3 = [components[5 + i * 3] doubleValue];
            double y3 = [components[6 + i * 3] doubleValue];

            double a = x1 - x2;
            double b = y1 - y2;
            double c = x2 - x3;
            double d = y2 - y3;

            double det = a * d - b * c;
            if (fabs(det) < 1e-8) {
                NSLog(@"Invalid input");
                continue;
            }

            double x = (d * (a * x1 + b * y1) - b * (c * x1 + d * y1)) / det;
            double y = (a * (c * x1 + d * y1) - c * (a * x1 + b * y1)) / det;

            double distance = sqrt(pow(x - x1, 2) + pow(y - y1, 2));

            NSString *output = [NSString stringWithFormat:@"%.3f %.3f %.3f\n", x, y, distance];
            [outputStream write:[output UTF8String] maxLength:output.length];
        }
    }

    [inputStream close];
    [outputStream close];
}

@end

int main(int argc, const char * argv[]) {
    @autoreleasepool {
        Main *main = [[Main alloc] init];
        [main run];
    }
    return 0;
}

