- (void)solve {
    CGPoint p1 = CGPointMake([[NSDouble alloc] init], [[NSDouble alloc] init]);
    p1.x = [p1.x doubleValue];
    p1.y = [p1.y doubleValue];

    CGPoint p2 = CGPointMake([[NSDouble alloc] init], [[NSDouble alloc] init]);
    p2.x = [p2.x doubleValue];
    p2.y = [p2.y doubleValue];

    CGPoint p3 = CGPointMake([[NSDouble alloc] init], [[NSDouble alloc] init]);
    p3.x = [p3.x doubleValue];
    p3.y = [p3.y doubleValue];

    CGPoint mid1 = CGPointMake([[NSDouble alloc] init], [[NSDouble alloc] init]);
    mid1.x = (p1.x + p2.x) / 2;
    mid1.y = (p1.y + p2.y) / 2;

    CGPoint mid2 = CGPointMake([[NSDouble alloc] init], [[NSDouble alloc] init]);
    mid2.x = (p2.x + p3.x) / 2;
    mid2.y = (p2.y + p3.y) / 2;

    CGPoint diff1 = CGPointMake([[NSDouble alloc] init], [[NSDouble alloc] init]);
    diff1.x = p2.x - p1.x;
    diff1.y = p2.y - p1.y;

    CGPoint diff2 = CGPointMake([[NSDouble alloc] init], [[NSDouble alloc] init]);
    diff2.x = p3.x - p2.x;
    diff2.y = p3.y - p2.y;

    CGPoint intersection = CGPointMake([[NSDouble alloc] init], [[NSDouble alloc] init]);
    intersection.x = mid1.x + (diff1.x * (cross(diff2, diff1) / cross(diff2, diff1)));
    intersection.y = mid1.y + (diff1.y * (cross(diff2, diff1) / cross(diff2, diff1)));

    NSLog(@"%.3f %.3f %.3f", intersection.x, intersection.y, sqrt(pow(intersection.x - p1.x, 2) + pow(intersection.y - p1.y, 2)));
}

- (double)cross:(CGPoint)p1 p2:(CGPoint)p2 {
    return p1.x * p2.y - p2.x * p1.y;
}

- (double)dot:(CGPoint)p1 p2:(CGPoint)p2 {
    return p1.x * p2.x + p2.y * p2.y;
}

- (CGPoint)sum:(CGPoint)p1 p2:(CGPoint)p2 {
    return CGPointMake(p1.x + p2.x, p1.y + p2.y);
}

- (CGPoint)diff:(CGPoint)p1 p2:(CGPoint)p2 {
    return CGPointMake(p1.x - p2.x, p1.y - p2.y);
}

- (CGPoint)mul:(CGPoint)p1 n:(double)n {
    return CGPointMake(p1.x * n, p1.y * n);
}

- (double)abs:(CGPoint)p1 {
    return sqrt(p1.x * p1.x + p1.y * p1.y);
}

- (double)angleR:(CGPoint)p1 p2:(CGPoint)p2 {
    return acos(dot(p1, p2) / abs(p1) / abs(p2));
}

- (double)angleD:(CGPoint)p1 p2:(CGPoint)p2 {
    return (180.0 / M_PI) * angleR(p1, p2);
}

- (CGPoint)mid:(CGPoint)p1 p2:(CGPoint)p2 {
    return CGPointMake((p1.x + p2.x) / 2, (p1.y + p2.y) / 2);
}

- (CGPoint)perpendicularBisector:(CGPoint)p1 p2:(CGPoint)p2 {
    CGPoint mid = [self mid:p1 p2:p2];
    CGPoint diff = [self diff:p1 p2:p2];
    return CGPointMake(mid.x, mid.y + diff.x);
}

- (CGPoint)intersectionPoint:(CGPoint)a1 a2:(CGPoint)a2 b1:(CGPoint)b1 b2:(CGPoint)b2 {
    CGPoint a = [self diff:a2 p2:a1];
    CGPoint b = [self diff:b2 p2:b1];
    return [self sum:a1 p2:[self mul:a n:(cross(b, [self diff:b1 a1]) / cross(b, a))]];
}

