- (void)solve {
    Point2D *p1 = [[Point2D alloc] initWithCGPoint:[self readPoint]];
    Point2D *p2 = [[Point2D alloc] initWithCGPoint:[self readPoint]];
    Point2D *p3 = [[Point2D alloc] initWithCGPoint:[self readPoint]];
    Line2D *l1 = [self perpendicularBisector:p1 p2:p2];
    Line2D *l2 = [self perpendicularBisector:p2 p2:p3];
    Point2D *p = [self intersectionPoint:l1 l2:l2];
    double distance = CGVectorDistance(CGVectorMake(p1.x - p.x, p1.y - p.y), CGVectorZero);
    NSString *output = [NSString stringWithFormat:@"%.3f %.3f %.3f\n", p.x, p.y, distance];
    [_outputStream write:[output UTF8String] maxLength:[output length]];
}

- (Line2D *)perpendicularBisector:(Point2D *)p1 p2:(Point2D *)p2 {
    Point2D *mid = [[Point2D alloc] initWithCGPoint:CGPointMake((p1.x + p2.x) / 2, (p1.y + p2.y) / 2)];
    CGPoint diff = CGPointMake(p2.x - p1.x, p2.y - p1.y);
    CGPoint perpendicular = CGPointMake(diff.y, -diff.x);
    return [[Line2D alloc] initWithStartPoint:mid endPoint:CGPointMake(mid.x + perpendicular.x, mid.y + perpendicular.y)];
}

- (Point2D *)intersectionPoint:(Line2D *)l1 l2:(Line2D *)l2 {
    CGPoint a1 = l1.startPoint, a2 = l1.endPoint;
    CGPoint b1 = l2.startPoint, b2 = l2.endPoint;
    CGPoint a = CGPointMake(a2.x - a1.x, a2.y - a1.y);
    CGPoint b = CGPointMake(b2.x - b1.x, b2.y - b1.y);
    CGPoint diff = CGPointMake(b1.x - a1.x, b1.y - a1.y);
    CGPoint intersection = CGPointMake(a1.x + a.x * (b.x * diff.y - b.y * diff.x) / (b.x * a.y - b.y * a.x), a1.y + a.y * (b.x * diff.y - b.y * diff.x) / (b.x * a.y - b.y * a.x));
    return [[Point2D alloc] initWithCGPoint:intersection];
}

- (CGPoint)readPoint {
    double x, y;
    [_inputStream read:&x maxLength:sizeof(double)];
    [_inputStream read:&y maxLength:sizeof(double)];
    return CGPointMake(x, y);
}
