- (Line2D *)perpendicularBisector:(Line2D *)l {
    Point2D *mid = [self mid:l];
    Point2D *diff = [[Point2D alloc] initWithX:(l.p2.x - l.p1.x) y:(l.p2.y - l.p1.y)];
    Point2D *newPoint = [[Point2D alloc] initWithX:mid.x + diff.y y:mid.y - diff.x];
    Line2D *perpendicularBisector = [[Line2D alloc] initWithP1:mid p2:newPoint];
    return perpendicularBisector;
