- (Point2D *)intersectionPoint:(Line2D *)l1 l2:(Line2D *)l2 {
    Point2D *a = [[Point2D alloc] initWithX:l1.p2.x - l1.p1.x y:l1.p2.y - l1.p1.y];
    Point2D *b = [[Point2D alloc] initWithX:l2.p2.x - l2.p1.x y:l2.p2.y - l2.p1.y];
    Point2D *diff = [[Point2D alloc] initWithX:l2.p1.x - l1.p1.x y:l2.p1.y - l1.p1.y];
    double crossAB = a.x * b.y - b.x * a.y;
    double crossBdiff = b.x * diff.y - diff.x * b.y;
    double t = crossBdiff / crossAB;
    Point2D *intersectionPoint = [[Point2D alloc] initWithX:l1.p1.x + t * a.x y:l1.p1.y + t * a.y];
    return intersectionPoint;
}
