double getPointX(double x1, double y1, double x2, double y2, double x3, double y3) {
    double a1 = 2 * (x2 - x1);
    double b1 = 2 * (y2 - y1);
    double c1 = (x1 * x1) - (x2 * x2) + (y1 * y1) - (y2 * y2);
    double a2 = 2 * (x3 - x1);
    double b2 = 2 * (y3 - y1);
    double c2 = (x1 * x1) - (x3 * x3) + (y1 * y1) - (y3 * y3);

    double numerator = b1 * c2 - b2 * c1;
    double denominator = a1 * b2 - a2 * b1;

    return numerator / denominator;
}

double getPointY(double x1, double y1, double x2, double y2, double x3, double y3) {
    double a1 = 2 * (x2 - x1);
    double b1 = 2 * (y2 - y1);
    double c1 = (x1 * x1) - (x2 * x2) + (y1 * y1) - (y2 * y2);
    double a2 = 2 * (x3 - x1);
    double b2 = 2 * (y3 - y1);
    double c2 = (x1 * x1) - (x3 * x3) + (y1 * y1) - (y3 * y3);

    double numerator = c1 * a2 - c2 * a1;
    double denominator = a1 * b2 - a2 * b1;

    return numerator / denominator;
}

double getDistance(double x1, double y1, double x2, double y2) {
    double distanceX = fabs(x1 - x2);
    double squareX = distanceX * distanceX;

    double distanceY = fabs(y1 - y2);
    double squareY = distanceY * distanceY;

    return sqrt(squareX + squareY);
}

