		double [] result = new double[2];
		double temp1 = a * e - d * b;
		double temp2 = c * e - f * b;
		double x = temp2 / temp1;
		double y = ((double)c - x * a) / b;
		if(x == -0.0){
			x = 0.0;
		}
		result[0] = x;
		result[1] = y;
