		if (!Double.isInfinite(a)) {
			b = p1.y - a * p1.x;
		} else {
			b = Double.NaN;
		}
		c = e2;
		if (!Double.isInfinite(c)) {
			d = p2.y - c * p2.x;
		} else {
			d = Double.NaN;
		}

		if (!Double.isNaN(b) && !Double.isNaN(d)) {
			x = (d - b) / (a - c);
			y = (a * d - b * c) / (a - c);
		} else if (Double.isNaN(b)) {
			x = p1.x;
			y = c * x + d;
		} else if (Double.isNaN(d)) {
			x = p2.x;
			y = a * x + b;
		}

		return new Point2D.Double(x, y);
	}
