        return INFINITY;
    }
    return -(b.x - a.x) / (b.y - a.y);
}

NSPoint makeSolution (NSPoint p1, double e1, NSPoint p2, double e2) {
    double a, b, c, d;
    double x = 0.0, y = 0.0;

    a = e1;
    if (!isinf(a)) {
        b = p1.y - a * p1.x;
