            slope2 = getSlope(bX, bY, cX, cY);

            solveX = makeSolutionX(middle1X, slope1, middle2X, slope2);
            solveY = makeSolutionY(middle1X, slope1, middle2X, slope2);

            r = sqrt((solveX - aX) * (solveX - aX) + (solveY - aY) * (solveY - aY));

