double getSlope(double x1, double y1, double x2, double y2) {
    if (y1 == y2) {
        return INFINITY;
    }
    return -(x2 - x1) / (y2 - y1);
}

double makeSolutionX(double p1X, double e1, double p2X, double e2) {
    double a, b, c, d;
    double x = 0.0;

    a = e1;
    if (!isinf(a)) {
        b = p1X - a * p1X;
    } else {
        b = NAN;
    }
    c = e2;
    if (!isinf(c)) {
        d = p2X - c * p2X;
    } else {
        d = NAN;
    }

    if (!isnan(b) && !isnan(d)) {
        x = (d - b) / (a - c);
    } else if (isnan(b)) {
        x = p1X;
    } else if (isnan(d)) {
        x = p2X;
    }

    return x;
}

double makeSolutionY(double p1X, double e1, double p2X, double e2) {
    double a, b, c, d;
    double y = 0.0;

    a = e1;
    if (!isinf(a)) {
        b = p1X - a * p1X;
    } else {
        b = NAN;
    }
    c = e2;
    if (!isinf(c)) {
        d = p2X - c * p2X;
    } else {
        d = NAN;
    }

    if (!isnan(b) && !isnan(d)) {
        y = (a * d - b * c) / (a - c);
    } else if (isnan(b)) {
        y = c * p1X + d;
    } else if (isnan(d)) {
        y = a * p2X + b;
    }

    return y;
}

