double getSlope(NSPoint a, NSPoint b) {
    if (a.y == b.y) {
        return DBL_MAX;
    }
    return -(b.x - a.x) / (b.y - a.y);
}

NSPoint makeSolution (NSPoint p1, double e1, NSPoint p2, double e2) {
    double a, b, c, d;
    double x = 0.0, y = 0.0;

    a = e1;
    if (!isinf(a)) {
        b = p1.y - a * p1.x;
    } else {
        b = NAN;
    }
    c = e2;
    if (!isinf(c)) {
        d = p2.y - c * p2.x;
    } else {
        d = NAN;
    }

    if (!isnan(b) && !isnan(d)) {
        x = (d - b) / (a - c);
        y = (a * d - b * c) / (a - c);
    } else if (isnan(b)) {
        x = p1.x;
        y = c * x + d;
    } else if (isnan(d)) {
        x = p2.x;
        y = a * x + b;
    }

    return NSMakePoint(x, y);
}

