        double a2 = x3 - x2;
        double b1 = y2 - y1;
        double b2 = y3 - y2;
        double c1 = -(x2 * x2 - x1 * x1 + y2 * y2 - y1 * y1) / 2;
        double c2 = -(x3 * x3 - x2 * x2 + y3 * y3 - y2 * y2) / 2;
        double x = (b1 * c2 - b2 * c1) / (a1 * b2 - a2 * b1);
        double y = (a2 * c1 - a1 * c2) / (a1 * b2 - a2 * b1);
        double r = sqrt((x - x1) * (x - x1) + (y - y1) * (y - y1));
        NSString *result = [NSString stringWithFormat:@"%.3f %.3f %.3f", x, y, r];
        [out write:[result UTF8String] maxLength:[result length]];
    }
}

