- (int)max:(NSArray *)ar {
    NSArray *sortedArray = [ar sortedArrayUsingComparator:^NSComparisonResult(id obj1, id obj2) {
        return [obj1 compare:obj2];
    }];
    return [sortedArray lastObject];
}

- (int)min:(NSArray *)ar {
    NSArray *sortedArray = [ar sortedArrayUsingComparator:^NSComparisonResult(id obj1, id obj2) {
        return [obj1 compare:obj2];
    }];
    return [sortedArray firstObject];
}

- (long long)gcd:(long long)a b:(long long)b {
    return b>0? [self gcd:b a:(a%b)]:a;
}

- (long long)lcm:(long long)a b:(long long)b {
    return a/gcd(a,b)*b;
}

