    return sqrt((p1.x-p2.x)*(p1.x-p2.x) + (p1.y-p2.y)*(p1.y-p2.y));
}

- (BOOL)isPrime:(int)n {
    if (n==2) return YES;
    if (n<2 || n%2==0) return NO;
    for (int i=3; i<=sqrt(n); i+=2) if(n%i==0) return NO;
    return YES;
}

