            final Point2D circumcenter = circumcircle.getCenter();
            final double radius = circumcircle.getRadius();

            System.out.printf("%.3f ", circumcenter.getX());
            System.out.printf("%.3f ", circumcenter.getY());
            System.out.printf("%.3f\n", radius);
        }
    }

