        _a = a;
        _b = b;
        _c = c;
    }
    return self;
}

+ (NSArray *)solve:(Equation *)left right:(Equation *)right {
    double determinant = left.a * right.b - right.a * left.b;
    double x = (right.b * left.c - left.b * right.c) / determinant;
    double y = (-right.a * left.c + left.a * right.c) / determinant;

    return @[@(x), @(y)];
}

