        P *y = [[P alloc] init];
        P *z = [[P alloc] init];

        if (fabs(m01->y) > 0.0000001) {
            double m1 = -m01->x / m01->y;
            x->x = -m1;
            y->x = 1.0;
            z->x = -g01->x * m1 + g01->y;
        } else {
            x->x = 1.0;
            y->x = 0.0;
            z->x = g01->x;
