    NSOutputStream *outputStream = [[NSOutputStream alloc] initWithFileAtPath:@"/dev/stdout"];
    [inputStream open];
    [outputStream open];
    self.stream = [NSStream inputStreamWithFileAtPath:@"/dev/stdin"];
    self.stream.delegate = self;
    [self.stream scheduleInRunLoop:[NSRunLoop currentRunLoop] forMode:NSDefaultRunLoopMode];
    [self.stream open];
    [self performSelector:@selector(readLine:) withObject:nil afterDelay:0.0];
}

- (void)readLine:(NSString *)line {
    NSArray *tokens = [line componentsSeparatedByString:@" "];
    int n = [tokens count];
    for (int i = 0; i < n; i++) {
        P *p = [[P alloc] init];
        p.x = [tokens[i] doubleValue];
        p.y = [tokens[i+1] doubleValue];
        P *g01 = [[P alloc] initWithX:([p.x add:p.x] / 2.0) y:([p.y add:p.y] / 2.0)];
        P *m01 = [[P alloc] initWithX:([p.x sub:p.x]) y:([p.y sub:p.y])];
        P *x = [[P alloc] initWithX:0.0 y:0.0];
        P *y = [[P alloc] initWithX:1.0 y:1.0];
        P *z = [[P alloc] initWithX:0.0 y:0.0];
        if (fabs(m01.y) > 0.0000001) {
            double m1 = -m01.x / m01.y;
            x.x = -m1;
            y.x = 1.0;
            z.x = -g01.x * m1 + g01.y;
        } else {
            x.x = 1.0;
            y.x = 0.0;
            z.x = g01.x;
        }
        P *g02 = [[P alloc] initWithX:([p.x add:p.x] / 2.0) y:([p.y add:p.y] / 2.0)];
        P *m02 = [[P alloc] initWithX:([p.x sub:p.x]) y:([p.y sub:p.y])];
        if (fabs(m02.y) > 0.0000001) {
            double m2 = -m02.x / m02.y;
            x.y = -m2;
            y.y = 1.0;
            z.y = -g02.x * m2 + g02.y;
        } else {
            x.y = 1.0;
            y.y = 0.0;
            z.y = g02.x;
        }
        double det = [x vec:y];
        double xx = [z vec:y] / det;
        double yy = [x vec:z] / det;
        double rr = [P alloc] abs:([P alloc] sub:([P alloc] initWithX:xx y:yy) p:([P alloc] initWithX:p.x y:p.y)]);
        NSString *xxx = [NSString stringWithFormat:@"%.3f", xx];
        NSString *yyy = [NSString stringWithFormat:@"%.3f", yy];
        NSString *zzz = [NSString stringWithFormat:@"%.3f", rr];
        NSLog(@"%@", [NSString stringWithFormat:@"%@ %@ %@", xxx, yyy, zzz]);
    }
}

