@implementation NSInputStream (CustomMethods)
- (int)readInt {
    int result = 0;
    int sign = 1;
    BOOL isNegative = NO;

    while (YES) {
        char c = [self read];
        if (c == '-') {
            isNegative = YES;
        } else if (c >= '0' && c <= '9') {
            result = result * 10 + (c - '0');
        } else {
            break;
        }
    }

    if (isNegative) {
        result = -result;
    }

    return result;
}

- (NSString *)readLine {
    NSMutableString *result = [NSMutableString string];
    while (YES) {
        char c = [self read];
        if (c == '\n') {
            break;
        } else {
            [result appendFormat:@"%c", c];
        }
    }
    return result;
}
