    @autoreleasepool {
        NSMutableArray *line_list = [NSMutableArray array];

        NSInputStream *inputStream = [[NSInputStream alloc] initWithFileAtPath:@"/dev/stdin"];
        [inputStream open];

        NSMutableString *input = [NSMutableString string];
        while ([inputStream hasBytesAvailable]) {
            char buffer[1024];
            NSInteger bytesRead = [inputStream read:buffer maxLength:sizeof(buffer)];
            if (bytesRead > 0) {
                [input appendString:[NSString stringWithUTF8String:buffer]];
            }
        }
        [inputStream close];

        NSArray *lines = [input componentsSeparatedByString:@"\n"];
        NSInteger low = [[lines[0] componentsSeparatedByString:@" "] firstObject].intValue;
        NSInteger line = [[lines[1] componentsSeparatedByString:@" "] firstObject].intValue;

        for (NSInteger i = 2; i < lines.count; i++) {
            NSString *str1 = lines[i];
            NSString *str2 = [NSString stringWithFormat:@",%ld", i-2];
            str1 = [str1 stringByAppendingString:str2];
            [line_list addObject:str1];
        }

        NSInteger now, priority, list_n, list_a, list_p;
        NSMutableArray *res = [NSMutableArray arrayWithCapacity:low];

        for (NSInteger i = 0; i < low; i++) {
            [res addObject:@0];
        }

        for (NSInteger i = 1; i <= low; i++) {
            priority = -1;
            now = i;
            for (NSInteger j = 0; j < line_list.count; j++) {
                NSArray *strAry = [line_list[j] componentsSeparatedByString:@","];
                list_n = [[strAry[0] componentsSeparatedByString:@" "] firstObject].intValue;
                list_a = [[strAry[1] componentsSeparatedByString:@" "] firstObject].intValue;
                list_p = [[strAry[2] componentsSeparatedByString:@" "] firstObject].intValue;
                if (now == list_n && priority < list_p) {
                    now = list_a;
                    priority = list_p;
                    j = 0;
                }
                if (now == list_a && priority < list_p) {
                    now = list_n;
                    priority = list_p;
                    j = 0;
                }
                else if (priority == (line - 1)) {
                    break;
                }
            }
            [res replaceObjectAtIndex:now-1 withObject:@(i)];
        }

        for (NSInteger i = 0; i < res.count; i++) {
            NSLog(@"%@", res[i]);
        }
    }
    return 0;
}

