        int w = sc.nextInt();
        int n = sc.nextInt();
        List<Integer> list = new ArrayList<>();
        java.util.stream.IntStream.range(1,w+1).forEach(item->list.add(item));
        for(int i=0;i<n;i++)
        {
            SwapAt(list,sc.nextInt(),sc.nextInt());
        }
        for(int item:list)System.out.println(item);
	}

