#import <stdio.h>
#import <math.h>

double EPS = 1.0e-8;

double cross(Point2D *p1, Point2D *p2) {
    return p1->x * p2->y - p2->x * p1->y;
}

double dot(Point2D *p1, Point2D *p2) {
    return p1->x * p2->x + p1->y * p2->y;
}

Point2D sum(Point2D *p1, Point2D *p2) {
    return (Point2D){p1->x + p2->x, p1->y + p2->y};
}

Point2D diff(Point2D *p1, Point2D *p2) {
    return (Point2D){p1->x - p2->x, p1->y - p2->y};
}

Point2D mul(Point2D *p1, double n) {
    return (Point2D){p1->x * n, p1->y * n};
}

double norm(Point2D *p1) {
    return p1->x * p1->x + p1->y * p1->y;
}

double abs(Point2D *p1) {
    return sqrt(norm(p1));
}

double angleR(Point2D *p1, Point2D *p2) {
    return acos(dot(p1, p2) / abs(p1) / abs(p2));
}

double angleD(Point2D *p1, Point2D *p2) {
    return degrees(angleR(p1, p2));
}

Point2D mid(Line2D *l1) {
    return mid(l1->p1, l1->p2);
}

Point2D mid(Point2D *p1, Point2D *p2) {
    return (Point2D){(p1->x + p2->x) / 2, (p1->y + p2->y) / 2};
}

Line2D perpendicularBisector(Line2D *l1) {
    return perpendicularBisector(l1->p1, l1->p2);
}

Line2D perpendicularBisector(Point2D *p1, Point2D *p2) {
    Point2D mid = mid(p1, p2);
    Point2D diff = diff(p1, p2);
    return (Line2D){mid, sum(mid, (Point2D){diff.y, -diff.x})};
}

bool intersectLL(Line2D *l1, Line2D *l2) {
    return intersectLL(l1->p1, l1->p2, l2->p1, l2->p2);
}

bool intersectLL(Point2D *a1, Point2D *a2, Point2D *b1, Point2D *b2) {
    return (fabs(cross(diff(a2, a1), diff(b2, b1))) > EPS) || (fabs(cross(diff(a2, a1), diff(a1, b1))) < EPS);
}

Point2D intersectionPoint(Line2D *l1, Line2D *l2) {
    return intersectionPoint(l1->p1, l1->p2, l2->p1, l2->p2);
}

Point2D intersectionPoint(Point2D *a1, Point2D *a2, Point2D *b1, Point2D *b2) {
    Point2D a = diff(a2, a1);
    Point2D b = diff(b2, b1);
    return sum(a1, mul(&a, cross(&b, diff(b1, a1)) / cross(&b, &a)));
}

NSString *lineToStr(Line2D *l) {
    return [NSString stringWithFormat:@"Line2D %@-%@", NSStringFromCGPoint(l->p1), NSStringFromCGPoint(l->p2)];
}

