                matrix[ipv][j] = matrix[row][j];
                matrix[row][j] = temp;
            }
        }

        double inv_pv = 1.0/matrix[ipv][ipv];
        for (int j = 0; j < n; j++) {
            matrix[ipv][j] *= inv_pv;
        }

        for (int i = 0; i < n; i++) {
            if (i != ipv) {
                double temp = matrix[i][ipv];
                for (int j = 0; j < n; j++) {
