@implementation Matrix {
    NSUInteger _rows;
    NSUInteger _columns;
    double *_data;
}

- (instancetype)initWithRows:(NSUInteger)rows columns:(NSUInteger)columns {
    self = [super init];
    if (self) {
        _rows = rows;
        _columns = columns;
        _data = (double *)malloc(rows * columns * sizeof(double));
        memset(_data, 0, rows * columns * sizeof(double));
    }
    return self;
}

- (void)setElement:(double)value atRow:(NSUInteger)row column:(NSUInteger)column {
    if (row < _rows && column < _columns) {
        _data[row * _columns + column] = value;
    }
}

- (double)elementAtRow:(NSUInteger)row column:(NSUInteger)column {
    if (row < _rows && column < _columns) {
        return _data[row * _columns + column];
    }
    return 0.0;
}

- (void)swapRows:(NSUInteger)row1 row2:(NSUInteger)row2 {
    if (row1 < _rows && row2 < _rows) {
        for (NSUInteger col = 0; col < _columns; col++) {
            double temp = _data[row1 * _columns + col];
            _data[row1 * _columns + col] = _data[row2 * _columns + col];
            _data[row2 * _columns + col] = temp;
        }
    }
}

- (void)scaleRow:(NSUInteger)row byFactor:(double)factor {
    if (row < _rows) {
        for (NSUInteger col = 0; col < _columns; col++) {
            _data[row * _columns + col] *= factor;
        }
    }
}

- (void)addRow:(NSUInteger)row1 scaledBy:(double)scale toRow:(NSUInteger)row2 {
    if (row1 < _rows && row2 < _rows) {
        for (NSUInteger col = 0; col < _columns; col++) {
            _data[row2 * _columns + col] += scale * _data[row1 * _columns + col];
        }
    }
}

- (void)solve {
    for (NSUInteger ipv = 0; ipv < _rows; ipv++) {
        double max = 0.0;
        NSUInteger row = 0;
        for (NSUInteger i = ipv; i < _rows; i++) {
            double absValue = fabs([self elementAtRow:i column:ipv]);
            if (absValue > max) {
                max = absValue;
                row = i;
            }
        }
        if (max == 0.0) {
            break;
        }
        if (ipv != row) {
            [self swapRows:ipv row2:row];
        }

        double inv_pv = 1.0 / [self elementAtRow:ipv column:ipv];
        [self scaleRow:ipv byFactor:inv_pv];

        for (NSUInteger i = 0; i < _rows; i++) {
            if (i != ipv) {
                double temp = [self elementAtRow:i column:ipv];
                [self addRow:ipv scaledBy:-temp toRow:i];
            }
        }
    }
}

