@implementation FastScanner

- (instancetype)initWithInputStream:(NSInputStream *)stream {
    self = [super init];
    if (self) {
        _in = stream;
    }
    return self;
}

- (BOOL)hasNextByte {
    if (_p < _length) {
        return YES;
    } else {
        _p = 0;
        _length = [_in read:_buffer maxLength:1024];
        if (_length <= 0) {
            return NO;
        }
    }
    return YES;
}

- (int)readByte {
    if ([self hasNextByte]) {
        return _buffer[_p++];
    }
    return -1;
}

- (BOOL)isPrintable:(int)n {
    return 33 <= n && n <= 126;
}

- (void)skip {
    while ([self hasNextByte] && ![self isPrintable:[self readByte]]) {
        _p++;
    }
}

- (BOOL)hasNext {
    [self skip];
    return [self hasNextByte];
}

- (NSString *)next {
    if (![self hasNext]) {
        [NSException raise:NSGenericException format:@"No more elements"];
    }
    NSMutableString *sb = [NSMutableString string];
    int t = [self readByte];
    while ([self isPrintable:t]) {
        [sb appendString:[NSString stringWithFormat:@"%c", t]];
        t = [self readByte];
    }
    return sb;
}

- (NSArray *)nextArray:(int)n {
    NSMutableArray *ar = [NSMutableArray arrayWithCapacity:n];
    for (int i = 0; i < n; i++) {
        [ar addObject:[self next]];
    }
    return ar;
}

- (int)nextInt {
    return [self nextInt];
}

- (NSArray *)nextIntArray:(int)n {
    NSMutableArray *ar = [NSMutableArray arrayWithCapacity:n];
    for (int i = 0; i < n; i++) {
        [ar addObject:[NSNumber numberWithInt:[self nextInt]]];
    }
    return ar;
}

- (long long)nextLong {
    if (![self hasNext]) {
        [NSException raise:NSGenericException format:@"No more elements"];
    }
    BOOL minus = NO;
    int temp = [self readByte];
    if (temp == '-') {
        minus = YES;
        temp = [self readByte];
    }
    if (temp < '0' || '9' < temp) {
        [NSException raise:NSGenericException format:@"Invalid number format"];
    }
    long long n = 0;
    while ([self isPrintable:temp]) {
        if ('0' <= temp && temp <= '9') {
            n *= 10;
            n += temp - '0';
        } else {
            [NSException raise:NSGenericException format:@"Invalid number format"];
        }
        temp = [self readByte];
    }
    return minus ? -n : n;
}

- (NSArray *)nextLongArray:(int)n {
    NSMutableArray *ar = [NSMutableArray arrayWithCapacity:n];
    for (int i = 0; i < n; i++) {
        [ar addObject:[NSNumber numberWithLongLong:[self nextLong]]];
    }
    return ar;
}

- (double)nextDouble {
    return [self nextDouble];
}

- (NSArray *)nextDoubleArray:(int)n {
    NSMutableArray *ar = [NSMutableArray arrayWithCapacity:n];
    for (int i = 0; i < n; i++) {
        [ar addObject:[NSNumber numberWithDouble:[self nextDouble]]];
    }
    return ar;
}

- (void)close {
    [_in close];
}

@end

