                NSInteger removed = [dq removeFirst];
                [out writeData:[NSString stringWithFormat:@"%ld\n", (long)removed].dataUsingEncoding:NSUTF8StringEncoding]];
            }
            else {
                [dq addFirst:temp];
            }
        }
