@implementation Main

- (void)run:(NSInputStream *)in out:(NSOutputStream *)out {
    NSInputStream *stream = in;
    NSOutputStream *output = out;
    NSInteger n;
    NSMutableArray *stack = [NSMutableArray arrayWithCapacity:20];
    [stream open];
    [output open];
    while ([stream hasBytesAvailable]) {
        [stream read:&n maxLength:sizeof(n)];
        if (n != 0) {
            [stack addObject:@(n)];
        } else {
            NSInteger popped = [[stack lastObject] integerValue];
            [stack removeLastObject];
            [output write:&popped maxLength:sizeof(popped)];
        }
    }
    [stream close];
    [output close];
}

@end

