    NSMutableArray *a = [NSMutableArray arrayWithCapacity:n+1];
    for (int i = 0; i <= n; i++) {
        [a addObject:@(i)];
    }
    [a replaceObjectAtIndex:0 withObject:@NO];
    [a replaceObjectAtIndex:1 withObject:@NO];

    for (int i = 2; i < (n - 3) / 2; i++) {
        if ([a objectAtIndex:i] == @YES) {
            for (int j = 2; j * i <= n; j++) {
                [a replaceObjectAtIndex:j * i withObject:@NO];
