@implementation BigNumber

- (instancetype)init {
    self = [super init];
    if (self) {
        self.numberList = [[NSMutableArray alloc] init];
    }
    return self;
}

- (NSInteger)getDigits {
    NSInteger size = self.numberList.count;
    NSInteger digits = (size - 1) * 9;
    NSInteger highValue = [self.numberList lastObject];
    digits += [self getDigitsOfNumber:highValue];
    return digits;
}

- (instancetype)parse:(NSString *)valueText {
    BigNumber *number = [[BigNumber alloc] init];

    while (![valueText isEqualToString:@""]) {
        NSInteger size = [valueText length];
        NSInteger end = MIN(size, 9);

        NSString *token = [valueText substringFromIndex:size - end];
        valueText = [valueText substringToIndex:size - end];
        [number.numberList addObject:[NSNumber numberWithInt:[token integerValue]]];
    }

    return number;
}

- (instancetype)add:(BigNumber *)a b:(BigNumber *)b {
    BigNumber *number = [[BigNumber alloc] init];

    NSInteger carryValue = 0;
    for (NSInteger i = 0; i < a.numberList.count || i < b.numberList.count; i++) {
        NSInteger value = carryValue;
        carryValue = 0;

        if (i < a.numberList.count) {
            value += [a.numberList[i] integerValue];
        }
        if (i < b.numberList.count) {
            value += [b.numberList[i] integerValue];
        }

