#import <Foundation/Foundation.h>

@interface BigInteger : NSObject

@property (nonatomic, strong) NSData *ds;

- (instancetype)initWithData:(NSData *)data;
+ (BOOL)isABiggerThanB:(BigInteger *)a by:(BigInteger *)b;
+ (BigInteger *)sum:(BigInteger *)i1 by:(BigInteger *)i2;
+ (BigInteger *)subsum:(BigInteger *)i1 by:(BigInteger *)i2;

@end

@implementation BigInteger

- (instancetype)initWithData:(NSData *)data {
    self = [super init];
    if (self) {
        self.ds = data;
    }
    return self;
}

+ (BOOL)isABiggerThanB:(BigInteger *)a by:(BigInteger *)b {
    if ([a.ds length] > [b.ds length]) return YES;
    else if ([a.ds length] < [b.ds length]) return NO;
    else {
        return [[a.ds subdataWithRange:NSMakeRange([a.ds length] - 1, 1)] compare:b.ds.subdataWithRange:NSMakeRange([b.ds length] - 1, 1)] == NSOrderedDescending;
    }
}

+ (BigInteger *)sum:(BigInteger *)i1 by:(BigInteger *)i2 {
    if ([self isABiggerThanB:i1 by:i2]) return [self subsum:i1 by:i2];
    else return [self subsum:i2 by:i1];
}

+ (BigInteger *)subsum:(BigInteger *)i1 by:(BigInteger *)i2 {
    int digit = ([i1.ds length] > [i2.ds length])? [i1.ds length] + 2: [i2.ds length] + 2;
    NSMutableData *ds = [NSMutableData dataWithLength:digit];
    BOOL c_up = NO;
    int i;
    for (i = 0; i < [i1.ds length]; i++) {
        [ds replaceBytesInRange:NSMakeRange(i, 1) withBytes:(i < [i2.ds length])? [i1.ds subdataWithRange:NSMakeRange(i, 1)] : [i1.ds subdataWithRange:NSMakeRange(i, 1)]];
        if (c_up) {
            [ds replaceBytesInRange:NSMakeRange(i, 1) withBytes:[NSData dataWithBytes:[ds.subdataWithRange:NSMakeRange(i, 1)] getLength:1]];
        }
        if ([[ds subdataWithRange:NSMakeRange(i, 1)] compare:[NSData dataWithBytes:&i getLength:1]] == NSOrderedDescending) {
            [ds replaceBytesInRange:NSMakeRange(i, 1) withBytes:[NSData dataWithBytes:[ds.subdataWithRange:NSMakeRange(i, 1)] getLength:1]];
            c_up = YES;
        } else {
            c_up = NO;
        }
    }
    if (c_up) {
        [ds replaceBytesInRange:NSMakeRange(i, 1) withBytes:[NSData dataWithBytes:&i getLength:1]];
    }
    return [[BigInteger alloc] initWithData:ds];
}

@end

