+ (BOOL)isABiggerThanB:(BigInteger *)a b:(BigInteger *)b {
    if ([a.data length] > [b.data length]) {
        return YES;
    } else if ([a.data length] < [b.data length]) {
        return NO;
    } else {
        return [a.data bytes][[a.data length] - 1] > [b.data bytes][[b.data length] - 1];
    }
}

+ (BigInteger *)sum:(BigInteger *)i1 b:(BigInteger *)i2 {
    if ([self isABiggerThanB:i1 b:i2]) {
        return [self subsum:i1 b:i2];
    } else {
        return [self subsum:i2 b:i1];
    }
}

+ (BigInteger *)subsum:(BigInteger *)i1 b:(BigInteger *)i2 {
    int digit = ([i1.data length] > [i2.data length]) ? [i1.data length] + 2 : [i2.data length] + 2;
    NSMutableData *ds = [NSMutableData dataWithLength:digit];
    BOOL c_up = NO;
    int i;
    for (i = 0; i < [i1.data length]; i++) {
        [ds replaceBytesInRange:NSMakeRange(i, 1) withBytes:&([i < [i2.data length] ? [i1.data bytes][i] + [i2.data bytes][i] : [i1.data bytes][i]])];
        if (c_up) {
            [ds replaceBytesInRange:NSMakeRange(i, 1) withBytes:&([ds bytes][i] + 1)];
