            [ds replaceBytesInRange:NSMakeRange(i, 1) withBytes:&([ds bytes][i] % 10)];
            c_up = YES;
        } else {
            c_up = NO;
        }
    }
    if (c_up) {
        [ds replaceBytesInRange:NSMakeRange(i, 1) withBytes:&([ds bytes][i] + 1)];
    }
    return [[BigInteger alloc] initWithData:ds];
}

