    if ([self.data length] > [other.data length]) {
        return YES;
    } else if ([self.data length] < [other.data length]) {
        return NO;
    } else {
        return [self.data compare:other.data options:NSNumericSearch] == NSOrderedAscending;
    }
}

+ (BigInteger *)sumOf:(BigInteger *)i1 and:(BigInteger *)i2 {
    NSUInteger digit = (i1.data.length > i2.data.length) ? i1.data.length + 2 : i2.data.length + 2;
    NSMutableData *resultData = [NSMutableData dataWithLength:digit];
    BOOL carryUp = NO;
    NSUInteger i;
    for (i = 0; i < i1.data.length; i++) {
        NSUInteger sum = (i < i2.data.length) ? [i1.data bytes][i] + [i2.data bytes][i] : [i1.data bytes][i];
        if (carryUp) {
            sum++;
        }
        if (sum > 9) {
            sum %= 10;
            carryUp = YES;
        } else {
            carryUp = NO;
        }
        [resultData replaceBytesInRange:NSMakeRange(i, 1) withBytes:&sum];
    }
    if (carryUp) {
        [resultData replaceBytesInRange:NSMakeRange(i, 1) withBytes:&carryUp];
    }
    return [[self alloc] initWithData:resultData];
}

