@implementation MyReader

- (instancetype)init {
    self = [super init];
    if (self) {
        _reader = [[NSFileHandle fileHandleWithStandardInput] fileHandleForReading];
        _line = @"";
        _delim = @"";
        [self initDelim];
    }
    return self;
}

- (BOOL)isReadable {
    if (_line.length != 0) { return YES; }
    _line = [[NSString alloc] initWithData:[_reader availableData] encoding:NSUTF8StringEncoding];
    return _line != @"";
}

