    return [self readInt:@""];
}

- (double)readDouble {
    return [self readDouble:@""];
}

- (NSString *)read {
    return [self read:@""];
}

- (NSInteger)readInt:(NSString *)delim {
    [self setDelim:delim];
    return [self readInt];
}

- (double)readDouble:(NSString *)delim {
    [self setDelim:delim];
    return [self readDouble];
}

- (NSString *)read:(NSString *)delim {
