typedef struct {
    int shift;
    int outOfRange;
} CipherReader;

CipherReader createCipherReader() {
    CipherReader reader;
    reader.shift = 0;
    reader.outOfRange = INT_MAX;
    return reader;
}

int positiveRemain(int divident, int divisor) {
    int result = divident % divisor;
    if (result < 0) {
        result += divisor;
    }

    return result;
}

char* displace(char* text, int count) {
    if (count == 0) { return text; }

    char* result = malloc(strlen(text) + 1);
    strcpy(result, text);

    for (int i = 0; i < strlen(text); i++) {
        char newWord;
        if ('a' <= text[i] && text[i] <= 'z') {
            newWord = (char) (positiveRemain(text[i] - 'a' + count, 26) + 'a');
        } else {
            newWord = text[i];
        }
        result[i] = newWord;
    }

    return result;
}

int getShiftCount(char* text, CipherReader reader) {
    char* words = strtok(text, " .");
    while (words != NULL) {
        int wordsLength = strlen(words);
        for (int i = 0; i < reader.outOfRange; i++) {
            char* keyword = reader.keywords[i];
            if (wordsLength != strlen(keyword)) { continue; }

            int shift = strcmp(keyword, words);
            if (!strcmp(displace(words, shift), keyword)) {
                return shift;
            }
        }
        words = strtok(NULL, " .");
    }

    return reader.outOfRange;
}

