- (NSString *)read:(NSString *)cipherText {
    int shift = [self getShiftCount:cipherText];
    if (shift == OUT_OF_RANGE) {
        return nil;
    }

    return [self displace:cipherText by:shift];
}

- (int)getShiftCount:(NSString *)text {
    NSArray *words = [text componentsSeparatedByString:@" "];

    for (NSString *word in words) {
        int wordsLength = [word length];
        for (NSString *keyword in self.keywords) {
            if (wordsLength != [keyword length]) {
                continue;
            }

            int shift = [keyword compare:word];
            if (![self displace:word by:shift].isEqualToString:keyword) {
                continue;
            }

            return shift;
        }
    }

    return OUT_OF_RANGE;
}

- (NSString *)displace:(NSString *)text by:(int)count {
    if (count == 0) {
        return text;
    }

    NSMutableString *result = [NSMutableString string];

    for (int i = 0; i < [text length]; i++) {
        unichar word = [text characterAtIndex:i];
