- (void)setInputsToList:(NSMutableArray *)list {
    NSCharacterSet *whitespace = [NSCharacterSet whitespaceAndNewlineCharacterSet];
    NSCharacterSet *decimalDigits = [NSCharacterSet decimalDigitCharacterSet];

    NSString *input = [NSString stringWithString:[NSFileHandle fileHandleWithStandardInput].availableData];
    NSArray *numbers = [input componentsSeparatedByCharactersInSet:whitespace];

    for (NSString *number in numbers) {
        if ([decimalDigits characterIsMember:[number characterAtIndex:0]]) {
            [list addObject:[NSNumber numberWithInt:[number intValue]]];
        }
    }
}

