    @autoreleasepool {
        NSInputStream *inputStream = [NSInputStream inputStreamWithFileAtPath:@"/dev/stdin"];
        [inputStream open];

        NSMutableData *data = [[NSMutableData alloc] init];
        NSInteger bytesRead = 0;
        char buffer[1024];

        while ((bytesRead = [inputStream read:buffer maxLength:1024]) > 0) {
            [data appendBytes:buffer length:bytesRead];
        }

        [inputStream close];

        NSArray *lines = [NSString stringWithCString:[data bytes] length:[data length]].componentsSeparatedByCharactersInSet:[NSCharacterSet newlineCharacterSet];

        NSMutableArray *numbers = [NSMutableArray array];
        for (NSString *line in lines) {
            if ([line length] > 0) {
                NSInteger number = [[line stringByTrimmingCharactersInSet:[NSCharacterSet whitespaceCharacterSet]] integerValue];
                [numbers addObject:@(number)];
            }
        }

        [numbers sortUsingComparator:^NSComparisonResult(id obj1, id obj2) {
            NSInteger num1 = [obj1 integerValue];
            NSInteger num2 = [obj2 integerValue];
            return (num1 < num2) ? NSOrderedAscending : (num1 > num2) ? NSOrderedDescending : NSOrderedSame;
        }];

        NSMutableString *result = [[NSMutableString alloc] init];
        for (NSInteger i = 0; i < [numbers count]; i++) {
            if (i > 0) {
                [result appendString:@" "];
            }
            [result appendString:[numbers[i] stringValue]];
        }

        NSLog(@"%@", result);
    }
    return 0;
}

