@interface FastScanner : NSObject

@property (nonatomic, strong) NSInputStream *in;
@property (nonatomic, strong) NSMutableData *buffer;
@property (nonatomic, assign) int length;
@property (nonatomic, assign) int p;

- (instancetype)initWithInputStream:(NSInputStream *)stream;
- (BOOL)hasNextByte;
- (int)readByte;
- (void)skip;
- (BOOL)hasNext;
- (NSString *)next;
- (NSArray *)nextArray:(NSInteger)n;
- (NSInteger)nextInt;
- (NSArray *)nextIntArray:(NSInteger)n;
- (long long)nextLong;
- (NSArray *)nextLongArray:(NSInteger)n;
- (double)nextDouble;
- (NSArray *)nextDoubleArray:(NSInteger)n;
- (void)close;

@end

@implementation FastScanner

- (instancetype)initWithInputStream:(NSInputStream *)stream {
    self = [super init];
    if (self) {
        self.in = stream;
        self.buffer = [NSMutableData dataWithLength:1024];
        self.length = 0;
        self.p = 0;
    }
    return self;
}

- (BOOL)hasNextByte {
    if (self.p < self.length) return YES;
    else {
        self.p = 0;
        [self.in readDataIntoBuffer:self.buffer maxLength:1024];
        self.length = [self.buffer length];
        if (self.length <= 0) return NO;
    }
    return YES;
}

- (int)readByte {
    if ([self hasNextByte] == YES) return [self.buffer bytes][self.p++];
    return -1;
}

- (void)skip {
    while ([self hasNextByte] && !([self.buffer bytes][self.p] >= 33 && [self.buffer bytes][self.p] <= 126)) self.p++;
}

- (BOOL)hasNext {
    [self skip];
    return [self hasNextByte];
}

- (NSString *)next {
    if (![self hasNext]) throw [NSException exceptionWithName:@"No more elements" reason:@"No more elements" userInfo:nil];
    NSMutableString *sb = [NSMutableString string];
    int t = [self readByte];
    while ([self.buffer bytes][self.p] >= 33 && [self.buffer bytes][self.p] <= 126) {
        [sb appendFormat:@"%c", [self.buffer bytes][self.p]];
        t = [self readByte];
    }
    return sb;
}

- (NSArray *)nextArray:(NSInteger)n {
    NSMutableArray *ar = [NSMutableArray arrayWithCapacity:n];
    for (int i=0; i<n; i++) [ar addObject:[self next]];
    return ar;
}

- (NSInteger)nextInt {
    return (NSInteger)[self nextLong];
}

- (NSArray *)nextIntArray:(NSInteger)n {
    NSMutableArray *ar = [NSMutableArray arrayWithCapacity:n];
    for (int i=0; i<n; i++) [ar addObject:@([self nextInt])];
    return ar;
}

- (long long)nextLong {
    if (![self hasNext]) throw [NSException exceptionWithName:@"No more elements" reason:@"No more elements" userInfo:nil];
    BOOL minus = NO;
    int temp = [self readByte];
    if (temp == '-') {
        minus = YES;
        temp = [self readByte];
    }
    if (temp<'0' || '9'<temp) throw [NSException exceptionWithName:@"Invalid number format" reason:@"Invalid number format" userInfo:nil];
    long long n = 0;
    while ([self.buffer bytes][self.p] >= 33 && [self.buffer bytes][self.p] <= 126) {
        if ('0'<=temp && temp<='9') {
            n *= 10;
            n += temp - '0';
        }
        else throw [NSException exceptionWithName:@"Invalid number format" reason:@"Invalid number format" userInfo:nil];
        temp = [self readByte];
    }
    return minus ? -n : n;
}

- (NSArray *)nextLongArray:(NSInteger)n {
    NSMutableArray *ar = [NSMutableArray arrayWithCapacity:n];
    for (int i=0; i<n; i++) [ar addObject:@([self nextLong])];
    return ar;
}

- (double)nextDouble {
    return [self.next doubleValue];
}

- (NSArray *)nextDoubleArray:(NSInteger)n {
    NSMutableArray *ar = [NSMutableArray arrayWithCapacity:n];
    for (int i=0; i<n; i++) [ar addObject:@([self nextDouble])];
    return ar;
}

- (void)close {
    [self.in close];
}

@end

