@property (nonatomic, strong) NSMutableData *buffer;
@property (nonatomic) NSInteger length;
@property (nonatomic) NSInteger p;

- (instancetype)initWithInputStream:(NSInputStream *)stream;
- (BOOL)hasNextByte;
- (NSInteger)readByte;
- (void)skip;
- (BOOL)hasNext;
- (NSString *)next;
- (NSArray *)nextArray:(NSInteger)n;
- (NSInteger)nextInt;
- (NSArray *)nextIntArray:(NSInteger)n;
- (long long)nextLong;
- (NSArray *)nextLongArray:(NSInteger)n;
- (double)nextDouble;
- (NSArray *)nextDoubleArray:(NSInteger)n;
- (void)close;

@end

@implementation FastScanner

- (instancetype)initWithInputStream:(NSInputStream *)stream {
    self = [super init];
    if (self) {
        self.in = stream;
        self.buffer = [NSMutableData dataWithCapacity:1024];
        self.length = 0;
        self.p = 0;
    }
    return self;
}

- (BOOL)hasNextByte {
    if (self.p < self.length) {
        return YES;
    } else {
        self.p = 0;
        [self.buffer setLength:0];
        self.length = [self.in read:[self.buffer mutableBytes] maxLength:self.buffer.length];
        if (self.length <= 0) {
            return NO;
        }
    }
    return YES;
}

- (NSInteger)readByte {
    if ([self hasNextByte]) {
        return [self.buffer bytes][self.p++];
    }
    return -1;
}

- (void)skip {
    while ([self hasNextByte] && ![[NSString stringWithFormat:@"%c", [self.buffer bytes][self.p]] isEqualToString:@" "]) {
        self.p++;
    }
}

- (BOOL)hasNext {
    [self skip];
    return [self hasNextByte];
}

- (NSString *)next {
    if (![self hasNext]) {
        NSLog(@"No more input");
        return nil;
    }
    NSMutableString *sb = [NSMutableString string];
    NSInteger t = [self readByte];
    while ([[NSString stringWithFormat:@"%c", t] isEqualToString:@" "]) {
        t = [self readByte];
    }
    while ([[NSString stringWithFormat:@"%c", t] isEqualToString:@"0"] || [[NSString stringWithFormat:@"%c", t] isEqualToString:@"9"]) {
        [sb appendString:[NSString stringWithFormat:@"%c", t]];
        t = [self readByte];
    }
    return sb;
}

- (NSArray *)nextArray:(NSInteger)n {
    NSMutableArray *ar = [NSMutableArray arrayWithCapacity:n];
    for (NSInteger i = 0; i < n; i++) {
        [ar addObject:[self next]];
    }
    return ar;
}

- (NSInteger)nextInt {
    return [self nextInt];
}

- (NSArray *)nextIntArray:(NSInteger)n {
    NSMutableArray *ar = [NSMutableArray arrayWithCapacity:n];
    for (NSInteger i = 0; i < n; i++) {
        [ar addObject:@([self nextInt]));
    }
    return ar;
}

- (long long)nextLong {
    if (![self hasNext]) {
        NSLog(@"No more input");
        return 0;
    }
    BOOL minus = NO;
    NSInteger t = [self readByte];
    if (t == '-') {
        minus = YES;
        t = [self readByte];
    }
    if ([[NSString stringWithFormat:@"%c", t] isEqualToString:@"0"] || [[NSString stringWithFormat:@"%c", t] isEqualToString:@"9"]) {
        long long n = 0;
        while ([[NSString stringWithFormat:@"%c", t] isEqualToString:@"0"] || [[NSString stringWithFormat:@"%c", t] isEqualToString:@"9"]) {
            n *= 10;
            n += t - '0';
            t = [self readByte];
        }
        return minus ? -n : n;
    }
    NSLog(@"Invalid input");
    return 0;
}

- (NSArray *)nextLongArray:(NSInteger)n {
    NSMutableArray *ar = [NSMutableArray arrayWithCapacity:n];
    for (NSInteger i = 0; i < n; i++) {
        [ar addObject:@([self nextLong]));
    }
    return ar;
}

- (double)nextDouble {
    return [self nextDouble];
}

- (NSArray *)nextDoubleArray:(NSInteger)n {
    NSMutableArray *ar = [NSMutableArray arrayWithCapacity:n];
    for (NSInteger i = 0; i < n; i++) {
        [ar addObject:@([self nextDouble]));
    }
    return ar;
}

- (void)close {
    [self.in close];
}

@end

@interface Main : NSObject

- (void)solve:(FastScanner *)in out:(NSOutputStream *)out methods:(Methods *)ms;

@end

@implementation Main

- (void)solve:(FastScanner *)in out:(NSOutputStream *)out methods:(Methods *)ms {
    NSArray *a = @[@([in nextInt]), @([in nextInt]), @([in nextInt]), @([in nextInt]), @([in nextInt])];
    NSArray *sortedArray = [a sortedArrayUsingSelector:@selector(compare:)];
    NSMutableArray *result = [NSMutableArray arrayWithCapacity:5];
    for (NSInteger i = 0; i < 5; i++) {
        [result addObject:sortedArray[sortedArray.count - 1 - i]];
    }
    [out write:[result componentsJoinedByString:@" "] dataUsingEncoding:NSUTF8StringEncoding];
}

@end

int main(int argc, const char * argv[]) {
    @autoreleasepool {
        NSInputStream *in = [NSInputStream inputStreamWithFileAtPath:@"/dev/stdin"];
        NSOutputStream *out = [NSOutputStream outputStreamToFD:1];
        [in open];
        [out open];
        FastScanner *scanner = [[FastScanner alloc] initWithInputStream:in];
        NSOutputStream *outputStream = [NSOutputStream outputStreamToFD:1];
        [outputStream open];
        Methods *methods = [[Methods alloc] init];
        Main *main = [[Main alloc] init];
        [main solve:scanner out:outputStream methods:methods];
        [scanner close];
        [outputStream close];
    }
    return 0;
}

