@implementation FastScanner

- (id)init {
    self = [super init];
    if (self) {
        in = [[NSFileHandle fileHandleWithStandardInput] retain];
        buffer = [[NSMutableData alloc] initWithLength:1024];
        length = 0;
        p = 0;
    }
    return self;
}

- (BOOL)hasNextByte {
    if (p < length) return YES;
    else {
        p = 0;
        length = [[in availableData] length];
        if (length <= 0) return NO;
    }
    return YES;
}

- (int)readByte {
    if ([self hasNextByte] == YES) return [buffer[p++] intValue];
    return -1;
}

- (BOOL)isPrintable:(int)n {return 33<=n&&n<=126;}

- (void)skip {
    while ([self hasNextByte] && ![[self isPrintable:[self readByte]] boolValue]) {}
}

- (BOOL)hasNext {
    [self skip];
    return [self hasNextByte];
}

- (NSString *)next {
    if (![self hasNext]) throw [NSException exceptionWithName:@"NSException" reason:@"No more elements" userInfo:nil];
    NSMutableString *sb = [[NSMutableString alloc] init];
    int t = [self readByte];
    while ([[self isPrintable:t] boolValue]) {
        [sb appendString:[NSString stringWithFormat:@"%c", t]];
        t = [self readByte];
    }
    return sb;
}

- (NSString **)nextArray:(int)n {
    NSString **ar = (NSString **)malloc(sizeof(NSString *) * n);
    for (int i=0; i<n; i++) ar[i] = [self next];
    return ar;
}

- (int)nextInt {
    return (int)[self nextLong];
}

- (int *)nextIntArray:(int)n {
    int *ar = (int *)malloc(sizeof(int) * n);
    for (int i=0; i<n; i++) ar[i] = [self nextInt];
    return ar;
}

- (long long)nextLong {
    if (![self hasNext]) throw [NSException exceptionWithName:@"NSException" reason:@"No more elements" userInfo:nil];
    BOOL minus = NO;
    int temp = [self readByte];
    if (temp == '-') {
        minus = YES;
        temp = [self readByte];
    }
    if (temp<'0' || '9'<temp) throw [NSException exceptionWithName:@"NSException" reason:@"Invalid input" userInfo:nil];
    long long n = 0;
    while ([[self isPrintable:temp] boolValue]) {
        if ('0'<=temp && temp<='9') {
            n *= 10;
            n += temp - '0';
        }
        else throw [NSException exceptionWithName:@"NSException" reason:@"Invalid input" userInfo:nil];
        temp = [self readByte];
    }
    return minus ? -n : n;
}

- (long long *)nextLongArray:(int)n {
    long long *ar = (long long *)malloc(sizeof(long long) * n);
    for (int i=0; i<n; i++) ar[i] = [self nextLong];
    return ar;
}

- (double)nextDouble {
    return [self nextDouble];
}

- (double *)nextDoubleArray:(int)n {
    double *ar = (double *)malloc(sizeof(double) * n);
    for (int i=0; i<n; i++) ar[i] = [self nextDouble];
    return ar;
}

- (void)close {
    [in close];
}

@end

