@implementation Methods

- (void)print:(id)ar {
    NSLog(@"%@", ar);
}

- (void)yesno:(id)out boolean:(BOOL)b {
    [out print:[b ? @"Yes" : @"No"]];
    [out println:@""];
}

- (void)YESNO:(id)out boolean:(BOOL)b {
    [out print:[b ? @"YES" : @"NO"]];
    [out println:@""];
}

- (int)max:(int *)ar {
    int max = ar[0];
    for (int i=1; i<[ar count]; i++) {
        if (ar[i] > max) max = ar[i];
    }
    return max;
}

- (int)min:(int *)ar {
    int min = ar[0];
    for (int i=1; i<[ar count]; i++) {
        if (ar[i] < min) min = ar[i];
    }
    return min;
}

- (long long)gcd:(long long)a b:(long long)b {
    return b>0 ? [self gcd:b a:(a%b)] : a;
}

- (long long)lcm:(long long)a b:(long long)b {
    return a/gcd(a,b)*b;
}

- (long long)factorial:(int)i {
    if (i==1) return 1;
    else return i*[self factorial:i-1];
}

- (int)manhat:(int)x1 y1:(int)y1 x2:(int)x2 y2:(int)y2 {
    return abs(x1-x2)+abs(y1-y2);
}

- (double)euclid:(double)x1 y1:(double)y1 x2:(double)x2 y2:(double)y2 {
    return sqrt(pow(x2-x1, 2)+pow(y2-y1, 2));
}

- (BOOL)isPrime:(int)n {
    if (n==2) return YES;
    if (n<2 || n%2==0) return NO;
    for (int i=3; i<=sqrt(n); i+=2) if(n%i==0) return NO;
    return YES;
}

