@interface FastScanner : NSObject

@property (nonatomic, strong) NSInputStream *in;
@property (nonatomic, strong) NSMutableData *buffer;
@property (nonatomic, assign) int length;
@property (nonatomic, assign) int p;

- (instancetype)initWithInputStream:(NSInputStream *)stream;
- (BOOL)hasNextByte;
- (int)readByte;
- (void)skip;
- (BOOL)hasNext;
- (NSString *)next;
- (NSString *)nextArray:(int)n;
- (int)nextInt;
- (int *)nextIntArray:(int)n;
- (long)nextLong;
- (long *)nextLongArray:(int)n;
- (double)nextDouble;
- (double *)nextDoubleArray:(int)n;
- (void)close;

@end

@implementation FastScanner

- (instancetype)initWithInputStream:(NSInputStream *)stream {
    self = [super init];
    if (self) {
        _in = stream;
        _buffer = [NSMutableData dataWithLength:1024];
        _length = 0;
        _p = 0;
    }
    return self;
}

- (BOOL)hasNextByte {
    if (_p < _length) {
        return YES;
    } else {
        _p = 0;
        [_in readIntoBuffer:_buffer maxLength:_length];
        _length = [_buffer length];
        if (_length <= 0) {
            return NO;
        }
    }
    return YES;
}

- (int)readByte {
    if ([self hasNextByte] == YES) {
        return [_buffer bytes][_p++];
    }
    return -1;
}

- (void)skip {
    while ([self hasNextByte] && !([self readByte] >= 33 && [self readByte] <= 126)) {
        _p++;
    }
}

- (BOOL)hasNext {
    [self skip];
    return [self hasNextByte];
}

- (NSString *)next {
    if (![self hasNext]) {
        return nil;
    }
    NSMutableString *sb = [NSMutableString string];
    int t = [self readByte];
    while ([self readByte] >= 33 && [self readByte] <= 126) {
        [sb appendString:[NSString stringWithFormat:@"%c", t]];
        t = [self readByte];
    }
    return sb;
}

- (NSString *)nextArray:(int)n {
    NSString *ar[n];
    for (int i = 0; i < n; i++) {
        ar[i] = [self next];
    }
    return ar;
}

- (int)nextInt {
    return (int)[self nextLong];
}

- (int *)nextIntArray:(int)n {
    int ar[n];
    for (int i = 0; i < n; i++) {
        ar[i] = [self nextInt];
    }
    return ar;
}

- (long)nextLong {
    if (![self hasNext]) {
        return 0;
    }
    BOOL minus = NO;
    int temp = [self readByte];
    if (temp == '-') {
        minus = YES;
        temp = [self readByte];
    }
    if (temp < '0' || temp > '9') {
        return 0;
    }
    long n = 0;
    while ([self readByte] >= '0' && [self readByte] <= '9') {
        n *= 10;
        n += temp - '0';
        temp = [self readByte];
    }
    return minus ? -n : n;
}

- (long *)nextLongArray:(int)n {
    long ar[n];
    for (int i = 0; i < n; i++) {
        ar[i] = [self nextLong];
    }
    return ar;
}

- (double)nextDouble {
    return [self nextDouble];
}

- (double *)nextDoubleArray:(int)n {
    double ar[n];
    for (int i = 0; i < n; i++) {
        ar[i] = [self nextDouble];
    }
    return ar;
}

- (void)close {
    [_in close];
}

@end

