        NSInputStream *inputStream = [NSInputStream inputStreamWithFileAtPath:@"/dev/stdin"];
        [inputStream open];

        NSMutableString *input = [NSMutableString string];
        char buffer[1024];
        while ([inputStream hasBytesAvailable]) {
            NSInteger bytesRead = [inputStream read:buffer maxLength:sizeof(buffer)];
            if (bytesRead > 0) {
                [input appendString:[NSString stringWithCString:buffer length:bytesRead]];
            }
        }

        [inputStream close];

        NSArray *inputArray = [input componentsSeparatedByString:@"\n"];
        NSMutableArray *numbers = [NSMutableArray array];

        for (NSString *line in inputArray) {
            NSArray *components = [line componentsSeparatedByString:@" "];
            for (NSString *component in components) {
                if (![component isEqualToString:@""]) {
                    [numbers addObject:component];
                }
            }
        }

        NSMutableArray *sortedNumbers = [numbers mutableCopy];
        [sortedNumbers sortUsingComparator:^NSComparisonResult(id obj1, id obj2) {
            return [obj1 compare:obj2 options:NSNumericSearch];
        }];

        for (int i = 0; i < [sortedNumbers count] - 1; i++) {
            NSLog(@"%@", [sortedNumbers objectAtIndex:i]);
        }

        NSLog(@"%@", [sortedNumbers lastObject]);
    }
    return 0;
}

