- (instancetype)initWithInputStream:(NSInputStream *)stream {
    self = [super init];
    if (self) {
        in = stream;
    }
    return self;
}

- (BOOL)hasNextByte {
    if (p < length) return YES;
    else {
        p = 0;
        NSError *error = nil;
        length = [in read:buffer maxLength:1024 error:&error];
        if (length <= 0) return NO;
    }
    return YES;
}

- (int)readByte {
    if ([self hasNextByte] == YES) return buffer[p++];
    return -1;
}

- (BOOL)isPrintable:(int)n {
    return 33 <= n && n <= 126;
}

- (void)skip {
    while ([self hasNextByte] && ![self isPrintable:buffer[p]]) p++;
}

- (BOOL)hasNext {
    [self skip];
    return [self hasNextByte];
}

- (NSString *)next {
    if (![self hasNext]) {
        NSException *exception = [NSException exceptionWithName:@"NSInvalidArgumentException" reason:@"No more elements" userInfo:nil];
        @throw exception;
    }
    NSMutableString *sb = [NSMutableString string];
    int t = [self readByte];
    while ([self isPrintable:t]) {
        [sb appendFormat:@"%c", (char)t];
        t = [self readByte];
    }
    return sb;
}

- (NSString *)nextArray:(int)n {
    NSString **ar = malloc(n * sizeof(NSString *));
    for (int i=0; i<n; i++) ar[i] = [self next];
    return ar;
}

