- (long long)nextLong {
    if (![self hasNext]) {
        NSException *exception = [NSException exceptionWithName:@"NSInvalidArgumentException" reason:@"No more elements" userInfo:nil];
        @throw exception;
    }
    BOOL minus = NO;
    int temp = [self readByte];
    if (temp == '-') {
        minus = YES;
        temp = [self readByte];
    }
    if (temp<'0' || '9'<temp) {
        NSException *exception = [NSException exceptionWithName:@"NSInvalidArgumentException" reason:@"Invalid number format" userInfo:nil];
        @throw exception;
    }
    long long n = 0;
    while ([self isPrintable:temp]) {
        if ('0'<=temp && temp<='9') {
            n *= 10;
            n += temp - '0';
        }
        else {
            NSException *exception = [NSException exceptionWithName:@"NSInvalidArgumentException" reason:@"Invalid number format" userInfo:nil];
            @throw exception;
        }
        temp = [self readByte];
    }
    return minus ? -n : n;
}

- (long long *)nextLongArray:(int)n {
    long long *ar = malloc(n * sizeof(long long));
    for (int i=0; i<n; i++) ar[i] = [self nextLong];
    return ar;
}

- (double)nextDouble {
    return [self nextLong];
}

- (double *)nextDoubleArray:(int)n {
    double *ar = malloc(n * sizeof(double));
    for (int i=0; i<n; i++) ar[i] = [self nextDouble];
    return ar;
}

- (void)close {
