#import <Foundation/Foundation.h>

@interface FastScanner : NSObject
- (instancetype)init;
- (BOOL)hasNext;
- (NSString *)next;
- (long long)nextLong;
- (int)nextInt;
- (double)nextDouble;
- (char)nextChar;
@end

@implementation FastScanner

- (instancetype)init {
    self = [super init];
    if (self) {
        self.inputStream = [NSFileHandle fileHandleWithStandardInput];
        self.buffer = [NSMutableData dataWithLength:1024];
        self.ptr = 0;
        self.buflen = 0;
    }
    return self;
}

- (BOOL)hasNext {
    if (self.ptr < self.buflen) {
        return YES;
    } else {
        self.ptr = 0;
        self.buflen = [self.inputStream readDataOfLength:self.buffer.length];
        if (self.buflen <= 0) {
            return NO;
        }
    }
    return YES;
}

- (NSString *)next {
    if (![self hasNext]) {
        return nil;
    }
    NSMutableString *sb = [NSMutableString string];
    int b = [self readByte];
    while ([self isPrintableChar:b]) {
        [sb appendFormat:@"%c", b];
        b = [self readByte];
    }
    return sb;
}

- (long long)nextLong {
    if (![self hasNext]) {
        return 0;
    }
    long long n = 0;
    BOOL minus = NO;
    int b = [self readByte];
    if (b == '-') {
        minus = YES;
        b = [self readByte];
    }
    if (b < '0' || b > '9') {
        return 0;
    }
    while (TRUE) {
        if (b >= '0' && b <= '9') {
            n *= 10;
            n += b - '0';
        } else if (b == -1 || ![self isPrintableChar:b]) {
            return minus ? -n : n;
        } else {
            return 0;
        }
        b = [self readByte];
    }
}

- (int)nextInt {
    long long nl = [self nextLong];
    if (nl < INT_MIN || nl > INT_MAX) {
        return 0;
    }
    return (int)nl;
}

- (double)nextDouble {
    return [self nextLong];
}

- (char)nextChar {
    int b = [self readByte];
    return b;
}

- (int)readByte {
    if ([self hasNext]) {
        return [self.buffer byteAtIndex:self.ptr++];
    } else {
