public class Main {

	static int minusCnt(int[] a){
		int count = 0;
		for(int i=0; i<a.length; i++)
			if(a[i] < 0) count++;
		return count;
	}

	static int[] minusIdx(int[] a,int cnt){
		int[] idx = new int[cnt];
		int j=0;
		for(int i=0; i<a.length; i++)
			if(a[i] < 0) idx[j++] = i;
		return idx;
	}


	static int maxOf(int[] a){
		int max = a[0];
		for(int i:a)
			if(max < i) max = i;
		return max;		
	}


	static int minOf(int[] a){
		int min = a[0];
		for(int i:a)
			if(min > i) min = i;
		return min;		
	}


	static void aryPrint(int[] a){
		for(int i : a) System.out.print(i + " ");
		System.out.println();
	}

	static int LsumUp(int[] a,int idx){
		int x=0;
		for(int i=0; i<=idx; i++) x +=a[i];
		return x ;
	}

	static int RsumUp(int[] a,int idx){
		int y=0;
		for(int i=idx; i<a.length; i++) y +=a[i];
		return y ;
	}

