int main(int argc, const char * argv[]) {
    @autoreleasepool {
        NSInputStream *inputStream = [[NSInputStream alloc] initWithFileAtPath:@"/dev/stdin"];
        [inputStream open];
        NSOutputStream *outputStream = [[NSOutputStream alloc] initWithFileAtPath:@"/dev/stdout" append:NO];
        [outputStream open];

        NSData *data = [inputStream readDataToEndOfFile];
        NSString *input = [[NSString alloc] initWithData:data encoding:NSUTF8StringEncoding];
        NSArray *lines = [input componentsSeparatedByString:@"\n"];

        for (NSString *line in lines) {
            if ([line isEqualToString:@""]) {
                break;
            }
            NSArray *components = [line componentsSeparatedByString:@" "];
            double x1 = [components[0] doubleValue];
            double y1 = [components[1] doubleValue];
            double r1 = [components[2] doubleValue];
            double x2 = [components[3] doubleValue];
            double y2 = [components[4] doubleValue];
            double r2 = [components[5] doubleValue];

            Circle *a = [[Circle alloc] initWithX:x1 y:y1 r:r1];
            Circle *b = [[Circle alloc] initWithX:x2 y:y2 r:r2];
            double dx = b.x - a.x;
            double dy = b.y - a.y;
            double r = a.r + b.r;
            double d = sqrt(dx * dx + dy * dy);
            if (d > r) {
                [outputStream write:@"0" length:1];
            } else {
                if (a.r < b.r && d + a.r < b.r) {
                    [outputStream write:@"-2" length:2];
                } else if (a.r > b.r && d + b.r < a.r) {
                    [outputStream write:@"2" length:1];
                } else {
                    [outputStream write:@"1" length:1];
                }
            }
        }

        [inputStream close];
        [outputStream close];
    }
