+ (NSMutableArray *)bubbleSort:(NSMutableArray *)array {
    for (int i = 0; i < array.count; i++) {
        for (int j = array.count - 1; j >= i + 1; j--) {
            if ([[array objectAtIndex:j] intValue] < [[array objectAtIndex:j - 1] intValue]) {
                NSNumber *tmp1 = [array objectAtIndex:j];
                NSNumber *tmp2 = [array objectAtIndex:j - 1];
                [array replaceObjectAtIndex:j withObject:tmp2];
                [array replaceObjectAtIndex:j - 1 withObject:tmp1];
            }
        }
    }

    return array;
}

