	static void solve (FastScanner in, PrintWriter out, Methods ms) {

		int[][] map = new int[14][14];

		while (in.hasNext() == true) {

			String[] temp = in.next().split(",");
			int x = Integer.parseInt(temp[0])+2, y = Integer.parseInt(temp[1])+2;
			int size = Integer.parseInt(temp[2]);

			map[y][x]++;

			if (size == 1) {
				map[y+1][x]++;
				map[y-1][x]++;
				map[y][x+1]++;
				map[y][x-1]++;
			}
			else if (size == 2) {
				map[y+1][x]++;
				map[y-1][x]++;
				map[y][x+1]++;
				map[y][x-1]++;
				map[y+1][x+1]++;
				map[y+1][x-1]++;
				map[y-1][x+1]++;
				map[y-1][x-1]++;
			}
			else if (size == 3) {
				map[y+1][x]++;
				map[y-1][x]++;
				map[y][x+1]++;
				map[y][x-1]++;
				map[y+1][x+1]++;
				map[y+1][x-1]++;
				map[y-1][x+1]++;
				map[y-1][x-1]++;
				map[y+2][x]++;
				map[y-2][x]++;
				map[y][x+2]++;
				map[y][x-2]++;
			}

		}

