}

- (void)drop:(NSInteger)x y:(NSInteger)y ink:(Ink)ink {
    switch (ink) {
        case InkSmall:
            [self paint:x y:y withRange:@[@[@(0), @(1), @(0)], @[@(1), @(1), @(1)], @[@(0), @(1), @(0)]]];
            break;
        case InkMiddle:
            [self paint:x y:y withRange:@[@[@(1), @(1), @(1)], @[@(1), @(1), @(1)], @[@(1), @(1), @(1)]]];
