            break;
    }
}

- (void)paint:(NSInteger)x y:(NSInteger)y withRange:(NSArray *)range {
    NSInteger rangeSize = range.count;
    NSInteger centerX = rangeSize / 2;
    NSInteger centerY = rangeSize / 2;
    for (NSInteger i = 0; i < rangeSize; i++) {
        for (NSInteger j = 0; j < rangeSize; j++) {
            if ([[range objectAtIndex:i] objectAtIndex:j] == @(1)) {
                NSInteger newX = x - centerX + i;
                NSInteger newY = y - centerY + j;
                if (0 <= newX && newX < _paper.count && 0 <= newY && newY < [[_paper objectAtIndex:newX] count]) {
                    NSInteger currentValue = [[[_paper objectAtIndex:newX] objectAtIndex:newY] integerValue];
                    [[_paper objectAtIndex:newX] replaceObjectAtIndex:newY withObject:@(currentValue + 1)];
                }
            }
        }
    }
}

- (NSInteger)countWhiteCells {
