    for (NSInteger i = 0; i < _paper.count; i++) {
        for (NSInteger j = 0; j < [[_paper objectAtIndex:i] count]; j++) {
            NSInteger value = [[[_paper objectAtIndex:i] objectAtIndex:j] integerValue];
            if (value == 0) {
