+ (BOOL)isCross:(NSInteger)x1:(NSInteger)y1:(NSInteger)x2:(NSInteger)y2:(NSInteger)x3:(NSInteger)y3:(NSInteger)x4:(NSInteger)y4 {
    NSInteger m = (x2 - x1) * (y4 - y3) - (y2 - y1) * (x4 - x3);
    if (m == 0) return NO;

    double r = ((y4 - y3) * (x3 - x1) - (x4 - x3) * (y3 - y1)) / m;
    double s = ((y2 - y1) * (x3 - x1) - (x2 - x1) * (y3 - y1)) / m;
    return (0 < r && r <= 1 && 0 < s && s <= 1);
}

