#import <Foundation/Foundation.h>

@interface FastScanner : NSObject

- (instancetype)initWithInputStream:(NSInputStream *)stream;
- (BOOL)hasNextByte;
- (int)readByte;
- (void)skip;
- (BOOL)hasNext;
- (NSString *)next;
- (NSString *)nextArray:(int)n;
- (int)nextInt;
- (int *)nextIntArray:(int)n;
- (long long)nextLong;
- (long long *)nextLongArray:(int)n;
- (double)nextDouble;
- (double *)nextDoubleArray:(int)n;
- (void)close;

@end

@implementation FastScanner

- (instancetype)initWithInputStream:(NSInputStream *)stream {
    self = [super init];
    if (self) {
        in = stream;
    }
    return self;
}

- (BOOL)hasNextByte {
    if (p < length) return YES;
    else {
        p = 0;
        length = [in read:buffer maxLength:1024];
        if (length <= 0) return NO;
    }
    return YES;
}

- (int)readByte {
    if ([self hasNextByte] == YES) return buffer[p++];
    return -1;
}

- (BOOL)isPrintable:(int)n {return 33<=n&&n<=126;}

- (void)skip {
    while ([self hasNextByte] && ![self isPrintable:buffer[p]]) p++;
}

- (BOOL)hasNext {
    [self skip];
    return [self hasNextByte];
}

- (NSString *)next {
    if (![[self hasNext] boolValue]) throw [NSException exceptionWithName:@"NoSuchElementException" reason:nil userInfo:nil];
    NSMutableString *sb = [NSMutableString string];
    int t = [self readByte];
    while ([self isPrintable:t]) {
        [sb appendFormat:@"%c", t];
        t = [self readByte];
    }
    return sb;
}

- (NSString *)nextArray:(int)n {
    NSString *ar[n];
    for (int i=0; i<n; i++) ar[i] = [self next];
    return ar;
}

- (int)nextInt {
    return (int)[self nextLong];
}

- (int *)nextIntArray:(int)n {
    int ar[n];
    for (int i=0; i<n; i++) ar[i] = [self nextInt];
    return ar;
}

- (long long)nextLong {
    if (![[self hasNext] boolValue]) throw [NSException exceptionWithName:@"NoSuchElementException" reason:nil userInfo:nil];
    BOOL minus = NO;
    int temp = [self readByte];
    if (temp == '-') {
        minus = YES;
        temp = [self readByte];
    }
    if (temp<'0' || '9'<temp) throw [NSException exceptionWithName:@"NumberFormatException" reason:nil userInfo:nil];
    long long n = 0;
    while ([self isPrintable:temp]) {
        if ('0'<=temp && temp<='9') {
            n *= 10;
            n += temp - '0';
        }
        else throw [NSException exceptionWithName:@"NumberFormatException" reason:nil userInfo:nil];
        temp = [self readByte];
    }
    return minus ? -n : n;
}

- (long long *)nextLongArray:(int)n {
    long long ar[n];
    for (int i=0; i<n; i++) ar[i] = [self nextLong];
    return ar;
}

- (double)nextDouble {
    return [self nextDouble];
}

- (double *)nextDoubleArray:(int)n {
    double ar[n];
    for (int i=0; i<n; i++) ar[i] = [self nextDouble];
    return ar;
}

- (void)close {
    [in close];
}

@end

@interface Methods : NSObject

- (void)print:(id)ar;
- (int)max:(int *)ar;
- (int)min:(int *)ar;
- (long long)gcd:(long long)a :(long long)b;
- (long long)lcm:(long long)a :(long long)b;
- (long long)factorial:(int)i;
- (int)manhat:(int)x1 :(int)y1 :(int)x2 :(int)y2;
- (double)euclid:(double)x1 :(double)y1 :(double)x2 :(double)y2;
- (BOOL)isPrime:(int)n;

@end

@implementation Methods

- (void)print:(id)ar {
    NSLog(@"%@", ar);
}

- (int)max:(int *)ar {
    int max = ar[0];
    for (int i=1; i<[ar count]; i++) {
        if (ar[i] > max) {
            max = ar[i];
        }
    }
    return max;
}

- (int)min:(int *)ar {
    int min = ar[0];
    for (int i=1; i<[ar count]; i++) {
        if (ar[i] < min) {
            min = ar[i];
        }
    }
    return min;
}

- (long long)gcd:(long long)a :(long long)b {
    return b>0 ? [self gcd:b :(a%b)] : a;
}

- (long long)lcm:(long long)a :(long long)b {
    return a/[self gcd:a :b]*b;
}

- (long long)factorial:(int)i {
    if (i==1) return 1;
    else return i*[self factorial:i-1];
}

- (int)manhat:(int)x1 :(int)y1 :(int)x2 :(int)y2 {
    return abs(x1-x2)+abs(y1-y2);
}

- (double)euclid:(double)x1 :(double)y1 :(double)x2 :(double)y2 {
    return sqrt(pow(x2-x1, 2)+pow(y2-y1, 2));
}

- (BOOL)isPrime:(int)n {
    if (n==2) return YES;
    if (n<2 || n%2==0) return NO;
    for (int i=3; i<=sqrt(n); i+=2) if(n%i==0) return NO;
    return YES;
}

