+ (void)solve:(FastScanner *)in :(NSOutputStream *)out :(Methods *)ms {
    while (YES) {
        int m = [in nextInt];
        int d = [in nextInt];
        if (m == 0 && d == 0) return;
        NSCalendar *cl = [[NSCalendar alloc] initWithCalendarIdentifier:NSGregorianCalendar];
        NSDateComponents *dateComponents = [[NSDateComponents alloc] init];
        [dateComponents setYear:2004];
        [dateComponents setMonth:m];
        [dateComponents setDay:d];
        NSDate *date = [cl dateFromComponents:dateComponents];
        NSCalendarUnit unitFlags = NSDayOfWeekCalendarUnit;
        NSDateComponents *components = [cl components:unitFlags fromDate:date];
        int dayOfWeek = [components dayOfWeek];
        switch (dayOfWeek) {
            case 1:
                [out write:"Sunday" length:6];
                break;
            case 2:
                [out write:"Monday" length:6];
