    }
    return self;
}

- (BOOL)hasNextByte {
    if (self.position < self.length) return YES;
    else {
        self.position = 0;
        self.length = [self.data length];
        if (self.length <= 0) return NO;
    }
    return YES;
}

- (int)readByte {
    if ([self hasNextByte] == YES) return [self.data bytes][self.position++];
    return -1;
}

- (BOOL)isPrintable:(int)n {
    return (33 <= n && n <= 126);
}

- (void)skip {
    while ([self hasNextByte] && ![self isPrintable:[self readByte]]) {}
}

- (BOOL)hasNext {
    [self skip];
    return [self hasNextByte];
}

- (NSString *)next {
    if (![self hasNext]) [NSException raise:NSInvalidArgumentException format:@"No more tokens"];
    NSMutableString *sb = [NSMutableString string];
    int t = [self readByte];
    while ([self isPrintable:t]) {
        [sb appendFormat:@"%c", t];
        t = [self readByte];
    }
    return sb;
}

