    if (![self hasNext]) [NSException raise:NSInvalidArgumentException format:@"No more tokens"];
    BOOL minus = NO;
    int temp = [self readByte];
    if (temp == '-') {
        minus = YES;
        temp = [self readByte];
    }
    if (temp < '0' || temp > '9') [NSException raise:NSInvalidArgumentException format:@"Invalid number"];
