    while ([self isPrintable:temp]) {
        if (temp >= '0' && temp <= '9') {
            n *= 10;
            n += temp - '0';
        } else [NSException raise:NSInvalidArgumentException format:@"Invalid number"];
        temp = [self readByte];
    }
    return minus ? -n : n;
}

