#import <Foundation/Foundation.h>

int main(int argc, const char * argv[]) {
    @autoreleasepool {
        NSInputStream *inputStream = [NSInputStream inputStreamWithFileAtPath:@"/dev/stdin"];
        [inputStream open];
        NSOutputStream *outputStream = [NSOutputStream outputStreamToMemory];
        [outputStream open];

        NSDateFormatter *dateFormatter = [[NSDateFormatter alloc] init];
        [dateFormatter setDateFormat:@"yyyy-MM-dd"];

        while (YES) {
            char buffer[1024];
            NSUInteger bytesRead = [inputStream read:buffer maxLength:sizeof(buffer)];
            if (bytesRead == 0) {
                break;
            }

            NSString *input = [[NSString alloc] initWithBytes:buffer length:bytesRead encoding:NSUTF8StringEncoding];
            NSArray *inputs = [input componentsSeparatedByString:@" "];

            if ([[inputs objectAtIndex:0] isEqualToString:@"0"]) {
                break;
            }

            NSDate *date = [dateFormatter dateFromString:[NSString stringWithFormat:@"2004-%@-%@", [inputs objectAtIndex:0], [inputs objectAtIndex:1]]];
            NSCalendar *calendar = [NSCalendar currentCalendar];
            NSDateComponents *components = [calendar components:NSCalendarUnitWeekday fromDate:date];
            int weekday = [components weekday];

            NSString *week;
            switch (weekday) {
                case 1:
                    week = @"Sunday";
                    break;
                case 2:
                    week = @"Monday";
                    break;
                case 3:
                    week = @"Tuesday";
                    break;
                case 4:
                    week = @"Wednesday";
                    break;
                case 5:
                    week = @"Thursday";
                    break;
                case 6:
                    week = @"Friday";
                    break;
                case 7:
                    week = @"Saturday";
                    break;
                default:
                    week = @"";
                    break;
            }

            [outputStream write:[week UTF8String] maxLength:[week lengthOfBytesUsingEncoding:NSUTF8StringEncoding]];
            [outputStream write:@"\n" maxLength:1];
        }

        [outputStream close];
        NSData *outputData = [outputStream propertyForKey:NSStreamDataWrittenToMemoryStreamKey];
        [outputData writeToFile:@"/dev/stdout" atomically:YES];
    }
    return 0;
}

