#import <Foundation/Foundation.h>

@interface FastScanner : NSObject

- (instancetype)initWithInputStream:(NSInputStream *)stream;
- (BOOL)hasNextByte;
- (int)readByte;
- (void)skip;
- (BOOL)hasNext;
- (NSString *)next;
- (NSArray *)nextArray:(int)n;
- (int)nextInt;
- (NSArray *)nextIntArray:(int)n;
- (long long)nextLong;
- (NSArray *)nextLongArray:(int)n;
- (double)nextDouble;
- (NSArray *)nextDoubleArray:(int)n;
- (void)close;

@end

@implementation FastScanner

- (instancetype)initWithInputStream:(NSInputStream *)stream {
    self = [super init];
    if (self) {
        _in = stream;
        _buffer = [[NSMutableData alloc] initWithCapacity:1024];
        _length = 0;
        _p = 0;
    }
    return self;
}

- (BOOL)hasNextByte {
    if (_p < _length) return YES;
    else {
        _p = 0;
        [_buffer setLength:0];
        _length = [_in read:[_buffer mutableBytes] maxLength:1024];
        if (_length <= 0) return NO;
    }
    return YES;
}

- (int)readByte {
    if ([self hasNextByte] == YES) return [_buffer bytes][[_buffer length] - _p++];
    return -1;
}

- (void)skip {
    while ([self hasNextByte] && !([[_buffer bytes][[_buffer length] - _p] >= 33 && [[_buffer bytes][[_buffer length] - _p] <= 126])) _p++;
}

- (BOOL)hasNext {
    [self skip];
    return [self hasNextByte];
}

- (NSString *)next {
    if (![self hasNext]) throw [NSException exceptionWithName:@"NoSuchElementException" reason:@"No more elements" userInfo:nil];
    NSMutableString *sb = [NSMutableString string];
    int t = [self readByte];
    while ([self isPrintable:t]) {
        [sb appendString:[NSString stringWithFormat:@"%c", t]];
        t = [self readByte];
    }
    return sb;
}

- (NSArray *)nextArray:(int)n {
    NSMutableArray *ar = [NSMutableArray arrayWithCapacity:n];
    for (int i=0; i<n; i++) [ar addObject:[self next]];
    return ar;
}

- (int)nextInt {
    return (int)[self nextLong];
}

- (NSArray *)nextIntArray:(int)n {
    NSMutableArray *ar = [NSMutableArray arrayWithCapacity:n];
    for (int i=0; i<n; i++) [ar addObject:@([self nextInt])];
    return ar;
}

- (long long)nextLong {
    if (![self hasNext]) throw [NSException exceptionWithName:@"NoSuchElementException" reason:@"No more elements" userInfo:nil];
    BOOL minus = NO;
    int temp = [self readByte];
    if (temp == '-') {
        minus = YES;
        temp = [self readByte];
    }
    if (temp<'0' || '9'<temp) throw [NSException exceptionWithName:@"NumberFormatException" reason:@"Invalid number format" userInfo:nil];
    long long n = 0;
    while ([self isPrintable:temp]) {
        if ('0'<=temp && temp<='9') {
            n *= 10;
            n += temp - '0';
        }
        else throw [NSException exceptionWithName:@"NumberFormatException" reason:@"Invalid number format" userInfo:nil];
        temp = [self readByte];
    }
    return minus? -n : n;
}

- (NSArray *)nextLongArray:(int)n {
    NSMutableArray *ar = [NSMutableArray arrayWithCapacity:n];
    for (int i=0; i<n; i++) [ar addObject:@([self nextLong])];
    return ar;
}

- (double)nextDouble {
    return [self nextDouble];
}

- (NSArray *)nextDoubleArray:(int)n {
    NSMutableArray *ar = [NSMutableArray arrayWithCapacity:n];
    for (int i=0; i<n; i++) [ar addObject:@([self nextDouble])];
    return ar;
}

- (void)close {
    [_in close];
}

@end

@interface Methods : NSObject

- (void)print:(id)ar;
- (int)max:(int *)ar length:(int)len;
- (int)min:(int *)ar length:(int)len;
- (long long)gcd:(long long)a b:(long long)b;
- (long long)lcm:(long long)a b:(long long)b;
- (long long)factorial:(int)i;
- (int)manhat:(int)x1 y1:(int)y1 x2:(int)x2 y2:(int)y2;
- (double)euclid:(double)x1 y1:(double)y1 x2:(double)x2 y2:(double)y2;
- (BOOL)isPrime:(int)n;

@end

@implementation Methods

- (void)print:(id)ar {
    NSLog(@"%@", ar);
}

- (int)max:(int *)ar length:(int)len {
    int max = ar[0];
    for (int i=1; i<len; i++) {
        max = MAX(max, ar[i]);
    }
    return max;
}

- (int)min:(int *)ar length:(int)len {
    int min = ar[0];
    for (int i=1; i<len; i++) {
        min = MIN(min, ar[i]);
    }
    return min;
}

- (long long)gcd:(long long)a b:(long long)b {
    return b>0? [self gcd:b a:a%b]:a;
}

- (long long)lcm:(long long)a b:(long long)b {
    return a/[self gcd:a b:b]*b;
}

- (long long)factorial:(int)i {
    if (i==1) return 1;
    else return i*[self factorial:i-1];
}

- (int)manhat:(int)x1 y1:(int)y1 x2:(int)x2 y2:(int)y2 {
