        in = stream;
        buffer = [NSByteOrder littleEndian:0];
        length = 0;
        p = 0;
    }
    return self;
}

- (BOOL)hasNextByte {
    if (p < length) return YES;
    else {
        p = 0;
        [in readIntoBuffer:buffer maxLength:length];
        if (length <= 0) return NO;
    }
    return YES;
}

- (int)readByte {
    if ([self hasNextByte] == YES) return buffer[p++];
    return -1;
}

- (BOOL)isPrintable:(int)n {
    return 33 <= n && n <= 126;
}

- (void)skip {
    while ([self hasNextByte] && ![self isPrintable:buffer[p]]) p++;
}

- (BOOL)hasNext {
    [self skip];
    return [self hasNextByte];
}

- (NSString *)next {
    if (![self hasNext]) throw [NSException exceptionWithName:@"NSException" reason:@"No more elements" userInfo:nil];
    NSMutableString *sb = [NSMutableString string];
    int t = [self readByte];
    while ([self isPrintable:t]) {
        [sb appendFormat:@"%c", t];
        t = [self readByte];
    }
    return sb;
}

