@property (nonatomic, assign) int length;
@property (nonatomic, assign) int p;

- (instancetype)initWithInputStream:(NSInputStream *)stream;
- (BOOL)hasNextByte;
- (int)readByte;
- (void)skip;
- (BOOL)hasNext;
- (NSString *)next;
- (NSString *)nextArray:(int)n;
- (int)nextInt;
- (int *)nextIntArray:(int)n;
- (long)nextLong;
- (long *)nextLongArray:(int)n;
- (double)nextDouble;
- (double *)nextDoubleArray:(int)n;
- (void)close;

@end

@implementation FastScanner

- (instancetype)initWithInputStream:(NSInputStream *)stream {
    self = [super init];
    if (self) {
        self.in = stream;
        self.buffer = [NSMutableData data];
        self.length = 0;
        self.p = 0;
    }
    return self;
}

- (BOOL)hasNextByte {
    if (self.p < self.length) {
        return YES;
    } else {
        self.p = 0;
        [self.in read:self.buffer.mutableBytes maxLength:self.buffer.length];
        self.length = [self.buffer length];
        if (self.length <= 0) {
            return NO;
        }
    }
    return YES;
}

- (int)readByte {
    if ([self hasNextByte]) {
        return [self.buffer bytes][self.p++];
    }
    return -1;
}

- (void)skip {
    while ([self hasNextByte] && ![[NSString alloc] initWithBytes:[self.buffer bytes] length:1 encoding:NSUTF8StringEncoding].rangeOfCharacterFromSet:[NSCharacterSet characterSetWithCharactersInString:@" "].location) {
        self.p++;
    }
}

- (BOOL)hasNext {
    [self skip];
    return [self hasNextByte];
}

- (NSString *)next {
    if (![self hasNext]) {
        return nil;
    }
    NSMutableString *sb = [NSMutableString string];
    int t = [self readByte];
    while ([NSString alloc] initWithBytes:[self.buffer bytes] length:1 encoding:NSUTF8StringEncoding].rangeOfCharacterFromSet:[NSCharacterSet characterSetWithCharactersInString:@" "].location) {
        [sb appendFormat:@"%c", t];
        t = [self readByte];
    }
    return sb;
}

- (NSString *)nextArray:(int)n {
    NSString *ar[n];
    for (int i=0; i<n; i++) {
        ar[i] = [self next];
    }
    return ar;
}

- (int)nextInt {
    return [self nextLong];
}

- (int *)nextIntArray:(int)n {
    int ar[n];
    for (int i=0; i<n; i++) {
        ar[i] = [self nextInt];
    }
    return ar;
}

- (long)nextLong {
    if (![self hasNext]) {
        return 0;
    }
    BOOL minus = NO;
    int temp = [self readByte];
    if (temp == '-') {
        minus = YES;
        temp = [self readByte];
    }
    if ([NSString alloc] initWithBytes:[self.buffer bytes] length:1 encoding:NSUTF8StringEncoding].rangeOfCharacterFromSet:[NSCharacterSet characterSetWithCharactersInString:@"0123456789"].location) {
        return 0;
    }
    long n = 0;
    while ([NSString alloc] initWithBytes:[self.buffer bytes] length:1 encoding:NSUTF8StringEncoding].rangeOfCharacterFromSet:[NSCharacterSet characterSetWithCharactersInString:@"0123456789"].location) {
        if ('0'<=temp && temp<='9') {
            n *= 10;
            n += temp - '0';
        } else {
            return 0;
        }
        temp = [self readByte];
    }
    return minus ? -n : n;
}

- (long *)nextLongArray:(int)n {
    long ar[n];
    for (int i=0; i<n; i++) {
        ar[i] = [self nextLong];
    }
    return ar;
}

- (double)nextDouble {
    return [self nextLong];
}

- (double *)nextDoubleArray:(int)n {
    double ar[n];
    for (int i=0; i<n; i++) {
        ar[i] = [self nextDouble];
    }
    return ar;
}

- (void)close {
    [self.in close];
}

@end

