@implementation FastScanner

- (BOOL)hasNextByte {
    if ([self p] < [self length]) return YES;
    else {
        [self p] = 0;
        [self length] = [self in] read:[self buffer] maxLength:1024];
        if ([self length] <= 0) return NO;
    }
    return YES;
}

- (int)readByte {
    if ([self hasNextByte] == YES) return [self buffer] [self p]++;
    return -1;
}

