    while ([self hasNextByte] && ![self isPrintable:[self readByte]]) [self p]++;
}

- (BOOL)hasNext {
    [self skip];
    return [self hasNextByte];
}

- (NSString *)next {
    if (![self hasNext]) throw [NSException exceptionWithName:@"NSException" reason:@"No next element" userInfo:nil];
    NSMutableString *sb = [NSMutableString string];
    int t = [self readByte];
    while ([self isPrintable:t]) {
        [sb appendString:[NSString stringWithFormat:@"%c", t]];
        t = [self readByte];
    }
    return sb;
}

- (NSString **)nextArray:(int)n {
    NSString **ar = malloc(sizeof(NSString *) * n);
    for (int i=0; i<n; i++) ar[i] = [self next];
    return ar;
}

