    int *ar = malloc(sizeof(int) * n);
    for (int i=0; i<n; i++) ar[i] = [self nextInt];
    return ar;
}

- (long)nextLong {
    if (![self hasNext]) throw [NSException exceptionWithName:@"NSException" reason:@"No next element" userInfo:nil];
    BOOL minus = NO;
    int temp = [self readByte];
    if (temp == '-') {
        minus = YES;
        temp = [self readByte];
    }
    if (temp < '0' || temp > '9') throw [NSException exceptionWithName:@"NSException" reason:@"Invalid input" userInfo:nil];
    long n = 0;
    while ([self isPrintable:temp]) {
        if (temp >= '0' && temp <= '9') {
            n *= 10;
            n += temp - '0';
        }
        else throw [NSException exceptionWithName:@"NSException" reason:@"Invalid input" userInfo:nil];
        temp = [self readByte];
    }
    return minus ? -n : n;
}

