+ (void)QuickSort:(NSMutableArray *)d left:(int)left right:(int)right {
    if (left >= right) {
        return;
    }
    int p = d[(left + right) / 2];
    int l = left, r = right;
    int tmp;
    while (l <= r) {
        while ([d[l] intValue] < p) {
            l++;
        }
        while ([d[r] intValue] > p) {
            r--;
        }
        if (l <= r) {
            tmp = [d[l] intValue];
            d[l] = d[r];
            d[r] = @(tmp);
            l++;
            r--;
        }
    }
    [self QuickSort:d left:left right:r];
    [self QuickSort:d left:l right:right];
}

+ (BOOL)SeparateSearch:(NSArray *)a b:(int)b first:(int)first end:(int)end {
    if (end - first <= 1) {
        if ([[a objectAtIndex:first] intValue] == b) {
            return YES;
        } else if ([[a objectAtIndex:end] intValue] == b) {
            return YES;
        } else {
            return NO;
        }
    } else {
        int temp = (end + first) / 2;
        if ([[a objectAtIndex:temp] intValue] == b) {
            return YES;
        } else if ([[a objectAtIndex:temp] intValue] < b) {
            return [self SeparateSearch:a b:b first:temp end:end];
        } else {
            return [self SeparateSearch:a b:b first:first end:temp];
        }
    }
}

+ (int)GCD:(int)x y:(int)y {
    int z = MAX(x, y) % MIN(x, y);
    if (z == 0) {
        return MIN(x, y);
    }
    return [self GCD:z y:MIN(y, x)];
}

+ (int)SelectionSort:(NSMutableArray *)a {
    int Select = 0;
    for (int j = 0; j < a.count - 1; j++) {
        int minIndex = j;
        int minValue = [a[minIndex] intValue];
        for (int i = j; i < a.count; i++) {
            if ([a[i] intValue] < minValue) {
                minIndex = i;
                minValue = [a[i] intValue];
            }
        }
        if (j != minIndex) {
            Select++;
            [self swap:a x:j y:minIndex];
        }
    }
    return Select;
}

+ (int)BubbleSort:(NSMutableArray *)a {
    int swapp = 0;
