            }
            break;
        case NSStreamEventEndEncountered:
            [aStream close];
            [aStream removeFromRunLoop:[NSRunLoop currentRunLoop] forMode:NSDefaultRunLoopMode];
            break;
        case NSStreamEventErrorOccurred:
            NSLog(@"Error: %@", [aStream streamError]);
            break;
        default:
