      int s = Integer.parseInt(str[1]);
      System.out.println(dfs(n, s, 0));
    }
  }

  private static int dfs(int n, int s, int min) {
    if (n == 0) {
      return s == 0 ? 1 : 0;
    }
    int ret = 0;
    for (int i = min; i <= Math.min(9, s); i++) {
      ret += dfs(n - 1, s - i, i + 1);
    }
    return ret;
  }
}

