				ans.add(list[index]);
				index = 0;
			}
		}
		Collections.sort(ans);
		for(int i = 0; i < ans.size() - 1; i++){
			System.out.print(ans.get(i) + " ");
		}
		System.out.println(ans.get(ans.size()-1));
