@implementation FastScanner

- (instancetype)initWithInputStream:(NSInputStream *)stream {
    self = [super init];
    if (self) {
        _in = stream;
        _buffer = [NSMutableData dataWithLength:1024];
        _length = 0;
        _p = 0;
    }
    return self;
}

- (BOOL)hasNextByte {
    if (_p < _length) return YES;
    else {
        _p = 0;
        [_in readIntoBuffer:_buffer maxLength:_buffer.length];
        _length = _buffer.length;
        if (_length <= 0) return NO;
    }
    return YES;
}

- (int)readByte {
    if ([self hasNextByte] == YES) return [_buffer byteAtIndex:_p++];
    return -1;
}

- (BOOL)isPrintable:(int)n {
    return n >= 33 && n <= 126;
}

- (void)skip {
    while ([self hasNextByte] && ![[self readByte] isPrintable]) _p++;
}

- (BOOL)hasNext {
    [self skip];
    return [self hasNextByte];
}

- (NSString *)next {
    if (![self hasNext]) throw [NSException exceptionWithName:@"NSException" reason:@"No next element" userInfo:nil];
    NSMutableString *sb = [NSMutableString string];
    int t = [self readByte];
    while ([[self readByte] isPrintable]) {
        [sb appendFormat:@"%c", t];
        t = [self readByte];
    }
    return sb;
}

- (NSArray<NSString *> *)nextArray:(int)n {
    NSMutableArray<NSString *> *ar = [NSMutableArray arrayWithCapacity:n];
    for (int i = 0; i < n; i++) [ar addObject:[self next]];
    return ar;
}

- (int)nextInt {
    return [self nextLong];
}

- (NSArray<NSNumber *> *)nextIntArray:(int)n {
    NSMutableArray<NSNumber *> *ar = [NSMutableArray arrayWithCapacity:n];
    for (int i = 0; i < n; i++) [ar addObject:@[[self nextInt]]];
    return ar;
}

- (long long)nextLong {
    if (![self hasNext]) throw [NSException exceptionWithName:@"NSException" reason:@"No next element" userInfo:nil];
    BOOL minus = NO;
    int temp = [self readByte];
    if (temp == '-') {
        minus = YES;
        temp = [self readByte];
    }
    if (temp < '0' || temp > '9') throw [NSException exceptionWithName:@"NSException" reason:@"Invalid character" userInfo:nil];
    long long n = 0;
    while ([[self readByte] isPrintable]) {
        if (temp >= '0' && temp <= '9') {
            n *= 10;
            n += temp - '0';
        } else throw [NSException exceptionWithName:@"NSException" reason:@"Invalid character" userInfo:nil];
        temp = [self readByte];
    }
    return minus ? -n : n;
}

- (NSArray<NSNumber *> *)nextLongArray:(int)n {
    NSMutableArray<NSNumber *> *ar = [NSMutableArray arrayWithCapacity:n];
    for (int i = 0; i < n; i++) [ar addObject:@[[self nextLong]]];
    return ar;
}

- (double)nextDouble {
    return [[self next] doubleValue];
}

- (NSArray<NSNumber *> *)nextDoubleArray:(int)n {
    NSMutableArray<NSNumber *> *ar = [NSMutableArray arrayWithCapacity:n];
    for (int i = 0; i < n; i++) [ar addObject:@[[self nextDouble]]];
    return ar;
}

