@implementation Methods

- (void)print:(id)object {
    NSLog(@"%@", object);
}

- (void)yesno:(BOOL)b {
    NSLog(@"%@", b ? @"Yes" : @"No");
}

- (void)YESNO:(BOOL)b {
    NSLog(@"%@", b ? @"YES" : @"NO");
}

- (int)max:(int *)ar {
    NSArray *sorted = [NSArray arrayWithArray:[NSArray arrayWithArray:ar]];
    return [sorted lastObject];
}

- (int)min:(int *)ar {
    NSArray *sorted = [NSArray arrayWithArray:[NSArray arrayWithArray:ar]];
    return [sorted firstObject];
}

- (long long)gcd:(long long)a:(long long)b {
    return b > 0 ? [self gcd:b:a%b] : a;
}

- (long long)lcm:(long long)a:(long long)b {
    return a / [self gcd:a:b] * b;
}

- (long long)factorial:(int)i {
    if (i == 1) return 1;
    else return i * [self factorial:i-1];
}

- (int)manhat:(int)x1:(int)y1:(int)x2:(int)y2 {
    return abs(x1 - x2) + abs(y1 - y2);
}

- (double)euclid:(double)x1:(double)y1:(double)x2:(double)y2 {
    return sqrt((x2 - x1)*(x2 - x1) + (y2 - y1)*(y2 - y1));
}

- (BOOL)isPrime:(int)n {
    if (n == 2) return YES;
    if (n < 2 || n % 2 == 0) return NO;
    for (int i = 3; i <= sqrt(n); i += 2) if (n % i == 0) return NO;
    return YES;
}

@end

@interface Main : NSObject

- (void)solve:(FastScanner *)in out:(NSOutputStream *)out methods:(Methods *)ms;

@end

@implementation Main

- (void)solve:(FastScanner *)in out:(NSOutputStream *)out methods:(Methods *)ms {
    int squareNum = 0, diamondNum = 0;
    while ([in hasNext] == YES) {
        NSString *temp = [in next];
        NSArray *a = [temp componentsSeparatedByString:@","];

        int a0 = [a[0] intValue];
        int a1 = [a[1] intValue];
        int a2 = [a[2] intValue];

        if (a2*a2 == a0*a0 + a1*a1) {
            squareNum++;
        }
        else if (a0 == a1) {
            diamondNum++;
        }
    }
    [out write:[NSString stringWithFormat:@"%d", squareNum] dataUsingEncoding:NSUTF8StringEncoding];
    [out write:@"\n" dataUsingEncoding:NSUTF8StringEncoding];
    [out write:[NSString stringWithFormat:@"%d", diamondNum] dataUsingEncoding:NSUTF8StringEncoding];
}

@end

