@implementation IO

- (instancetype)initWithInputStream:(NSInputStream *)inputStream {
    self = [super init];
    if (self) {
        _inputStream = inputStream;
        _buffer = [NSMutableData dataWithLength:1024];
        _ptr = 0;
        _buflen = 0;
    }
    return self;
}

- (BOOL)hasNextByte {
    if (_ptr < _buflen) {
        return YES;
    } else {
        _ptr = 0;
        NSInteger readBytes = [_inputStream read:[_buffer mutableBytes] maxLength:[_buffer length]];
        if (readBytes <= 0) {
            return NO;
        }
        _buflen = readBytes;
        return YES;
    }
}

- (int)readByte {
    if ([self hasNextByte]) {
        return [_buffer bytes][_ptr++];
    } else {
        return -1;
    }
}

- (BOOL)isPrintableChar:(int)c {
    return c >= 33 && c <= 126;
}

- (BOOL)isNewLine:(int)c {
    return c == '\n' || c == '\r';
}

- (void)skipUnprintable {
    while ([self hasNextByte] && ![self isPrintableChar:[self readByte]]) {
        _ptr++;
    }
}

- (void)skipNewLine {
    while ([self hasNextByte] && ![self isNewLine:[self readByte]]) {
        _ptr++;
    }
}

- (BOOL)hasNext {
    [self skipUnprintable];
    return [self hasNextByte];
}

- (BOOL)hasNextLine {
    [self skipNewLine];
    return [self hasNextByte];
}

- (NSString *)next {
    if (![self hasNext]) {
        return nil;
    }
    NSMutableString *sb = [NSMutableString string];
    int b = [self readByte];
    while ([self isPrintableChar:b]) {
        [sb appendString:[NSString stringWithFormat:@"%c", b]];
        b = [self readByte];
    }
    return sb;
}

- (NSArray<NSNumber *> *)nextIntArray:(NSInteger)len {
    if (![self hasNext]) {
        return nil;
    }
    NSMutableArray<NSNumber *> *a = [NSMutableArray arrayWithCapacity:len];
    int b = [self readByte];
    while ([self isPrintableChar:b]) {
        if (a.count == len) {
            return nil;
        }
        NSInteger n = 0;
        BOOL minus = NO;
        if (b == '-') {
            minus = YES;
            b = [self readByte];
        }
        if (b < '0' || b > '9') {
            return nil;
        }
        while (TRUE) {
            if (b >= '0' && b <= '9') {
                n *= 10;
                n += b - '0';
            } else if (b == -1 || ![self isPrintableChar:b]) {
                if (minus) {
                    n = -n;
                }
                [a addObject:@(n)];
                break;
            } else {
                return nil;
            }
            b = [self readByte];
        }
    }
    return a;
}

- (NSString *)nextLine {
    if (![self hasNextLine]) {
        return nil;
    }
    NSMutableString *sb = [NSMutableString string];
    int b = [self readByte];
    while (![self isNewLine:b]) {
        [sb appendString:[NSString stringWithFormat:@"%c", b]];
        b = [self readByte];
    }
    return sb;
}

- (long long)nextLong {
    if (![self hasNext]) {
        return 0;
    }
    long long n = 0;
    BOOL minus = NO;
    int b = [self readByte];
    if (b == '-') {
        minus = YES;
        b = [self readByte];
    }
    if (b < '0' || b > '9') {
        return 0;
    }
    while (TRUE) {
        if (b >= '0' && b <= '9') {
            n *= 10;
            n += b - '0';
        } else if (b == -1 || ![self isPrintableChar:b]) {
            return minus ? -n : n;
        } else {
            return 0;
        }
        b = [self readByte];
    }
}

- (NSInteger)nextInt {
    long long nl = [self nextLong];
    if (nl < INT_MIN || nl > INT_MAX) {
        return 0;
    }
    return (NSInteger)nl;
}

- (char)nextChar {
    if (![self hasNext]) {
        return 0;
    }
    return [self readByte];
}

- (double)nextDouble {
    return [self nextLong];
}

