        @SuppressWarnings("unused")
        public void solve(int testNumber, FastScanner in, PrintWriter out) {
            final int N = in.nextInt();
            for (int i = 0; i < N; i++) {

                List<Integer> list = new ArrayList<Integer>();
                for (int j = 0; j < 10; j++) {
                    list.add(in.nextInt());
                }

                out.println(dfs(list, 0, -1, -1) ? "YES" : "NO");
            }
        }

        private boolean dfs(List<Integer> list, int index, int bTop, int cTop) {
            if (index >= list.size()) {
                return true;
            }
            if (list.get(index) > bTop && dfs(list, index + 1, list.get(index), cTop)) {
                return true;
            }
            if (list.get(index) > cTop && dfs(list, index + 1, bTop, list.get(index))) {
                return true;
            }
            return false;
        }

    }

    static final class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1024];
        private int ptr = 0;
        private int buflen = 0;

        public FastScanner(InputStream in) {
            this.in = in;
        }

        private boolean hasNextByte() {
            if (ptr < buflen) {
                return true;
            } else {
                ptr = 0;
                try {
                    buflen = in.read(buffer);
                } catch (IOException e) {
                    e.printStackTrace();
                }
                if (buflen <= 0) {
                    return false;
                }
            }
            return true;
        }

        private int readByte() {
            if (hasNextByte()) return buffer[ptr++];
            else return -1;
        }

        private static boolean isPrintableChar(int c) {
            return 33 <= c && c <= 126;
        }

        private void skipUnprintable() {
            while (hasNextByte() && !isPrintableChar(buffer[ptr])) ptr++;
        }

        public boolean hasNext() {
            skipUnprintable();
            return hasNextByte();
        }

        public int nextInt() {
            if (!hasNext()) throw new NoSuchElementException();
            int n = 0;
            boolean minus = false;
            int b = readByte();
            if (b == '-') {
