#import <Foundation/Foundation.h>

@interface FastScanner : NSObject

- (instancetype)initWithInputStream:(NSInputStream *)inputStream;

- (BOOL)hasNext;
- (NSInteger)nextInt;

@end

@implementation FastScanner

- (instancetype)initWithInputStream:(NSInputStream *)inputStream {
    self = [super init];
    if (self) {
        self.inputStream = inputStream;
        self.buffer = [NSMutableData dataWithLength:1024];
        self.ptr = 0;
        self.buflen = 0;
    }
    return self;
}

- (BOOL)hasNext {
    [self skipUnprintable];
    return [self hasNextByte];
}

- (NSInteger)nextInt {
    if (![self hasNext]) {
        NSLog(@"No more input");
        return 0;
    }
    NSInteger n = 0;
    BOOL minus = NO;
    NSInteger b = [self readByte];
    if (b == '-') {
        minus = YES;
        b = [self readByte];
    }
    if (b < '0' || b > '9') {
        NSLog(@"Invalid input");
        return 0;
    }
    while (true) {
        if (b >= '0' && b <= '9') {
            n *= 10;
            n += b - '0';
        } else if (b == -1 || ![self isPrintableChar:b]) {
            return minus ? -n : n;
        } else {
            NSLog(@"Invalid input");
            return 0;
        }
        b = [self readByte];
    }
}

- (BOOL)hasNextByte {
    if (self.ptr < self.buflen) {
        return YES;
    } else {
        self.ptr = 0;
        [self.inputStream read:self.buffer maxLength:1024];
        self.buflen = [self.inputStream streamStatus];
        if (self.buflen <= 0) {
            return NO;
        }
    }
    return YES;
}

- (NSInteger)readByte {
    if ([self hasNextByte]) {
        return [self.buffer byteAtIndex:self.ptr++];
    } else {
        return -1;
    }
}

- (BOOL)isPrintableChar:(NSInteger)c {
    return c >= 33 && c <= 126;
}

- (void)skipUnprintable {
    while ([self hasNextByte] && ![self isPrintableChar:[self.buffer byteAtIndex:self.ptr]]) {
        self.ptr++;
    }
}

@end

