- (int)readInt {
    int result = 0;
    BOOL negative = NO;
    char c;

    while ((c = [self readByte]) != EOF && !isdigit(c)) {
        if (c == '-') {
            negative = YES;
        }
    }

    while (c != EOF && isdigit(c)) {
        result = result * 10 + (c - '0');
        c = [self readByte];
    }

    return negative ? -result : result;
}

- (char)readByte {
    static char buffer[2048];
    static int p = 0, buflen = 0;
    if (p >= buflen) {
        p = 0;
