- (int)ccw:(P *)p {
    Vec *a = [[Vec alloc] initWithPoints:self.s t:p];
    Vec *b = [[Vec alloc] initWithPoints:self.s t:self.t];
    if (fabs(a.crossProduct(b)) < EPS) {
        if (fabs(a.dotProduct(b)) < EPS) {
            return 0;
        }
        return a.dotProduct(b) < 0 ? 2 : -2;
