    return self.ccw(o.s) * self.ccw(o.t) < 0 && o.ccw(self.s) * o.ccw(self.t) < 0 ||
           self.ccw(o.s) * self.ccw(o.t) < 0 && o.ccw(self.s) * o.ccw(self.t) < 0;
