- (P *)symmetricPoint:(P *)p {
    if (self.s.x == self.t.x) {
        return [[P alloc] initWithX:p.x + (self.s.x - p.x) * 2 y:p.y];
    } else if (self.s.y == self.t.y) {
        return [[P alloc] initWithX:p.x y:p.y + (self.s.y - p.y) * 2];
    } else {
        double alpha = (self.s.y - self.t.y) / (self.s.x - self.t.x);
        double beta = self.s.y - self.s.x * alpha;
        double x = (2 * p.y * alpha - 2 * alpha * beta + p.x - alpha * alpha * p.x) / (alpha * alpha + 1);
        double y = (p.x - x) / alpha + p.y;
        return [[P alloc] initWithX:x y:y];
    }
