+ (int)convexHull:(P **)p con:(P **)con {
    int n = 4;
    if (n < 3) {
        return 0;
    }
    qsort(p, n, sizeof(P *), ^(const void *a, const void *b) {
        P *pa = *(P **)a;
        P *pb = *(P **)b;
        if (fabs(pa->x - pb->x) < EPS) {
            return (pa->y < pb->y) ? -1 : (pa->y > pb->y) ? 1 : 0;
        }
        return (pa->x < pb->x) ? -1 : 1;
    });
    int k = 0;
    for (int i = 0; i < n; i++) {
        while (k >= 2 && ccw(con[k - 2], con[k - 1], p[i]) == -1) {
            k--;
        }
        con[k++] = p[i];
    }
    int t = k;
    for (int i = n - 2; i >= 0; i--) {
        while (k > t && ccw(con[k - 2], con[k - 1], p[i]) == -1) {
            k--;
        }
        con[k++] = p[i];
    }
    return k - 1;
}

+ (int)ccw:(P *)p1 p2:(P *)p2 p3:(P *)p3 {
    Vec *a = [[Vec alloc] initWithPoints:p1 p2:p2];
    Vec *b = [[Vec alloc] initWithPoints:p1 p3:p3];
    if (fabs(a.crossProduct(b)) < EPS) {
        if (fabs(a.dotProduct(b)) < EPS) {
            return 0;
        }
        return a.dotProduct(b) < 0 ? 2 : -2;
    }
    return a.crossProduct(b) < 0 ? -1 : 1;
}

