#import <stdio.h>
#import <stdlib.h>

typedef struct {
    double x;
    double y;
} P;

int ccw(P p1, P p2, P p3) {
    double a = (p2.x - p1.x) * (p3.y - p1.y) - (p2.y - p1.y) * (p3.x - p1.x);
    if (a < 0) {
        return -1;
    } else if (a > 0) {
        return 1;
    } else {
        return 0;
    }
}

double area(P *p, int n) {
    double a = 0;
    for (int i = 0; i < n; i++) {
        a += p[i].x * p[(i + 1) % n].y - p[i].y * p[(i + 1) % n].x;
    }
    return fabs(a) / 2;
}

P* convexHull(P *p, int n) {
    if (n < 3) {
        return p;
    }

    int i, j, k;
    int top = 0;
    P *ch = malloc((n + 1) * sizeof(P));

    qsort(p, n, sizeof(P), ^(const void *a, const void *b) {
        const P *pa = (const P *)a;
        const P *pb = (const P *)b;
        if (pa->x < pb->x) {
            return -1;
        } else if (pa->x > pb->x) {
            return 1;
        } else {
            return pa->y < pb->y ? -1 : pa->y > pb->y ? 1 : 0;
        }
    });

    for (i = 0; i < n; i++) {
        while (top >= 2 && ccw(ch[top - 2], ch[top - 1], p[i]) <= 0) {
            top--;
        }
        ch[top++] = p[i];
    }

    int t = top;
    for (i = n - 2; i >= 0; i--) {
        while (top >= t + 2 && ccw(ch[top - 2], ch[top - 1], p[i]) <= 0) {
            top--;
        }
        ch[top++] = p[i];
    }

    ch[top - 1] = ch[0];
    return ch;
}

int main() {
    P p[] = {{0, 0}, {1, 0}, {1, 1}, {0, 1}};
    int n = sizeof(p) / sizeof(p[0]);
    P *ch = convexHull(p, n);
    double a = area(ch, n);
    printf("%f\n", a);
    free(ch);
    return 0;
}

