+ (P *)convexHull:(P **)p {
    int n = 4;
    if (n < 3) {
        return p;
    }

    NSArray *sortedP = [NSArray arrayWithObjects:p[0], p[1], p[2], p[3], nil];
    sortedP = [sortedP sortedArrayUsingSelector:@selector(compare:)];

    NSMutableArray *lower = [NSMutableArray array];
    [lower addObject:sortedP[0]];
    [lower addObject:sortedP[1]];
    for (int i = 2; i < n; i++) {
        [lower addObject:sortedP[i]];
        while ([lower count] >= 3) {
            int k = [lower count] - 1;
            if ([self ccw:lower[k - 2] p2:lower[k - 1] p3:lower[k]] == -1 && [self ccw:lower[k - 1] p2:lower[k] p3:lower[k - 2]] == -1) {
                break;
            }
            [lower removeObjectAtIndex:k - 1];
        }
    }

    NSMutableArray *upper = [NSMutableArray array];
    [upper addObject:sortedP[n - 1]];
    [upper addObject:sortedP[n - 2]];
    for (int i = n - 3; i >= 0; i--) {
        [upper addObject:sortedP[i]];
        while ([upper count] >= 3) {
            int k = [upper count] - 1;
            if ([self ccw:upper[k - 2] p2:upper[k - 1] p3:upper[k]] == -1 && [self ccw:upper[k - 1] p2:upper[k] p3:upper[k - 2]] == -1) {
                break;
            }
            [upper removeObjectAtIndex:k - 1];
        }
    }

    [upper removeObjectAtIndex:0];
    [upper removeObjectAtIndex:[upper count] - 1];
    int N = [lower count] + [upper count];
    P *res[N];
    int x = 0;
    for (P *q in upper) {
        res[x++] = q;
    }
    for (P *q in lower) {
        res[x++] = q;
    }

    return res;
}

