    if (a.crossProduct(b) > EPS) return -1;
    if (a.dotProduct(b) < EPS) return 2;
    if (a.norm() < b.norm()) return -2;
    return 0;
}

double area(P *p, int n) {
    if (n < 3) return 0;
    double a = 0;
    for (int i = 0; i < n; i++) {
        a += p[i].x * p[(i + 1) % n].y - p[i].y * p[(i + 1) % n].x;
    }
    return fabs(a / 2);
}

P *convexHull(P *p, int n) {
    if (n < 3) return p;
    qsort(p, n, sizeof(P), ^(const void *a, const void *b) {
        P *pa = (P *)a;
        P *pb = (P *)b;
        if (pa->x == pb->x) return pa->y - pb->y;
        return pa->x - pb->x;
    });
    NSMutableArray *lower = [NSMutableArray arrayWithCapacity:n];
    [lower addObject:&p[0]];
    [lower addObject:&p[1]];
    for (int i = 2; i < n; i++) {
        [lower addObject:&p[i]];
        while ([lower count] >= 3) {
            int k = [lower count] - 1;
            if (ccw(*[lower objectAtIndex:k - 2], *([lower objectAtIndex:k - 1]), *([lower objectAtIndex:k])) == -1 &&
                ccw(*([lower objectAtIndex:k - 1]), *([lower objectAtIndex:k]), *([lower objectAtIndex:k - 2])) == -1) {
                break;
            }
            [lower removeObjectAtIndex:k - 1];
        }
    }
    NSMutableArray *upper = [NSMutableArray arrayWithCapacity:n];
    [upper addObject:&p[n - 1]];
    [upper addObject:&p[n - 2]];
    for (int i = n - 3; i >= 0; i--) {
        [upper addObject:&p[i]];
        while ([upper count] >= 3) {
            int k = [upper count] - 1;
            if (ccw(*[upper objectAtIndex:k - 2], *([upper objectAtIndex:k - 1]), *([upper objectAtIndex:k])) == -1 &&
                ccw(*([upper objectAtIndex:k - 1]), *([upper objectAtIndex:k]), *([upper objectAtIndex:k - 2])) == -1) {
                break;
            }
            [upper removeObjectAtIndex:k - 1];
        }
    }
    [upper removeObjectAtIndex:0];
    [upper removeObjectAtIndex:[upper count] - 1];
    int N = [lower count] + [upper count];
    P *res = (P *)malloc(N * sizeof(P));
    int x = 0;
    for (P *q in upper) {
        res[x++] = *q;
    }
    for (P *q in lower) {
        res[x++] = *q;
    }
    return res;
}

int main(int argc, const char * argv[]) {
    @autoreleasepool {
        NSFileHandle *fileHandle = [NSFileHandle fileHandleForReadingAtPath:@"input.txt"];
        NSData *data = [fileHandle readDataToEndOfFile];
        NSString *inputString = [[NSString alloc] initWithData:data encoding:NSUTF8StringEncoding];
        NSArray *lines = [inputString componentsSeparatedByString:@"\n"];
        for (NSString *line in lines) {
            NSArray *coordinates = [line componentsSeparatedByString:@", "];
            P *points = (P *)malloc(4 * sizeof(P));
            for (int i = 0; i < 4; i++) {
                NSArray *coords = [coordinates[i] componentsSeparatedByString:@", "];
                points[i] = (P){[coords[0] doubleValue], [coords[1] doubleValue]};
            }
            P *convexHullPoints = convexHull(points, 4);
            double areaValue = area(convexHullPoints, 4);
            if (areaValue < EPS) {
                NSLog(@"NO");
            } else {
                NSLog(@"YES");
            }
            free(convexHullPoints);
            free(points);
        }
    }
