    return [[Complex alloc] initWithReal:_re - other.re imaginary:_im - other.im];
}

- (Complex *)mul:(Complex *)other {
    return [[Complex alloc] initWithReal:_re * other.re - _im * other.im imaginary:_re * other.im + _im * other.re];
