    return self;
}

- (instancetype)initWithPoints:(XPoint *)p1 p2:(XPoint *)p2 {
    self = [super init];
    if (self) {
        if (p1.x != p2.x) {
            _p = -(p1.y - p2.y) / (p1.x - p2.x);
            _q = 1;
            _r = p1.x * _p + p1.y;
        } else {
            if (p1.y != p2.y) {
                _p = 1;
                _q = 0;
                _r = 0;
            } else {
                _p = 1;
                _q = 1;
                _r = 1;
            }
        }
    }
    return self;
}

- (BOOL)isTheSameSide:(XPoint *)x y:(XPoint *)y {
    double result = (self.calcPX_QY(x.x, x.y) - self.r)
                    * (self.calcPX_QY(y.x, y.y) - self.r);
    return (result > 0) ? YES : NO;
}

- (double)calcPX_QY:(double)x y:(double)y {
    return x * _p + y * _q;
}

