- (void)processInput:(NSString *)input {
    NSArray *points = [input componentsSeparatedByString:@","];

    NSMutableArray *a = [[NSMutableArray alloc] init];
    for (int i = 0; i < 4; i++) {
        NSString *xStr = points[i*2];
        NSString *yStr = points[i*2+1];

        double x = [xStr doubleValue];
        double y = [yStr doubleValue];

        NSValue *point = [NSValue valueWithCGPoint:CGPointMake(x, y)];
        [a addObject:point];
    }

    [a sortUsingComparator:^NSComparisonResult(id obj1, id obj2) {
        CGPoint p1 = [obj1 CGPointValue];
        CGPoint p2 = [obj2 CGPointValue];

        if (p1.x < p2.x) {
            return NSOrderedAscending;
        } else if (p1.x > p2.x) {
            return NSOrderedDescending;
        } else if (p1.y < p2.y) {
            return NSOrderedAscending;
        } else if (p1.y > p2.y) {
            return NSOrderedDescending;
        } else {
            return NSOrderedSame;
        }
    }];

    int ans = 0;
    for (int i = 0; i < 4; i++) {
        NSValue *p1 = a[i];
        NSValue *p2 = a[(i+1)%4];
        NSValue *p3 = a[(i+2)%4];

        CGPoint a = [p1 CGPointValue];
        CGPoint b = [p2 CGPointValue];
        CGPoint c = [p3 CGPointValue];

        double crossProduct = (b.x - a.x) * (c.y - a.y) - (b.y - a.y) * (c.x - a.x);

        if (crossProduct > 0) {
            ans += 1;
        } else if (crossProduct < 0) {
            ans -= 1;
        }
    }

