- (int)relativeCCW:(Point2D *)point {
    double dx1 = _end.x - _start.x;
    double dy1 = _end.y - _start.y;
    double dx2 = point.x - _start.x;
    double dy2 = point.y - _start.y;
    double cross = dx1 * dy2 - dy1 * dx2;
    if (cross > 0) {
        return 1; // Point is to the left of the line
    } else if (cross < 0) {
        return -1; // Point is to the right of the line
    } else {
        return 0; // Point is on the line
    }
}
