    int width = 0;
    int height = 0;
    int u = 0;
    int l = 0;

    for (int i = 0; i < 8; i++) {
        for (int j = 0; j < 8; j++) {
            if (surface[i][j] == 1) {
                height = i;
                u = i;
                goto h1;
