            NSString *s = [[NSString alloc] initWithData:[stream readDataOfLength:mapsize] encoding:NSUTF8StringEncoding];
            if (i % 2 == 0) {
                for (int j = 0; j < 4; j++) {
                    int c = [s characterAtIndex:j] - '0';
                    pass[i][j * 2 + 1] = c;
