            if (bytesRead < 1024) {
                break;
            }
        }

        [inputStream close];

        NSArray *cards = [line componentsSeparatedByString:@","]; // Split the line into an array of cards

        NSMutableDictionary *cardCounts = [NSMutableDictionary dictionary]; // Dictionary to hold the count of each card
        for (NSString *card in cards) {
            int cardValue = [card intValue]; // Convert the card string to an integer value

            int count = [[cardCounts objectForKey:[NSNumber numberWithInt:cardValue]] intValue]; // Get the current count of the card
            count++; // Increment the count
            [cardCounts setObject:[NSNumber numberWithInt:count] forKey:[NSNumber numberWithInt:cardValue]]; // Update the count in the dictionary
        }

        BOOL hasFourCard = [cardCounts containsObjectWithValueForKey:[NSNumber numberWithInt:4]]; // Check if there are four of a kind
        BOOL hasThreeCard = [cardCounts containsObjectWithValueForKey:[NSNumber numberWithInt:3]]; // Check if there are three of a kind
        BOOL hasTwoPair = [cardCounts containsObjectWithValueForKey:[NSNumber numberWithInt:2]]; // Check if there are two pairs

