#import <Foundation/Foundation.h>
@interface Card : NSObject
@property (nonatomic, assign) NSInteger value;
@property (nonatomic, assign) NSInteger suit;
@end

@implementation Card
@end

@interface Hand : NSObject
@property (nonatomic, strong) NSMutableArray<Card *> *cards;
@end

@implementation Hand
- (instancetype)init {
    self = [super init];
    if (self) {
        _cards = [NSMutableArray array];
    }
    return self;
}

- (void)addCard:(Card *)card {
    [_cards addObject:card];
}

- (void)sortCards {
    NSSortDescriptor *descriptor = [[NSSortDescriptor alloc] initWithKey:@"value" ascending:YES];
    [_cards sortUsingDescriptors:@[descriptor]];
}

- (NSInteger)countOfCardsWithValue:(NSInteger)value {
    NSInteger count = 0;
    for (Card *card in _cards) {
        if (card.value == value) {
            count++;
        }
    }
    return count;
}

- (NSInteger)countOfCardsWithSuit:(NSInteger)suit {
    NSInteger count = 0;
    for (Card *card in _cards) {
        if (card.suit == suit) {
            count++;
        }
    }
    return count;
}

- (NSInteger)sumOfCardValues {
    NSInteger sum = 0;
    for (Card *card in _cards) {
        sum += card.value;
    }
    return sum;
}

- (BOOL)isStraight {
    NSInteger previousValue = 0;
    for (Card *card in _cards) {
        if (previousValue == 0) {
            previousValue = card.value;
        } else {
            if (card.value != previousValue + 1) {
                return NO;
            }
            previousValue = card.value;
        }
    }
    return YES;
}

- (BOOL)isFlush {
    NSInteger firstSuit = _cards[0].suit;
    for (Card *card in _cards) {
        if (card.suit != firstSuit) {
            return NO;
        }
    }
    return YES;
}

