#import <Foundation/Foundation.h>

@interface Methods : NSObject

- (void)print:(id)ar;
- (int)max:(int[])ar;
- (int)min:(int[])ar;
- (long)gcd:(long)a :(long)b;
- (long)lcm:(long)a :(long)b;
- (long)factorial:(int)i;
- (int)manhat:(int)x1 :(int)y1 :(int)x2 :(int)y2;
- (double)euclid:(double)x1 :(double)y1 :(double)x2 :(double)y2;
- (BOOL)isPrime:(int)n;

@end

@implementation Methods

- (void)print:(id)ar {
    NSLog(@"%@", ar);
}

- (int)max:(int[])ar {
    NSArray *sortedArray = [NSArray arrayWithArray:ar];
    sortedArray = [sortedArray sortedArrayUsingSelector:@selector(compare:)];
    return [sortedArray lastObject];
}

- (int)min:(int[])ar {
    NSArray *sortedArray = [NSArray arrayWithArray:ar];
    sortedArray = [sortedArray sortedArrayUsingSelector:@selector(compare:)];
    return [sortedArray firstObject];
}

- (long)gcd:(long)a :(long)b {
    if (b > 0) {
        return [self gcd:b :(a % b)];
    }
    return a;
}

- (long)lcm:(long)a :(long)b {
    return a / [self gcd:a :b] * b;
}

- (long)factorial:(int)i {
    if (i == 1) {
        return 1;
    }
    return i * [self factorial:i - 1];
}

- (int)manhat:(int)x1 :(int)y1 :(int)x2 :(int)y2 {
    return abs(x1 - x2) + abs(y1 - y2);
}

- (double)euclid:(double)x1 :(double)y1 :(double)x2 :(double)y2 {
    return sqrt(pow(x2 - x1, 2) + pow(y2 - y1, 2));
}

- (BOOL)isPrime:(int)n {
    if (n == 2) {
        return YES;
    }
    if (n < 2 || n % 2 == 0) {
        return NO;
    }
    for (int i = 3; i <= sqrt(n); i += 2) {
        if (n % i == 0) {
            return NO;
        }
    }
    return YES;
