@implementation FastScanner

- (instancetype)initWithInputStream:(NSInputStream *)stream {
    self = [super init];
    if (self) {
        _in = stream;
        _buffer = [NSMutableData dataWithLength:1024];
        _length = 0;
        _p = 0;
    }
    return self;
}

- (BOOL)hasNextByte {
    if (_p < _length) return YES;
    else {
        _p = 0;
        [_in readIntoBuffer:_buffer withLength:1024];
        _length = _buffer.length;
        if (_length <= 0) return NO;
    }
    return YES;
}

- (int)readByte {
    if ([self hasNextByte] == YES) return [_buffer bytes][_p++];
    return -1;
}

- (BOOL)isPrintable:(int)n {
    return 33 <= n && n <= 126;
}

- (void)skip {
    while ([self hasNextByte] && ![self isPrintable:[self readByte]]) {}
}

- (BOOL)hasNext {
    [self skip];
    return [self hasNextByte];
}

- (NSString *)next {
    if (![self hasNext]) throw [NSException exceptionWithName:@"NoNextException" reason:@"No more elements" userInfo:nil];
    NSMutableString *sb = [NSMutableString string];
    int t = [self readByte];
    while ([self isPrintable:t]) {
        [sb appendFormat:@"%c", t];
        t = [self readByte];
    }
    return sb;
}

- (NSArray *)nextArray:(int)n {
    NSMutableArray *ar = [NSMutableArray arrayWithCapacity:n];
    for (int i=0; i<n; i++) [ar addObject:[self next]];
    return ar;
}

- (int)nextInt {
    return (int)[self nextLong];
}

- (int *)nextIntArray:(int)n {
    int *ar = malloc(sizeof(int) * n);
    for (int i=0; i<n; i++) ar[i] = [self nextInt];
    return ar;
}

- (long long)nextLong {
    if (![self hasNext]) throw [NSException exceptionWithName:@"NoNextException" reason:@"No more elements" userInfo:nil];
    BOOL minus = NO;
    int temp = [self readByte];
    if (temp == '-') {
        minus = YES;
        temp = [self readByte];
    }
    if (temp < '0' || temp > '9') throw [NSException exceptionWithName:@"NumberFormatException" reason:@"Invalid character" userInfo:nil];
    long long n = 0;
    while ([self isPrintable:temp]) {
        if (temp >= '0' && temp <= '9') {
            n *= 10;
            n += temp - '0';
        }
        else throw [NSException exceptionWithName:@"NumberFormatException" reason:@"Invalid character" userInfo:nil];
        temp = [self readByte];
    }
    return minus ? -n : n;
}

- (long long *)nextLongArray:(int)n {
    long long *ar = malloc(sizeof(long long) * n);
    for (int i=0; i<n; i++) ar[i] = [self nextLong];
    return ar;
}

- (double)nextDouble {
    return [self nextDouble];
}

- (double *)nextDoubleArray:(int)n {
    double *ar = malloc(sizeof(double) * n);
    for (int i=0; i<n; i++) ar[i] = [self nextDouble];
    return ar;
}

- (void)close {
    [_in close];
}

