		String pre, post;
		for (int i = 0 ; i < length ; i++) {
			switch (expression[i].charAt(0)) {
			default: stack.push(expression[i]); break;
			case '+':
				post = stack.pop(); pre = stack.pop();
				stack.push("("+pre+" + "+post+")"); break;
