				stack.push("("+pre+" - "+post+")"); break;
			case '*':
				post = stack.pop(); pre = stack.pop();
				stack.push("("+pre+" * "+post+")"); break;
			case '/':
				post = stack.pop(); pre = stack.pop();
				stack.push("("+pre+" / "+post+")"); break;
			}
		}
		return stack.pop();
	}


