import java.util.*;
public class Main {
	int W,N;
	int[] v,w;
	int[] dp;
	public void solve(){
		for(int cc = 1;;cc++){
			W = nextInt();
			if(W == 0)break;

			N = nextInt();
			v = new int[N];
			w = new int[N];
			for(int i = 0;i < N;i++){
				String[] s = next().split(",");
				v[i] = Integer.parseInt(s[0]);
				w[i] = Integer.parseInt(s[1]);
			}

			dp = new int[W + 1];
			for(int i = 1;i <= N;i++){
				for(int j = W;j >= 0;j--){
					if(j + w[i - 1] <= W)dp[j + w[i - 1]] = Math.max(dp[j + w[i - 1]],dp[j] + v[i - 1]);
				}
			}
			int ans = 0;
			for(int j = 0;j <= W;j++){
				if(dp[ans] < dp[j]){
					ans = j;
				}
			}
			out.println("Case "+cc+":");
			out.println(dp[ans]);
			out.println(ans);
		}
	}

