@implementation NSInputStream (Custom)

- (int)readInt {
    int value = 0;
    BOOL negative = NO;
    BOOL started = NO;

    while (YES) {
        char c = [self read];
        if (c == EOF) break;

        if (c == '-') {
            negative = YES;
        } else if (c >= '0' && c <= '9') {
            value = value * 10 + (c - '0');
            started = YES;
        } else if (started) {
            break;
        }
    }

    return negative ? -value : value;
}

- (NSString *)readLine {
    NSMutableString *line = [NSMutableString string];

    while (YES) {
        char c = [self read];
        if (c == EOF || c == '\n') break;
        [line appendFormat:@"%c", c];
    }

    return line;
}

