				p[i] = Integer.valueOf(in[0]);
				w[i] = Integer.valueOf(in[1]);
			}
			for (int i = N - 1; i >= 0; i--) {
				for (int j = 0; j <= W; j++) {
					if (j - w[i] < 0) {
						dp[i][j] = dp[i + 1][j];
					} else {
						dp[i][j] = Math.max(dp[i + 1][j], dp[i + 1][j - w[i]]
