		for(int i = 1; i <= 9; i++){
			if(tehai[i] < 2) continue;
			int[] t = Arrays.copyOf(tehai, tehai.length);
			t[i] -= 2;
			if(can4(t)) return true;
		}
		return false;
	}

	boolean can4(int[] tehai){
		int sumAll = 0;
		for(int i = 1; i <= 9; i++){
