    }
    return self;
}

- (BOOL)hasNext {
    while ([self _hasNextByte] && ![[self _buffer] characterAtIndex:_ptr].isPrintableChar) {
        _ptr++;
    }
    return [self _hasNextByte];
}

- (NSString *)next {
    if (![self hasNext]) {
        return nil;
    }
    NSMutableString *sb = [NSMutableString string];
    int b = [self _readByte];
    while ([[self _buffer] characterAtIndex:b].isPrintableChar) {
        [sb appendString:[[self _buffer] characterAtIndex:b]];
        b = [self _readByte];
    }
    return sb;
}

