@implementation FastScanner
- (instancetype)initWithInputStream:(NSInputStream *)in {
    self = [super init];
    if (self) {
        _in = in;
        _buffer = [[NSMutableData alloc] initWithCapacity:1024];
        _ptr = 0;
        _buflen = 0;
    }
    return self;
}

- (BOOL)hasNextByte {
    if (_ptr < _buflen) {
        return YES;
    } else {
        _ptr = 0;
        [_in readIntoBuffer:[_buffer mutableBytes] maxLength:1024];
        _buflen = [_buffer length];
        if (_buflen <= 0) {
            return NO;
        }
    }
    return YES;
}

- (int)readByte {
    if ([self hasNextByte]) {
        return [_buffer byteAtIndex:_ptr++];
    } else {
        return -1;
    }
}

- (BOOL)isPrintableChar:(int)c {
    return c >= 33 && c <= 126;
}

- (BOOL)hasNext {
    while ([self hasNextByte] && ![[self buffer] isPrintableChar:[self buffer] byteAtIndex:_ptr]) {
        _ptr++;
    }
    return [self hasNextByte];
}

- (NSString *)next {
    if (![self hasNext]) {
        [NSException raise:NSInvalidArgumentException format:@"No more elements to read"];
    }
    NSMutableString *sb = [NSMutableString string];
    int b = [self readByte];
    while ([self isPrintableChar:b]) {
        [sb appendFormat:@"%c", b];
        b = [self readByte];
    }
    return sb;
}

- (NSString *)nextLine {
    if (![self hasNext]) {
        [NSException raise:NSInvalidArgumentException format:@"No more elements to read"];
    }
    NSMutableString *sb = [NSMutableString string];
    int b = [self readByte];
    while (b != 10) {
        [sb appendFormat:@"%c", b];
        b = [self readByte];
    }
    return sb;
}

- (long)nextLong {
    if (![self hasNext]) {
        [NSException raise:NSInvalidArgumentException format:@"No more elements to read"];
    }
    long n = 0;
    BOOL minus = NO;
    int b = [self readByte];
    if (b == '-') {
        minus = YES;
        b = [self readByte];
    }
    if (b < '0' || b > '9') {
        [NSException raise:NSInvalidArgumentException format:@"Invalid input for long"];
    }
    while (YES) {
        if ('0' <= b && b <= '9') {
            n *= 10;
            n += b - '0';
        } else if (b == -1 || ![self isPrintableChar:b]) {
            return minus ? -n : n;
        } else {
            [NSException raise:NSInvalidArgumentException format:@"Invalid input for long"];
        }
        b = [self readByte];
    }
}

- (int)nextInt {
    long nl = [self nextLong];
    if (nl < INT_MIN || nl > INT_MAX) {
        [NSException raise:NSInvalidArgumentException format:@"Invalid input for int"];
    }
    return (int)nl;
}

- (double)nextDouble {
    return [self nextDouble];
}
@end

