    if (![self hasNext]) {
        NSLog(@"No more elements");
        return nil;
    }
    NSMutableString *sb = [NSMutableString string];
    int t = [self readByte];
    while ([self buffer][t] >= 33 && [self buffer][t] <= 126) {
        [sb appendString:[NSString stringWithFormat:@"%c", [self buffer][t]]];
        t = [self readByte];
    }
    return sb;
}

