- (BOOL)hasNextByte;
- (int)readByte;
- (BOOL)isPrintable:(int)n;
- (void)skip;
- (BOOL)hasNext;
- (NSString *)next;
- (NSString **)nextArray:(int)n;
- (int)nextInt;
- (int *)nextIntArray:(int)n;
- (long long)nextLong;
- (long long *)nextLongArray:(int)n;
- (double)nextDouble;
- (double *)nextDoubleArray:(int)n;
- (void)close;

@end

@implementation FastScanner

- (instancetype)initWithInputStream:(NSInputStream *)stream {
    self = [super init];
    if (self) {
        _in = stream;
    }
    return self;
}

- (BOOL)hasNextByte {
    if (p < length) return YES;
    else {
        p = 0;
        [self readBuffer];
        if (length <= 0) return NO;
    }
    return YES;
}

- (int)readByte {
    if ([self hasNextByte] == YES) return buffer[p++];
    return -1;
}

- (BOOL)isPrintable:(int)n {return 33<=n&&n<=126;}

- (void)skip {
    while ([self hasNextByte] && ![[self isPrintable:self.readByte] boolValue]) p++;
}

- (BOOL)hasNext {
    [self skip];
    return [self hasNextByte];
}

- (NSString *)next {
    if (![self hasNext]) throw [NSException exceptionWithName:@"NSException" reason:@"No more input" userInfo:nil];
    NSMutableString *sb = [NSMutableString string];
    int t = [self readByte];
    while ([[self isPrintable:t] boolValue]) {
        [sb appendString:[NSString stringWithFormat:@"%c", t]];
        t = [self readByte];
    }
    return sb;
}

- (NSString **)nextArray:(int)n {
    NSString **ar = (NSString **)malloc(n * sizeof(NSString *));
    for (int i=0; i<n; i++) ar[i] = [self next];
    return ar;
}

- (int)nextInt {return (int)[self nextLong];}

- (int *)nextIntArray:(int)n {
    int *ar = (int *)malloc(n * sizeof(int));
    for (int i=0; i<n; i++) ar[i] = [self nextInt];
    return ar;
}

- (long long)nextLong {
    if (![self hasNext]) throw [NSException exceptionWithName:@"NSException" reason:@"No more input" userInfo:nil];
    BOOL minus = NO;
    int temp = [self readByte];
    if (temp == '-') {
        minus = YES;
        temp = [self readByte];
    }
    if (temp<'0' || '9'<temp) throw [NSException exceptionWithName:@"NSException" reason:@"Invalid input" userInfo:nil];
    long long n = 0;
    while ([[self isPrintable:temp] boolValue]) {
        if ('0'<=temp && temp<='9') {
            n *= 10;
            n += temp - '0';
        }
        else throw [NSException exceptionWithName:@"NSException" reason:@"Invalid input" userInfo:nil];
        temp = [self readByte];
    }
    return minus ? -n : n;
}

- (long long *)nextLongArray:(int)n {
    long long *ar = (long long *)malloc(n * sizeof(long long));
    for (int i=0; i<n; i++) ar[i] = [self nextLong];
    return ar;
}

- (double)nextDouble {return [self nextDouble];}

- (double *)nextDoubleArray:(int)n {
    double *ar = (double *)malloc(n * sizeof(double));
    for (int i=0; i<n; i++) ar[i] = [self nextDouble];
    return ar;
}

- (void)close {
    [_in close];
}

@end

@interface Methods : NSObject

- (void)print:(id)ar;
- (void)yesno:(BOOL)b;
- (void)YESNO:(BOOL)b;
- (int)max:(int *)ar;
- (int)min:(int *)ar;
- (long long)gcd:(long long)a:(long long)b;
- (long long)lcm:(long long)a:(long long)b;
- (long long)factorial:(int)i;
- (int)manhat:(int)x1:(int)y1:(int)x2:(int)y2;
- (double)euclid:(double)x1:(double)y1:(double)x2:(double)y2;
- (BOOL)isPrime:(int)n;

@end

@implementation Methods

- (void)print:(id)ar {
    NSLog(@"%@", ar);
}

- (void)yesno:(BOOL)b {
    NSLog(@"%@", b ? @"Yes" : @"No");
}

- (void)YESNO:(BOOL)b {
    NSLog(@"%@", b ? @"YES" : @"NO");
}

- (int)max:(int *)ar {
    int max = ar[0];
    for (int i=1; i<[ar count]; i++) {
        if (ar[i] > max) max = ar[i];
    }
    return max;
}

- (int)min:(int *)ar {
    int min = ar[0];
    for (int i=1; i<[ar count]; i++) {
        if (ar[i] < min) min = ar[i];
    }
    return min;
}

- (long long)gcd:(long long)a:(long long)b {
    return b>0 ? [self gcd:b:a%b] : a;
}

- (long long)lcm:(long long)a:(long long)b {
    return a/[self gcd:a:b] * b;
}

- (long long)factorial:(int)i {
    if (i==1) return 1;
    else return i*[self factorial:i-1];
}

- (int)manhat:(int)x1:(int)y1:(int)x2:(int)y2 {
    return abs(x1-x2) + abs(y1-y2);
}

- (double)euclid:(double)x1:(double)y1:(double)x2:(double)y2 {
    return sqrt((x2-x1)*(x2-x1)+(y2-y1)*(y2-y1));
}

- (BOOL)isPrime:(int)n {
    if (n==2) return YES;
    if (n<2 || n%2==0) return NO;
    for (int i=3; i<=sqrt(n); i+=2) if(n%i==0) return NO;
    return YES;
}

@end

@interface Main : NSObject

- (void)solve:(FastScanner *)in out:(NSOutputStream *)out ms:(Methods *)ms;

@end

@implementation Main

- (void)solve:(FastScanner *)in out:(NSOutputStream *)out ms:(Methods *)ms {
    double min = DBL_MAX;
    double max = DBL_MIN;
    while ([in hasNext] == YES) {
        double temp = [in nextDouble];
        min = fmin(min, temp);
        max = fmax(max, temp);
    }
    [out write:[NSString stringWithFormat:@"%f", max-min] dataUsingEncoding:NSUTF8StringEncoding];
}

@end

int main() {
    Main *main = [[Main alloc] init];
    FastScanner *in = [[FastScanner alloc] initWithInputStream:[NSInputStream inputStreamWithFileAtPath:@"input.txt"]];
    NSOutputStream *out = [[NSOutputStream outputStreamToFileAtPath:@"output.txt" append:NO] init];
    Methods *ms = [[Methods alloc] init];
    [main solve:in out:out ms:ms];
    [in close];
    [out close];
    return 0;
}

