@implementation FastScanner

- (instancetype)initWithInputStream:(NSInputStream *)stream {
    self = [super init];
    if (self) {
        in = stream;
        buffer = [NSMutableData dataWithLength:1024];
        length = 0;
        p = 0;
    }
    return self;
}

- (BOOL)hasNextByte {
    if (p < length) return YES;
    else {
        p = 0;
        length = [in read:[buffer mutableBytes] maxLength:1024];
        if (length <= 0) return NO;
    }
    return YES;
}

- (int)readByte {
    if ([self hasNextByte] == YES) return [buffer bytes][p++];
    return -1;
}

- (void)skip {
    while ([self hasNextByte] && !isPrintable([[buffer bytes] objectAtIndex:p])) p++;
}

- (BOOL)hasNext {
    [self skip];
    return [self hasNextByte];
}

- (NSString *)next {
    if (![self hasNext]) {
        [NSException raise:@"NSRangeException" format:@"No more elements"];
    }
    NSMutableString *sb = [NSMutableString string];
    int t = [self readByte];
    while (isPrintable(t)) {
        [sb appendFormat:@"%c", t];
        t = [self readByte];
    }
    return sb;
}

- (NSString *)nextArray:(int)n {
    NSString **ar = malloc(sizeof(NSString *) * n);
    for (int i=0; i<n; i++) ar[i] = [self next];
    return ar;
}

- (int)nextInt {
    return (int)[self nextLong];
}

- (int *)nextIntArray:(int)n {
    int *ar = malloc(sizeof(int) * n);
    for (int i=0; i<n; i++) ar[i] = [self nextInt];
    return ar;
}

- (long long)nextLong {
    if (![self hasNext]) {
        [NSException raise:@"NSRangeException" format:@"No more elements"];
    }
    BOOL minus = NO;
    int temp = [self readByte];
    if (temp == '-') {
        minus = YES;
        temp = [self readByte];
    }
    if (temp<'0' || '9'<temp) {
        [NSException raise:@"NumberFormatException" format:@"Invalid number"];
    }
    long long n = 0;
    while (isPrintable(temp)) {
        if ('0'<=temp && temp<='9') {
            n *= 10;
            n += temp - '0';
        }
        else {
            [NSException raise:@"NumberFormatException" format:@"Invalid number"];
        }
        temp = [self readByte];
    }
    return minus ? -n : n;
}

- (long long *)nextLongArray:(int)n {
    long long *ar = malloc(sizeof(long long) * n);
    for (int i=0; i<n; i++) ar[i] = [self nextLong];
    return ar;
}

- (double)nextDouble {
    return [self nextLong];
}

- (double *)nextDoubleArray:(int)n {
    double *ar = malloc(sizeof(double) * n);
    for (int i=0; i<n; i++) ar[i] = [self nextDouble];
    return ar;
}

- (void)close {
    [in close];
}

