@implementation Methods

- (void)print:(id)ar {
    NSLog(@"%@", ar);
}

- (void)yesno:(NSOutputStream *)out bool:(BOOL)b {
    NSString *result = b ? @"Yes" : @"No";
    [out write:result];
}

- (void)YESNO:(NSOutputStream *)out bool:(BOOL)b {
    NSString *result = b ? @"YES" : @"NO";
    [out write:result];
}

- (int)max:(int *)ar {
    int max = INT_MIN;
    for (int i = 0; i < sizeof(ar) / sizeof(ar[0]); i++) {
        if (ar[i] > max) {
            max = ar[i];
        }
    }
    return max;
}

- (int)min:(int *)ar {
    int min = INT_MAX;
    for (int i = 0; i < sizeof(ar) / sizeof(ar[0]); i++) {
        if (ar[i] < min) {
            min = ar[i];
        }
    }
    return min;
}

- (long)gcd:(long)a b:(long)b {
    if (b == 0) {
        return a;
    }
    return [self gcd:b a:(a % b)];
}

- (long)lcm:(long)a b:(long)b {
    return a * b / [self gcd:a b:b];
}

- (long)factorial:(int)i {
    if (i == 1) {
        return 1;
    }
    return i * [self factorial:i - 1];
}

- (int)manhat:(int)x1 y1:(int)y1 x2:(int)x2 y2:(int)y2 {
    return abs(x1 - x2) + abs(y1 - y2);
}

- (double)euclid:(double)x1 y1:(double)y1 x2:(double)x2 y2:(double)y2 {
    return sqrt(pow(x2 - x1, 2) + pow(y2 - y1, 2));
}

- (BOOL)isPrime:(int)n {
    if (n == 2) {
        return YES;
    }
    if (n < 2 || n % 2 == 0) {
        return NO;
    }
    for (int i = 3; i <= sqrt(n); i += 2) {
        if (n % i == 0) {
            return NO;
        }
    }
    return YES;
}

