#import <Foundation/Foundation.h>

@interface FastScanner : NSObject

- (instancetype)initWithInputStream:(NSInputStream *)stream;

- (BOOL)hasNextByte;
- (int)readByte;
- (BOOL)isPrintable:(int)n;
- (void)skip;
- (BOOL)hasNext;
- (NSString *)next;
- (NSArray<NSString *> *)nextArray:(int)n;
- (int)nextInt;
- (NSArray<NSNumber *> *)nextIntArray:(int)n;
- (long long)nextLong;
- (NSArray<NSNumber *> *)nextLongArray:(int)n;
- (double)nextDouble;
- (NSArray<NSNumber *> *)nextDoubleArray:(int)n;

@end

@implementation FastScanner

- (instancetype)initWithInputStream:(NSInputStream *)stream {
    self = [super init];
    if (self) {
        _in = stream;
    }
    return self;
}

- (BOOL)hasNextByte {
    if (p < length) return YES;
    else {
        p = 0;
        [self length];
        if (length <= 0) return NO;
    }
    return YES;
}

- (int)readByte {
    if ([self hasNextByte] == YES) return buffer[p++];
    return -1;
}

- (BOOL)isPrintable:(int)n {
    return 33 <= n && n <= 126;
}

- (void)skip {
    while ([self hasNextByte] && ![self isPrintable:buffer[p]]) p++;
}

- (BOOL)hasNext {
    [self skip];
    return [self hasNextByte];
}

- (NSString *)next {
    if (![self hasNext]) throw [NSException exceptionWithName:@"NoNext" reason:@"No next element" userInfo:nil];
    NSMutableString *sb = [NSMutableString string];
    int t = [self readByte];
    while ([self isPrintable:t]) {
        [sb appendFormat:@"%c", t];
        t = [self readByte];
    }
    return sb;
}

- (NSArray<NSString *> *)nextArray:(int)n {
    NSMutableArray<NSString *> *ar = [NSMutableArray arrayWithCapacity:n];
    for (int i=0; i<n; i++) [ar addObject:[self next]];
    return ar;
}

- (int)nextInt {
    return (int)[self nextLong];
}

- (NSArray<NSNumber *> *)nextIntArray:(int)n {
    NSMutableArray<NSNumber *> *ar = [NSMutableArray arrayWithCapacity:n];
    for (int i=0; i<n; i++) [ar addObject:@([self nextInt])];
    return ar;
}

- (long long)nextLong {
    if (![self hasNext]) throw [NSException exceptionWithName:@"NoNext" reason:@"No next element" userInfo:nil];
    BOOL minus = NO;
    int temp = [self readByte];
    if (temp == '-') {
        minus = YES;
        temp = [self readByte];
    }
    if (temp < '0' || '9' < temp) throw [NSException exceptionWithName:@"NumberFormatException" reason:@"Invalid number format" userInfo:nil];
    long long n = 0;
    while ([self isPrintable:temp]) {
        if ('0' <= temp && temp <= '9') {
            n *= 10;
            n += temp - '0';
        }
        else throw [NSException exceptionWithName:@"NumberFormatException" reason:@"Invalid number format" userInfo:nil];
        temp = [self readByte];
    }
    return minus ? -n : n;
}

- (NSArray<NSNumber *> *)nextLongArray:(int)n {
    NSMutableArray<NSNumber *> *ar = [NSMutableArray arrayWithCapacity:n];
    for (int i=0; i<n; i++) [ar addObject:@([self nextLong])];
    return ar;
}

- (double)nextDouble {
    return [self nextDouble];
}

- (NSArray<NSNumber *> *)nextDoubleArray:(int)n {
    NSMutableArray<NSNumber *> *ar = [NSMutableArray arrayWithCapacity:n];
    for (int i=0; i<n; i++) [ar addObject:@([self nextDouble])];
    return ar;
}

- (void)close {
    [_in close];
}

@end

@interface Methods : NSObject

- (void)print:(id)ar;
- (void)yesno:(BOOL)b out:(NSOutputStream *)out;
- (void)YESNO:(BOOL)b out:(NSOutputStream *)out;
- (int)max:(int *)ar length:(int)len;
