- (int)max:(int *)ar length:(int)len {
    int max = ar[0];
    for (int i=1; i<len; i++) {
        if (ar[i] > max) max = ar[i];
    }
    return max;
}

- (int)min:(int *)ar length:(int)len {
    int min = ar[0];
    for (int i=1; i<len; i++) {
        if (ar[i] < min) min = ar[i];
    }
    return min;
}

- (long long)gcd:(long long)a b:(long long)b {
    return b > 0 ? [self gcd:b a:a%b] : a;
}

- (long long)lcm:(long long)a b:(long long)b {
    return a / [self gcd:a b:b] * b;
}

- (long long)factorial:(int)i {
