- (double)euclid:(double)x1 y1:(double)y1 x2:(double)x2 y2:(double)y2 {
    return sqrt((x2 - x1)*(x2 - x1) + (y2 - y1)*(y2 - y1));
}

- (BOOL)isPrime:(int)n {
    if (n == 2) return YES;
    if (n < 2 || n % 2 == 0) return NO;
    for (int i=3; i<=sqrt(n); i+=2) if (n % i == 0) return NO;
    return YES;
}

