        _length = 0;
        _p = 0;
    }
    return self;
}

- (BOOL)hasNextByte {
    if (_p < _length) return YES;
    else {
        _p = 0;
        [_in readIntoBuffer:_buffer maxLength:1024];
        _length = [_buffer length];
        if (_length <= 0) return NO;
    }
    return YES;
}

- (int)readByte {
    if ([self hasNextByte] == YES) return [_buffer bytes][_p++];
    return -1;
}

- (BOOL)isPrintable:(int)n {
    return n >= 33 && n <= 126;
}

- (void)skip {
    while ([self hasNextByte] && ![self isPrintable:[self readByte]]) _p++;
}

- (BOOL)hasNext {
    [self skip];
    return [self hasNextByte];
}

- (NSString *)next {
    if (![self hasNext]) {
        [NSException raise:@"NSException" format:@"No more input available."];
    }
    NSMutableString *sb = [NSMutableString string];
    int t = [self readByte];
    while ([self isPrintable:t]) {
        [sb appendString:[NSString stringWithFormat:@"%c", t]];
        t = [self readByte];
    }
    return sb;
}

- (NSArray *)nextArray:(int)n {
    NSMutableArray *ar = [NSMutableArray arrayWithCapacity:n];
    for (int i = 0; i < n; i++) {
        [ar addObject:[self next]];
    }
