    if (![self hasNext]) {
        [NSException raise:@"NSException" format:@"No more input available."];
    }
    BOOL minus = NO;
    int temp = [self readByte];
    if (temp == '-') {
        minus = YES;
        temp = [self readByte];
    }
    if (temp < '0' || temp > '9') {
        [NSException raise:@"NSException" format:@"Invalid input."];
    }
