@interface FastScanner : NSObject

@property (nonatomic, strong) NSInputStream *in;
@property (nonatomic, strong) NSMutableData *buffer;
@property (nonatomic, assign) int length;
@property (nonatomic, assign) int p;

- (instancetype)initWithInputStream:(NSInputStream *)stream;

- (BOOL)hasNextByte;
- (int)readByte;
- (BOOL)isPrintable:(int)n;
- (void)skip;
- (BOOL)hasNext;
- (NSString *)next;
- (NSArray *)nextArray:(int)n;
- (int)nextInt;
- (NSArray *)nextIntArray:(int)n;
- (long)nextLong;
- (NSArray *)nextLongArray:(int)n;
- (double)nextDouble;
- (NSArray *)nextDoubleArray:(int)n;
- (void)close;

@end

@implementation FastScanner

- (instancetype)initWithInputStream:(NSInputStream *)stream {
    self = [super init];
    if (self) {
        self.in = stream;
        self.buffer = [[NSMutableData alloc] init];
        self.length = 0;
        self.p = 0;
    }
    return self;
}

- (BOOL)hasNextByte {
    if (self.p < self.length) return YES;
    else {
        self.p = 0;
        NSError *error;
        self.length = [self.in read:self.buffer.mutableBytes maxLength:self.buffer.length error:&error];
        if (self.length <= 0) return NO;
    }
    return YES;
}

- (int)readByte {
    if ([self hasNextByte] == YES) return [self.buffer bytes][self.p++];
    return -1;
}

- (BOOL)isPrintable:(int)n {return 33 <= n && n <= 126;}

- (void)skip {
    while ([self hasNextByte] && ![self isPrintable:[self.buffer bytes][self.p]]) self.p++;
}

- (BOOL)hasNext {
    [self skip];
    return [self hasNextByte];
}

- (NSString *)next {
    if (![self hasNext]) {
        [NSException raise:NSGenericException format:@"No more elements available"];
    }
    NSMutableString *sb = [NSMutableString string];
    int t = [self readByte];
    while ([self isPrintable:t]) {
        [sb appendString:[NSString stringWithFormat:@"%c", t]];
        t = [self readByte];
    }
    return sb;
}

- (NSArray *)nextArray:(int)n {
    NSMutableArray *ar = [NSMutableArray arrayWithCapacity:n];
    for (int i = 0; i < n; i++) [ar addObject:[self next]];
    return ar;
}

- (int)nextInt {
    return [[self next] intValue];
}

- (NSArray *)nextIntArray:(int)n {
    NSMutableArray *ar = [NSMutableArray arrayWithCapacity:n];
    for (int i = 0; i < n; i++) [ar addObject:[self nextInt]];
    return ar;
}

- (long)nextLong {
    if (![self hasNext]) {
        [NSException raise:NSGenericException format:@"No more elements available"];
    }
    BOOL minus = NO;
    int temp = [self readByte];
    if (temp == '-') {
        minus = YES;
        temp = [self readByte];
    }
    if (temp < '0' || '9' < temp) {
        [NSException raise:NSGenericException format:@"Invalid input format"];
    }
    long n = 0;
    while ([self isPrintable:temp]) {
        if ('0' <= temp && temp <= '9') {
            n *= 10;
            n += temp - '0';
        }
        else {
            [NSException raise:NSGenericException format:@"Invalid input format"];
        }
        temp = [self readByte];
    }
    return minus ? -n : n;
}

- (NSArray *)nextLongArray:(int)n {
    NSMutableArray *ar = [NSMutableArray arrayWithCapacity:n];
    for (int i = 0; i < n; i++) [ar addObject:[self nextLong]];
    return ar;
}

- (double)nextDouble {
    return [[self next] doubleValue];
}

- (NSArray *)nextDoubleArray:(int)n {
    NSMutableArray *ar = [NSMutableArray arrayWithCapacity:n];
    for (int i = 0; i < n; i++) [ar addObject:[self nextDouble]];
    return ar;
}

- (void)close {
    NSError *error;
    [self.in closeWithError:&error];
}

@end

