@implementation FastScanner

- (BOOL)hasNextByte {
    if (p < length) return YES;
    else {
        p = 0;
        length = [NSFileHandle fileHandleWithStandardInput].availableData.length;
        if (length <= 0) return NO;
    }
    return YES;
}

- (int)readByte {
    if ([self hasNextByte] == YES) return [NSFileHandle fileHandleWithStandardInput].availableData[p++];
    return -1;
}

- (BOOL)isPrintable:(int)n {return 33<=n&&n<=126;}

- (void)skip {
    while ([self hasNextByte] && ![[NSFileHandle fileHandleWithStandardInput].availableData[p] isPrintable]) p++;
}

- (BOOL)hasNext {
    [self skip];
    return [self hasNextByte];
}

- (NSString *)next {
    if (![self hasNext]) throw [NSException exceptionWithName:@"NoSuchElementException" reason:@"No more elements to read" userInfo:nil];
    NSMutableString *sb = [NSMutableString string];
    int t = [self readByte];
    while ([[NSFileHandle fileHandleWithStandardInput].availableData[p] isPrintable]) {
        [sb appendFormat:@"%c", t];
        t = [self readByte];
    }
    return sb;
}

- (NSArray *)nextArray:(int)n {
    NSMutableArray *ar = [NSMutableArray arrayWithCapacity:n];
    for (int i=0; i<n; i++) [ar addObject:[self next]];
    return ar;
}

- (int)nextInt {
    return (int)[self nextLong];
}

- (NSArray *)nextIntArray:(int)n {
    NSMutableArray *ar = [NSMutableArray arrayWithCapacity:n];
    for (int i=0; i<n; i++) [ar addObject:[NSNumber numberWithInt:[self nextInt]]];
    return ar;
}

- (long long)nextLong {
    if (![self hasNext]) throw [NSException exceptionWithName:@"NoSuchElementException" reason:@"No more elements to read" userInfo:nil];
    BOOL minus = NO;
    int temp = [self readByte];
    if (temp == '-') {
        minus = YES;
        temp = [self readByte];
    }
    if (temp<'0' || '9'<temp) throw [NSException exceptionWithName:@"NumberFormatException" reason:@"Invalid number format" userInfo:nil];
    long long n = 0;
    while ([[NSFileHandle fileHandleWithStandardInput].availableData[p] isPrintable]) {
        if ('0'<=temp && temp<='9') {
            n *= 10;
            n += temp - '0';
        }
        else throw [NSException exceptionWithName:@"NumberFormatException" reason:@"Invalid number format" userInfo:nil];
        temp = [self readByte];
    }
    return minus ? -n : n;
}

- (NSArray *)nextLongArray:(int)n {
    NSMutableArray *ar = [NSMutableArray arrayWithCapacity:n];
    for (int i=0; i<n; i++) [ar addObject:[NSNumber numberWithLongLong:[self nextLong]]];
    return ar;
}

- (double)nextDouble {
    return [self nextDouble];
}

- (NSArray *)nextDoubleArray:(int)n {
    NSMutableArray *ar = [NSMutableArray arrayWithCapacity:n];
    for (int i=0; i<n; i++) [ar addObject:[NSNumber numberWithDouble:[self nextDouble]]];
    return ar;
}

- (void)close {
    [NSFileHandle fileHandleWithStandardInput].availableData = nil;
}

@end

