#import <Foundation/Foundation.h>

@interface FastScanner : NSObject

- (instancetype)initWithInputStream:(NSInputStream *)stream;
- (BOOL)hasNextByte;
- (int)readByte;
- (NSString *)next;
- (NSArray *)nextArray:(int)n;
- (int)nextInt;
- (NSArray *)nextIntArray:(int)n;
- (long long)nextLong;
- (NSArray *)nextLongArray:(int)n;
- (double)nextDouble;
- (NSArray *)nextDoubleArray:(int)n;
- (void)close;

@end

@implementation FastScanner

- (instancetype)initWithInputStream:(NSInputStream *)stream {
    self = [super init];
    if (self) {
        in = stream;
        buffer = [[NSData alloc] initWithLength:1024];
        length = 0;
        p = 0;
    }
    return self;
}

- (BOOL)hasNextByte {
    if (p < length) return YES;
    else {
        p = 0;
        length = [in readIntoBuffer:buffer maxLength:1024];
        if (length <= 0) return NO;
    }
    return YES;
}

- (int)readByte {
    if ([self hasNextByte] == YES) return [buffer bytes][p++];
    return -1;
}

