- (long long)nextLong {
    if (![self hasNext]) throw [NSException exceptionWithName:@"NSException" reason:@"No more elements" userInfo:nil];
    BOOL minus = NO;
    int temp = [self readByte];
    if (temp == '-') {
        minus = YES;
        temp = [self readByte];
    }
    if (temp<'0' || '9'<temp) throw [NSException exceptionWithName:@"NSException" reason:@"Invalid input" userInfo:nil];
    long long n = 0;
    while ([self isPrintable:temp]) {
        if ('0'<=temp && temp<='9') {
            n *= 10;
            n += temp - '0';
        }
        else throw [NSException exceptionWithName:@"NSException" reason:@"Invalid input" userInfo:nil];
        temp = [self readByte];
    }
    return minus ? -n : n;
}

