		for(int i = 0; i < n; i++){
			String str = sc.nextLine();
			List<Character> max_list = new ArrayList<Character>();
			List<Character> min_list = new ArrayList<Character>();

			for(char c:str.toCharArray()){
				max_list.add(c);
				min_list.add(c);
