	public void solve() {
		while(true){
			int two = 0;
			int five = 0;
			N = nextInt();
			if(N==0)break;
			for(int i = N;i >= 2;i--){
				int j = i;
				while(j%2==0){
					j/=2;
					two++;
				}

				while(j%5==0){
					j/=5;
					five++;
				}
			}

			out.println(Math.min(two,five));
		}
	}

