    self = [super init];
    if (self) {
        in = stream;
        buffer = [[NSMutableData alloc] initWithLength:1024];
        length = 0;
        p = 0;
    }
    return self;
}

- (BOOL)hasNextByte {
    if (p < length) return YES;
    else {
        p = 0;
        length = [in read:[buffer mutableBytes] maxLength:1024];
        if (length <= 0) return NO;
    }
    return YES;
}

- (int)readByte {
    if ([self hasNextByte] == YES) return [buffer bytes][p++];
    return -1;
}

- (void)skip {
    while ([self hasNextByte] && !([self readByte] >= 33 && [self readByte] <= 126)) ;
}

- (BOOL)hasNext {
    [self skip];
    return [self hasNextByte];
}

- (NSString *)next {
    if (![self hasNext]) throw [NSException exceptionWithName:@"NoSuchElementException" reason:@"No more elements" userInfo:nil];
    NSMutableString *sb = [NSMutableString string];
    int t = [self readByte];
    while ([self isPrintable:t]) {
        [sb appendString:[NSString stringWithFormat:@"%c", t]];
        t = [self readByte];
    }
    return sb;
}

- (NSArray<NSString *> *)nextArray:(int)n {
    NSMutableArray<NSString *> *ar = [NSMutableArray arrayWithCapacity:n];
    for (int i=0; i<n; i++) [ar addObject:[self next]];
