    if (![self hasNext]) throw [NSException exceptionWithName:@"NoSuchElementException" reason:@"No more elements" userInfo:nil];
    BOOL minus = NO;
    int temp = [self readByte];
    if (temp == '-') {
        minus = YES;
        temp = [self readByte];
    }
