@interface FastScanner : NSObject

@property (nonatomic, strong) NSInputStream *in;
@property (nonatomic, strong) NSMutableData *buffer;
@property (nonatomic, assign) int length;
@property (nonatomic, assign) int p;

- (instancetype)initWithInputStream:(NSInputStream *)stream;
- (BOOL)hasNextByte;
- (int)readByte;
- (BOOL)isPrintable:(int)n;
- (void)skip;
- (BOOL)hasNext;
- (NSString *)next;
- (NSArray *)nextArray:(int)n;
- (int)nextInt;
- (NSArray *)nextIntArray:(int)n;
- (long long)nextLong;
- (NSArray *)nextLongArray:(int)n;
- (double)nextDouble;
- (NSArray *)nextDoubleArray:(int)n;
- (void)close;

@end

@implementation FastScanner

- (instancetype)initWithInputStream:(NSInputStream *)stream {
    self = [super init];
    if (self) {
        self.in = stream;
        self.buffer = [NSMutableData dataWithCapacity:1024];
        self.length = 0;
        self.p = 0;
    }
    return self;
}

- (BOOL)hasNextByte {
    if (self.p < self.length) {
        return YES;
    } else {
        self.p = 0;
        [self.buffer setLength:0];
        self.length = [self.in read:self.buffer.mutableBytes maxLength:1024];
        if (self.length <= 0) {
            return NO;
        }
    }
    return YES;
}

- (int)readByte {
    if ([self hasNextByte]) {
        return [self.buffer bytes][self.p++];
    }
    return -1;
}

- (BOOL)isPrintable:(int)n {
    return 33 <= n && n <= 126;
}

- (void)skip {
    while ([self hasNextByte] && ![self isPrintable:[self.buffer bytes][self.p]]) {
        self.p++;
    }
}

- (BOOL)hasNext {
    [self skip];
    return [self hasNextByte];
}

- (NSString *)next {
    if (![self hasNext]) {
        [NSException raise:NSInvalidArgumentException format:@"No more elements"];
    }
    NSMutableString *sb = [NSMutableString string];
    int t = [self readByte];
    while ([self isPrintable:t]) {
        [sb appendFormat:@"%c", t];
        t = [self readByte];
    }
    return sb;
}

- (NSArray *)nextArray:(int)n {
    NSMutableArray *ar = [NSMutableArray arrayWithCapacity:n];
    for (int i = 0; i < n; i++) {
        [ar addObject:[self next]];
    }
    return ar;
}

- (int)nextInt {
    return (int)[self nextLong];
}

- (NSArray *)nextIntArray:(int)n {
    NSMutableArray *ar = [NSMutableArray arrayWithCapacity:n];
    for (int i = 0; i < n; i++) {
        [ar addObject:@([self nextInt])];
    }
    return ar;
}

- (long long)nextLong {
    if (![self hasNext]) {
        [NSException raise:NSInvalidArgumentException format:@"No more elements"];
    }
    BOOL minus = NO;
    int temp = [self readByte];
    if (temp == '-') {
        minus = YES;
        temp = [self readByte];
    }
    if (temp < '0' || '9' < temp) {
        [NSException raise:NSInvalidArgumentException format:@"Invalid input"];
    }
    long long n = 0;
    while ([self isPrintable:temp]) {
        if ('0' <= temp && temp <= '9') {
            n *= 10;
            n += temp - '0';
        } else {
            [NSException raise:NSInvalidArgumentException format:@"Invalid input"];
        }
        temp = [self readByte];
    }
    return minus ? -n : n;
}

- (NSArray *)nextLongArray:(int)n {
    NSMutableArray *ar = [NSMutableArray arrayWithCapacity:n];
    for (int i = 0; i < n; i++) {
        [ar addObject:@([self nextLong])];
    }
    return ar;
}

- (double)nextDouble {
    return [self nextLong];
}

- (NSArray *)nextDoubleArray:(int)n {
    NSMutableArray *ar = [NSMutableArray arrayWithCapacity:n];
    for (int i = 0; i < n; i++) {
        [ar addObject:@([self nextDouble])];
    }
    return ar;
}

- (void)close {
    [self.in close];
}

@end

