    NSAutoreleasePool *pool = [[NSAutoreleasePool alloc] init];

    NSInputStream *in = [NSInputStream inputStreamWithFileAtPath:@"/dev/stdin"];
    FastScanner *scanner = [[FastScanner alloc] initWithInputStream:in];
    NSOutputStream *out = [NSOutputStream outputStreamToFD:1];
    [out open];

    Methods *ms = [[Methods alloc] init];

    while (YES) {
        int n = [scanner nextInt];
        if (n == 0) {
            break;
        }

        NSMutableArray *primeList = [NSMutableArray array];
        [primeList addObject:@(2)];
        int i = 3;
        while ([primeList count] < 10000) {
            if ([ms isPrime:i]) {
                [primeList addObject:@(i)];
            }
            i += 2;
        }

        long long sum = 0;
        for (int i = 0; i < n; i++) {
            sum += [primeList[i] intValue];
        }

        [out write:[NSString stringWithFormat:@"%lld\n", sum] length:[NSString stringWithFormat:@"%lld\n", sum].length];
    }

    [scanner close];
    [out close];

    [pool drain];
    return 0;
}

