		BigDecimal x = BigDecimal.valueOf(a).divide(BigDecimal.valueOf(b), n + 20, RoundingMode.DOWN);
		if (a >= b) {
			x = x.subtract(BigDecimal.valueOf(a/b));
		}

		String s = x.toPlainString();
		int ans = 0;
		for (int i = 0; i < n; i++) {
			char c = 0;
			try {
				c = s.charAt(i + 2);
			} catch (Exception e) {c = 0;}
			ans += (int)(c - '0');
		}
		out.println(ans);
	}

