@implementation Methods

- (void)print:(NSArray *)ar {
    NSLog(@"%@", ar);
}

- (void)yesno:(BOOL)b out:(NSOutputStream *)out {
    if (b) {
        [out write:@"Yes" length:3];
    }
    else {
        [out write:@"No" length:2];
    }
}

- (void)YESNO:(BOOL)b out:(NSOutputStream *)out {
    if (b) {
        [out write:@"YES" length:3];
    }
    else {
        [out write:@"NO" length:2];
    }
}

- (int)max:(NSArray *)ar {
    NSArray *sorted = [ar sortedArrayUsingSelector:@selector(compare:)];
    return [sorted lastObject];
}

- (int)min:(NSArray *)ar {
    NSArray *sorted = [ar sortedArrayUsingSelector:@selector(compare:)];
    return [sorted firstObject];
}

- (long long)gcd:(long long)a b:(long long)b {
    if (b > 0) {
        return [self gcd:b a:(a%b)];
    }
    else {
        return a;
    }
}

- (long long)lcm:(long long)a b:(long long)b {
    return a/[self gcd:a b:b]*b;
}

- (long long)factorial:(int)i {
    if (i == 1) {
        return 1;
    }
    else {
        return i*[self factorial:i-1];
    }
}

- (int)manhat:(int)x1 y1:(int)y1 x2:(int)x2 y2:(int)y2 {
    return abs(x1-x2) + abs(y1-y2);
}

- (double)euclid:(double)x1 y1:(double)y1 x2:(double)x2 y2:(double)y2 {
    return sqrt((x2-x1)*(x2-x1)+(y2-y1)*(y2-y1));
}

- (BOOL)isPrime:(int)n {
    if (n == 2) {
        return YES;
    }
    if (n < 2 || n%2 == 0) {
        return NO;
    }
    for (int i=3; i<=sqrt(n); i+=2) {
        if (n%i == 0) {
            return NO;
        }
    }
    return YES;
}

