@property (nonatomic, assign) NSInteger buflen;
- (BOOL)hasNextByte;
- (NSInteger)readByte;
- (BOOL)isPrintableChar:(NSInteger)c;
- (void)skipUnprintable;
- (BOOL)hasNext;
- (NSString *)next;
- (long long)nextLong;
@end

@implementation FastScanner

- (instancetype)init {
    self = [super init];
    if (self) {
        self.in = [NSInputStream inputStreamWithFileAtPath:@"/dev/stdin"];
        self.buffer = [[NSMutableData alloc] initWithLength:1024];
        self.ptr = 0;
        self.buflen = 0;
    }
    return self;
}

- (BOOL)hasNextByte {
    if (self.ptr < self.buflen) {
        return YES;
    } else {
        self.ptr = 0;
        NSInteger bytesRead = [self.in read:[self.buffer mutableBytes] maxLength:self.buffer.length];
        if (bytesRead <= 0) {
            return NO;
        }
        self.buflen = bytesRead;
        return YES;
    }
}

- (NSInteger)readByte {
    if ([self hasNextByte]) {
        return [self.buffer bytes][self.ptr++];
    } else {
        return -1;
    }
}

- (BOOL)isPrintableChar:(NSInteger)c {
    return c >= 33 && c <= 126;
}

- (void)skipUnprintable {
    while ([self hasNextByte] && ![self isPrintableChar:[self.buffer bytes][self.ptr]]) {
        self.ptr++;
    }
}

- (BOOL)hasNext {
    [self skipUnprintable];
    return [self hasNextByte];
}

- (NSString *)next {
    if (![self hasNext]) {
        @throw [NSException exceptionWithName:NSInvalidArgumentException reason:@"No more input" userInfo:nil];
    }
    NSMutableString *sb = [NSMutableString string];
    NSInteger b = [self readByte];
    while ([self isPrintableChar:b]) {
        [sb appendFormat:@"%c", b];
        b = [self readByte];
    }
    return sb;
}

- (long long)nextLong {
    if (![self hasNext]) {
        @throw [NSException exceptionWithName:NSInvalidArgumentException reason:@"No more input" userInfo:nil];
    }
    long long n = 0;
    BOOL minus = NO;
    NSInteger b = [self readByte];
    if (b == '-') {
        minus = YES;
        b = [self readByte];
    }
    if (b < '0' || b > '9') {
        @throw [NSException exceptionWithName:NSInvalidArgumentException reason:@"Invalid input" userInfo:nil];
    }
    while (YES) {
        if (b >= '0' && b <= '9') {
            n *= 10;
            n += b - '0';
        } else if (b == -1 || ![self isPrintableChar:b]) {
            return minus ? -n : n;
        } else {
            @throw [NSException exceptionWithName:NSInvalidArgumentException reason:@"Invalid input" userInfo:nil];
        }
        b = [self readByte];
    }
}

@end

