@implementation FastScanner

- (instancetype)initWithInputStream:(NSInputStream *)stream {
    self = [super init];
    if (self) {
        _in = stream;
        _buffer = [NSMutableData dataWithCapacity:1024];
        _length = 0;
        _p = 0;
    }
    return self;
}

- (BOOL)hasNextByte {
    if (_p < _length) return YES;
    else {
        _p = 0;
        [_buffer setLength:0];
        _length = [_in read:[_buffer mutableBytes] maxLength:1024];
        if (_length <= 0) return NO;
    }
    return YES;
}

- (int)readByte {
    if ([self hasNextByte] == YES) return [_buffer byteAtIndex:_p++];
    return -1;
}

- (BOOL)isPrintable:(int)n {return 33<=n&&n<=126;}

- (void)skip {
    while ([self hasNextByte] && ![[self class] isPrintable:[self readByte]]) {}
}

- (BOOL)hasNext {
    [self skip];
    return [self hasNextByte];
}

- (NSString *)next {
    if (![self hasNext]) throw [NSException exceptionWithName:@"NoSuchElementException" reason:nil userInfo:nil];
    NSMutableString *sb = [NSMutableString string];
    int t = [self readByte];
    while ([[self class] isPrintable:t]) {
        [sb appendFormat:@"%c", t];
        t = [self readByte];
    }
    return sb;
}

- (NSString **)nextArray:(int)n {
    NSString **ar = malloc(sizeof(NSString *) * n);
    for (int i=0; i<n; i++) ar[i] = [self next];
    return ar;
}

- (int)nextInt {return (int)[self nextLong];}

- (int *)nextIntArray:(int)n {
    int *ar = malloc(sizeof(int) * n);
    for (int i=0; i<n; i++) ar[i] = [self nextInt];
    return ar;
}

- (long long)nextLong {
    if (![self hasNext]) throw [NSException exceptionWithName:@"NoSuchElementException" reason:nil userInfo:nil];
    BOOL minus = NO;
    int temp = [self readByte];
    if (temp == '-') {
        minus = YES;
        temp = [self readByte];
    }
    if (temp<'0' || '9'<temp) throw [NSException exceptionWithName:@"NumberFormatException" reason:nil userInfo:nil];
    long long n = 0;
    while ([[self class] isPrintable:temp]) {
        if ('0'<=temp && temp<='9') {
            n *= 10;
            n += temp - '0';
        }
        else throw [NSException exceptionWithName:@"NumberFormatException" reason:nil userInfo:nil];
        temp = [self readByte];
    }
    return minus ? -n : n;
}

- (long long *)nextLongArray:(int)n {
    long long *ar = malloc(sizeof(long long) * n);
    for (int i=0; i<n; i++) ar[i] = [self nextLong];
    return ar;
}

- (double)nextDouble {return [self nextLong];}

- (double *)nextDoubleArray:(int)n {
    double *ar = malloc(sizeof(double) * n);
    for (int i=0; i<n; i++) ar[i] = [self nextDouble];
    return ar;
}

- (void)close {
    [_in close];
}

