#import <Foundation/Foundation.h>

double EPS = 1e-8;

typedef struct {
    double x;
    double y;
} P;

typedef struct {
    P s;
    P t;
    double dx;
    double dy;
} Vec;

P P_make(double x, double y) {
    P p;
    p.x = x;
    p.y = y;
    return p;
}

Vec Vec_make(P s, P t) {
    Vec v;
    v.s = s;
    v.t = t;
    v.dx = t.x - s.x;
    v.dy = t.y - s.y;
    return v;
}

int P_compare(P p1, P p2) {
    if (fabs(p1.x - p2.x) < EPS && fabs(p1.y - p2.y) < EPS) return 0;
    if (fabs(p1.x - p2.x) < EPS) {
        return p1.y < p2.y ? 1 : p1.y > p2.y ? -1 : 0;
    }
    return p1.x < p2.x ? 1 : p1.x > p2.x ? -1 : 0;
}

double Vec_dotProduct(Vec v1, Vec v2) {
    return v1.dx * v2.dx + v1.dy * v2.dy;
}

double Vec_crossProduct(Vec v1, Vec v2) {
    return v1.dx * v2.dy - v1.dy * v2.dx;
}

BOOL Vec_isOrthogonal(Vec v1, Vec v2) {
    return fabs(Vec_dotProduct(v1, v2)) < EPS;
}

