int comparePoint(const void *a, const void *b) {
    Point *p1 = (Point *)a;
    Point *p2 = (Point *)b;
    if (!EQ(p1->x, p2->x)) {
        return (p1->x < p2->x) ? -1 : 1;
    }
    if (!EQ(p1->y, p2->y)) {
        return (p1->y < p2->y) ? -1 : 1;
    }
    return 0;
}

int compareVector(const void *a, const void *b) {
    Vector *v1 = (Vector *)a;
    Vector *v2 = (Vector *)b;
    if (!EQ(v1->x, v2->x)) {
        return (v1->x < v2->x) ? -1 : 1;
    }
    if (!EQ(v1->y, v2->y)) {
        return (v1->y < v2->y) ? -1 : 1;
    }
    return 0;
}

double dot(Vector a, Vector b) {
    return a.x * b.x + a.y * b.y;
}

double cross(Vector a, Vector b) {
    return a.x * b.y - a.y * b.x;
}

int isOrthogonal(Vector a, Vector b) {
    return EQ(dot(a, b), 0.0);
}

void solve() {
    Vector a, b;
    a.x = scanf("%lf", &a.x);
    a.y = scanf("%lf", &a.y);
    b.x = scanf("%lf", &b.x);
    b.y = scanf("%lf", &b.y);
    printf(isOrthogonal(a, b) ? "YES\n" : "NO\n");
}

