@interface FastScanner : NSObject
@property (nonatomic, strong) NSInputStream *inputStream;
@property (nonatomic, strong) NSMutableData *buffer;
@property (nonatomic, assign) int ptr;
@property (nonatomic, assign) int buflen;
-(BOOL)hasNextByte;
-(int)readByte;
-(void)skipUnprintable;
-(BOOL)hasNext;
-(NSString *)next;
-(long long)nextLong;
@end

@implementation FastScanner

-(instancetype)init {
    self = [super init];
    if (self) {
        self.buffer = [[NSMutableData alloc] initWithLength:1024];
        self.ptr = 0;
        self.buflen = 0;
    }
    return self;
}

-(BOOL)hasNextByte {
    if (self.ptr < self.buflen) {
        return YES;
    } else {
        self.ptr = 0;
        self.buflen = [self.inputStream read:[self.buffer mutableBytes] maxLength:self.buffer.length];
        if (self.buflen <= 0) {
            return NO;
        }
    }
    return YES;
}

-(int)readByte {
    if ([self hasNextByte]) {
        return [self.buffer bytes][self.ptr++];
    } else {
        return -1;
    }
}

-(void)skipUnprintable {
    while ([self hasNextByte] && !([self readByte] >= 33 && [self readByte] <= 126)) {
        [self ptr]++;
    }
}

-(BOOL)hasNext {
    [self skipUnprintable];
    return [self hasNextByte];
}

-(NSString *)next {
    if (![self hasNext]) {
        return nil;
    }
    NSMutableString *sb = [NSMutableString string];
    int b = [self readByte];
    while ([self readByte] >= 33 && [self readByte] <= 126) {
        [sb appendString:[NSString stringWithFormat:@"%c", b]];
        b = [self readByte];
    }
    return sb;
}

-(long long)nextLong {
    if (![self hasNext]) {
        return 0;
    }
    long long n = 0;
    BOOL minus = NO;
    int b = [self readByte];
    if (b == '-') {
        minus = YES;
        b = [self readByte];
