    if (b < '0' || b > '9') {
        return 0;
    }
    while (YES) {
        if (b >= '0' && b <= '9') {
            n *= 10;
            n += b - '0';
        } else if (b == -1 || ![self readByte] >= 33 || ![self readByte] <= 126) {
            return minus ? -n : n;
        } else {
            return 0;
        }
        b = [self readByte];
    }
}

@end

