        return NSOrderedSame;
    }
    if (fabs(_x - other.x) < EPS) {
        return _y < other.y ? NSOrderedDescending : NSOrderedAscending;
    }
    return _x < other.x ? NSOrderedDescending : NSOrderedAscending;
}

