@implementation Vec

- (instancetype)initWithPoint:(P *)point {
    self = [super init];
    if (self) {
        _s = [[P alloc] initWithX:0 y:0];
        _t = point;
        _dx = _t.x - _s.x;
        _dy = _t.y - _s.y;
    }
    return self;
}

- (instancetype)initWithStartPoint:(P *)startPoint endPoint:(P *)endPoint {
    self = [super init];
    if (self) {
        _s = startPoint;
        _t = endPoint;
        _dx = _t.x - _s.x;
        _dy = _t.y - _s.y;
    }
    return self;
}

- (Vec *)reverse {
    return [[Vec alloc] initWithStartPoint:_t endPoint:_s];
}

- (double)norm {
    return sqrt(_dx * _dx + _dy * _dy);
}

- (double)dotProduct:(Vec *)other {
    return _dx * other.dx + _dy * other.dy;
}

- (double)crossProduct:(Vec *)other {
    return _dx * other.dy - _dy * other.dx;
}

- (BOOL)isOrthogonal:(Vec *)other {
    return fabs([self dotProduct:other]) < EPS;
}

- (BOOL)isParallel:(Vec *)other {
    return fabs([self crossProduct:other]) < EPS;
}

- (int)ccw:(P *)point {
    Vec *a = [[Vec alloc] initWithStartPoint:_s endPoint:point];
    Vec *b = [[Vec alloc] initWithStartPoint:_s endPoint:_t];
    if (fabs([a crossProduct:b]) < EPS) {
        if ([a dotProduct:b] < 0) {
            return 2;
        }
        if ([a norm] < [b norm]) {
            return -2;
        }
        return 0;
    }
    if ([a crossProduct:b] > 0) {
        return -1;
    }
    return 1;
}

- (BOOL)isCross:(Vec *)other {
    return [self ccw:other.s] * [self ccw:other.t] < 0 && other.ccw(_s) * other.ccw(_t) < 0 ||
           [self ccw:other.s] * [self ccw:other.t] < 0 && other.ccw(_s) * other.ccw(_t) < 0;
}

- (double)distanceFromPoint:(P *)point {
    Vec *o = [[Vec alloc] initWithPoint:point];
    return fabs([self crossProduct:o]) / [self norm];
}

- (NSString *)description {
    return [NSString stringWithFormat:@"%@->%@", _s, _t];
}

@end

