- (int)contains:(double[4][2])plist x:(double)x y:(double)y {
    BOOL isin = NO;
    int n = 4;
    for (int i = 0; i < n; i++) {
        double a[2] = {plist[i][0] - x, plist[i][1] - y};
        double b[2] = {plist[(i+1)%n][0] - x, plist[(i+1)%n][1] - y};
        if (a[1] > b[1]) {
            double temp = a[0];
            a[0] = b[0];
            b[0] = temp;
            temp = a[1];
            a[1] = b[1];
            b[1] = temp;
        }
        if (a[1] <= 0 && 0 < b[1]) {
            double cross = a[0] * b[1] - a[1] * b[0];
            if (cross < 0) {
                isin = !isin;
            }
        }
        double cross = a[0] * b[1] - a[1] * b[0];
        double dot = a[0] * b[0] + a[1] * b[1];
        if (cross == 0 && dot <= 0) {
            return 0;
        }
    }
    return isin ? 1 : -1;
}

