@property (nonatomic, strong) NSMutableData *buffer;
@property (nonatomic, assign) int ptr;
@property (nonatomic, assign) int buflen;

- (instancetype)initWithInputStream:(NSInputStream *)inputStream;
- (BOOL)hasNextByte;
- (int)readByte;
- (BOOL)isPrintableChar:(int)c;
- (void)skipUnprintable;
- (BOOL)hasNext;
- (NSString *)next;
- (long long)nextLong;
@end

@implementation FastScanner

- (instancetype)initWithInputStream:(NSInputStream *)inputStream {
    self = [super init];
    if (self) {
        _inputStream = inputStream;
        _buffer = [NSMutableData data];
        _ptr = 0;
        _buflen = 0;
    }
    return self;
}

- (BOOL)hasNextByte {
    if (_ptr < _buflen) {
        return YES;
    } else {
        _ptr = 0;
        [_inputStream read:[_buffer mutableBytes] maxLength:1024];
        _buflen = [_inputStream getLength];
        if (_buflen <= 0) {
            return NO;
        }
    }
    return YES;
}

- (int)readByte {
    if ([self hasNextByte]) {
        return [_buffer bytes][_ptr++];
    } else {
        return -1;
    }
}

- (BOOL)isPrintableChar:(int)c {
    return c >= 33 && c <= 126;
}

- (void)skipUnprintable {
    while ([self hasNextByte] && ![self isPrintableChar:[self readByte]]) {
        _ptr++;
    }
}

- (BOOL)hasNext {
    [self skipUnprintable];
    return [self hasNextByte];
}

- (NSString *)next {
    if (![self hasNext]) {
        @throw [NSException exceptionWithName:@"NoMoreElementsException" reason:@"No more elements" userInfo:nil];
    }
    NSMutableString *sb = [NSMutableString string];
    int b = [self readByte];
    while ([self isPrintableChar:b]) {
        [sb appendString:[NSString stringWithFormat:@"%c", b]];
        b = [self readByte];
    }
    return sb;
}

- (long long)nextLong {
    if (![self hasNext]) {
        @throw [NSException exceptionWithName:@"NoMoreElementsException" reason:@"No more elements" userInfo:nil];
    }
    long long n = 0;
    BOOL minus = NO;
    int b = [self readByte];
    if (b == '-') {
        minus = YES;
        b = [self readByte];
    }
    if (b < '0' || b > '9') {
        @throw [NSException exceptionWithName:@"NumberFormatException" reason:@"Invalid number format" userInfo:nil];
    }
    while (TRUE) {
        if (b >= '0' && b <= '9') {
            n *= 10;
            n += b - '0';
        } else if (b == -1 || ![self isPrintableChar:b]) {
            return minus ? -n : n;
        } else {
            @throw [NSException exceptionWithName:@"NumberFormatException" reason:@"Invalid number format" userInfo:nil];
        }
        b = [self readByte];
    }
}

@end

