		int sum = x + y;
		return sum % 10;
	}
	private static int[] getNextArray(int[] array){
		int[] n = new int[array.length - 1];
		for(int i = 0; i + 1 < array.length; i++){
			n[i] = getNumInTheOnePlace(array[i], array[i + 1]);
		}
		return n;
