@implementation FastScanner

- (instancetype)initWithInputStream:(NSInputStream *)stream {
    self = [super init];
    if (self) {
        _in = stream;
        _buffer = [NSMutableData dataWithLength:1024];
        _length = 0;
        _p = 0;
    }
    return self;
}

- (BOOL)hasNextByte {
    if (_p < _length) return YES;
    else {
        _p = 0;
        [_in readIntoBuffer:_buffer maxLength:1024];
        _length = [_buffer length];
        if (_length <= 0) return NO;
    }
    return YES;
}

- (int)readByte {
    if ([self hasNextByte] == YES) return [_buffer byteAtIndex:_p++];
    return -1;
}

- (BOOL)isPrintable:(int)n {
    return 33 <= n && n <= 126;
}

- (void)skip {
    while ([self hasNextByte] && !([self isPrintable:[self readByte]])) _p++;
}

- (BOOL)hasNext {
    [self skip];
    return [self hasNextByte];
}

- (NSString *)next {
    if (![self hasNext]) {
        NSException *exception = [NSException exceptionWithName:@"NSInvalidArgumentException"
                                                          reason:@"No more elements to read"
                                                        userInfo:nil];
        @throw exception;
    }
    NSMutableString *sb = [NSMutableString string];
    int t = [self readByte];
    while ([self isPrintable:t]) {
        [sb appendFormat:@"%c", t];
        t = [self readByte];
    }
    return sb;
}

- (NSArray<NSString *> *)nextArray:(int)n {
    NSMutableArray<NSString *> *ar = [NSMutableArray arrayWithCapacity:n];
    for (int i=0; i<n; i++) [ar addObject:[self next]];
    return ar;
}

- (int)nextInt {
    return [self nextLong];
}

- (NSArray<NSNumber *> *)nextIntArray:(int)n {
    NSMutableArray<NSNumber *> *ar = [NSMutableArray arrayWithCapacity:n];
    for (int i=0; i<n; i++) [ar addObject:@([self nextInt])];
    return ar;
}

- (long long)nextLong {
    if (![self hasNext]) {
        NSException *exception = [NSException exceptionWithName:@"NSInvalidArgumentException"
                                                          reason:@"No more elements to read"
                                                        userInfo:nil];
        @throw exception;
    }
    BOOL minus = NO;
    int temp = [self readByte];
    if (temp == '-') {
        minus = YES;
        temp = [self readByte];
    }
    if (temp < '0' || '9' < temp) {
        NSException *exception = [NSException exceptionWithName:@"NSInvalidArgumentException"
                                                          reason:@"Invalid input"
                                                        userInfo:nil];
        @throw exception;
    }
    long long n = 0;
    while ([self isPrintable:temp]) {
        if ('0' <= temp && temp <= '9') {
            n *= 10;
            n += temp - '0';
        } else {
            NSException *exception = [NSException exceptionWithName:@"NSInvalidArgumentException"
                                                              reason:@"Invalid input"
                                                            userInfo:nil];
            @throw exception;
        }
        temp = [self readByte];
    }
    return minus ? -n : n;
}

- (NSArray<NSNumber *> *)nextLongArray:(int)n {
    NSMutableArray<NSNumber *> *ar = [NSMutableArray arrayWithCapacity:n];
    for (int i=0; i<n; i++) [ar addObject:@([self nextLong])];
    return ar;
}

- (double)nextDouble {
    return [self nextLong];
}

- (NSArray<NSNumber *> *)nextDoubleArray:(int)n {
    NSMutableArray<NSNumber *> *ar = [NSMutableArray arrayWithCapacity:n];
    for (int i=0; i<n; i++) [ar addObject:@([self nextDouble])];
    return ar;
}

- (void)close {
    [_in close];
}

@end

