#import <Foundation/Foundation.h>

int main(int argc, const char * argv[]) {
    @autoreleasepool {
        NSInputStream *inputStream = [[NSInputStream alloc] initWithFileAtPath:@"/dev/stdin"];
        [inputStream open];

        NSMutableString *line = [NSMutableString string];
        int sum = 0;

        while ([inputStream hasBytesAvailable]) {
            char buffer[1024];
            NSInteger bytesRead = [inputStream read:buffer maxLength:1024];
            if (bytesRead > 0) {
                [line appendString:[[NSString alloc] initWithBytes:buffer length:bytesRead encoding:NSUTF8StringEncoding]];

                NSRange range = [line rangeOfString:@"\n"];
                while (range.location != NSNotFound) {
                    NSString *currentLine = [line substringToIndex:range.location];
                    [line deleteCharactersInRange:NSMakeRange(0, range.location + 1)];

                    currentLine = [currentLine stringByTrimmingCharactersInSet:[NSCharacterSet whitespaceAndNewlineCharacterSet]];
                    if ([currentLine length] > 0) {
                        currentLine = [currentLine stringByReplacingOccurrencesOfString:@"-" withString:@"- "];
                        currentLine = [currentLine stringByReplacingOccurrencesOfString:@"." withString:@" ."];

                        NSArray *numbers = [currentLine componentsSeparatedByCharactersInSet:[NSCharacterSet decimalDigitCharacterSet]];
                        for (NSString *number in numbers) {
                            if ([number length] > 0) {
                                sum += [number intValue];
                            }
                        }
                    }

                    range = [line rangeOfString:@"\n"];
                }
            }
        }

        NSLog(@"%d", sum);
    }
    return 0;
}

