	public static void quickSort(int a[], int low, int high) {
		if (high <= low) {
			return ;
		}
		int i = low;
		int j = high;
		int x = a[(low + high) / 2];
		while (i <= j) {
			while (a[i] < x) {
				i++;
			}
			while (x < a[j]) {
				j--;
			}
			if (i <= j) {
				int swap = a[i];
				a[i] = a[j];
				a[j] = swap;
				i++;
				j--;
			}
		}
		quickSort(a, low, j);
		quickSort(a, i, high);
	}
