#import <stdio.h>
#import <stdlib.h>
#import <string.h>

#define MAX 14

typedef struct {
    int top;
    int stack[MAX * MAX];
} Stack;

void push(Stack *s, int value) {
    s->stack[s->top++] = value;
}

int pop(Stack *s) {
    return s->stack[--s->top];
}

int main() {
    Stack nowh, noww;
    nowh.top = 0;
    noww.top = 0;

    char f[MAX][MAX];
    int i, j, k, h, w, count;
    int di[4], dj[4];

    di[0] = -1;
    di[1] = 0;
    di[2] = 1;
    di[3] = 0;
    dj[0] = 0;
    dj[1] = -1;
    dj[2] = 0;
    dj[3] = 1;

    while (scanf("%s", f[1] + 1) != EOF) {
        count = 0;
        for (i = 1; i < MAX - 1; i++) {
            for (j = 1; j < MAX - 1; j++) {
                if (f[i][j] == '1') {
                    count++;
                    f[i][j] = '0';
                    push(&nowh, i);
                    push(&noww, j);
                    while (nowh.top > 0) {
                        h = pop(&nowh);
                        w = pop(&noww);
                        for (k = 0; k < 4; k++) {
                            if (f[h + di[k]][w + dj[k]] == '1') {
                                f[h + di[k]][w + dj[k]] = '0';
                                push(&nowh, h + di[k]);
                                push(&noww, w + dj[k]);
                            }
                        }
                    }
                }
            }
        }
        printf("%d\n", count);
    }
    return 0;
}

