#import <Foundation/Foundation.h>

@interface Main : NSObject

@property (nonatomic, strong) NSInputStream *inputStream;

- (void)io;

@end

@implementation Main

- (void)io {
    self.inputStream = [NSInputStream inputStreamWithFileAtPath:@"/dev/stdin"];
    [self.inputStream open];

    NSInputStream *inputStream = self.inputStream;
    NSOutputStream *outputStream = [NSOutputStream outputStreamToFD:1];
    [outputStream open];

    NSMutableData *data = [NSMutableData data];
    NSInteger bytesRead;
    while ((bytesRead = [inputStream read:[data mutableBytes] maxLength:[data length] + 1024]) > 0) {
        [data appendBytes:[data mutableBytes] length:bytesRead];
    }

    [inputStream close];
    [outputStream close];

    NSString *inputString = [[NSString alloc] initWithData:data encoding:NSUTF8StringEncoding];
    NSArray *lines = [inputString componentsSeparatedByString:@"\n"];

    for (NSString *line in lines) {
        NSArray *values = [line componentsSeparatedByString:@", "];
        int n = [values[0] intValue];
        if (n == 0) {
            break;
        }

        NSMutableArray *points = [NSMutableArray array];
        for (int i = 1; i < values.count; i += 2) {
            double x = [values[i] doubleValue];
            double y = [values[i + 1] doubleValue];
            [points addObject:[NSValue valueWithCGPoint:CGPointMake(x, y)]];
        }

        int result = [self solve:points];
        [outputStream write:[NSString stringWithFormat:@"%d\n", result] dataUsingEncoding:NSUTF8StringEncoding];
    }
}

- (int)solve:(NSMutableArray *)points {
    CGPoint start = [points[0] CGPointValue];
    for (NSValue *value in points) {
        CGPoint point = [value CGPointValue];
        if (point.y < start.y) {
            start = point;
        }
    }

    CGPoint p0 = start;
    int n = 0;
    double prev = 0;
    do {
        double min = M_PI * 3;
        CGPoint next = p0;
        for (NSValue *value in points) {
            CGPoint p = [value CGPointValue];
            double theta = [self getTheta:p p0:p0];
            if (theta >= prev && theta < min) {
                min = theta;
                next = p;
            }
        }
        p0 = next;
        prev = min;
        n++;
    } while (p0 != start);

    return points.count - n;
}

- (double)getTheta:(CGPoint)p p0:(CGPoint)p0 {
    double xDiff = p.x - p0.x;
    double yDiff = p.y - p0.y;
    double theta = acos(xDiff / hypot(xDiff, yDiff));
    if (p.y < p0.y) {
        theta = M_PI * 2 - theta;
    }
    return theta;
}

@end

int main() {
    Main *main = [[Main alloc] init];
    [main io];
    return 0;
}

