- (void)io {
    self.inputStream = [[NSInputStream alloc] initWithFileAtPath:@"/dev/stdin"];
    [self.inputStream open];

    NSFormatter *formatter = [[NSFormatter alloc] init];
    formatter.numberStyle = NSNumberFormatterDecimalStyle;

    while (YES) {
        NSString *line = [self.readLine];
        NSArray *numbers = [line componentsSeparatedByString:@", "];
        if (numbers.count == 1 && [numbers[0] isEqualToString:@"0"]) {
            break;
        }

        NSMutableArray *points = [NSMutableArray array];
        for (int i = 0; i < numbers.count; i += 2) {
            double x = [formatter numberFromString:numbers[i]].doubleValue;
            double y = [formatter numberFromString:numbers[i+1]].doubleValue;
            Point *point = [[Point alloc] initWithX:x y:y];
            [points addObject:point];
        }

        int result = [self solve:points];
        NSLog(@"%d", result);
    }

    [self.inputStream close];
}

- (NSString *)readLine {
    NSMutableData *data = [NSMutableData data];
    uint8_t buffer[1];
    while ([self.inputStream hasBytesAvailable]) {
        [self.inputStream read:buffer maxLength:1];
        if (buffer[0] == '\n') {
            break;
        }
        [data appendBytes:buffer length:1];
    }
    return [[NSString alloc] initWithData:data encoding:NSUTF8StringEncoding];
}

- (double)getTheta:(Point *)p p0:(Point *)p0 {
    double theta = acos((p.x-p0.x)/hypot(p.x-p0.x,p.y-p0.y));
    if (p.y<p0.y) {
        theta = M_PI*2-theta;
    }
    return theta;
}

- (int)solve:(NSMutableArray *)points {
    Point *start = points[0];
    for (Point *v in points) {
        if (v.y<start.y) {
            start = v;
        }
    }
    Point *p0 = start;
    int n = 0;
    double prev = 0;
    do {
        double min = M_PI*3;
        Point *next = p0;
        for (Point *p in points) {
            double theta = [self getTheta:p p0:p0];
            if (theta>=prev&&theta<min) {
                min = theta;
                next = p;
            }
        }
        p0 = next;
        prev = min;
        n++;
    } while (p0!=start);
    return points.count-n;
}

