@implementation FastScanner

- (instancetype)initWithInputStream:(NSInputStream *)in {
    self = [super init];
    if (self) {
        _in = in;
        _buffer = [[NSMutableData alloc] init];
        _ptr = 0;
        _buflen = 0;
    }
