- (BOOL)hasNextByte {
    if (_ptr < _buflen) {
        return YES;
    } else {
        _ptr = 0;
        [_buffer setLength:0];
        NSError *error = nil;
        [_in readIntoBuffer:[_buffer mutableBytes] maxLength:[_buffer length] error:&error];
        if (error) {
            NSLog(@"Error: %@", error);
            return NO;
        }
        _buflen = [_buffer length];
        if (_buflen <= 0) {
            return NO;
        }
    }
    return YES;
}

- (NSInteger)readByte {
    if ([self hasNextByte]) {
        return [_buffer bytes][_ptr++];
    } else {
        return -1;
    }
}

- (BOOL)isPrintableChar:(NSInteger)c {
    return c >= 33 && c <= 126;
}

- (void)skipUnprintable {
    while ([self hasNextByte] && ![self isPrintableChar:[self readByte]]) {
        _ptr++;
    }
}

- (BOOL)hasNext {
    [self skipUnprintable];
    return [self hasNextByte];
}

- (NSString *)next {
    if (![self hasNext]) {
        NSLog(@"No more input.");
        return nil;
    }
    NSMutableString *sb = [[NSMutableString alloc] init];
    NSInteger b = [self readByte];
    while ([self isPrintableChar:b]) {
        [sb appendFormat:@"%c", (char)b];
        b = [self readByte];
    }
    return sb;
}

- (long long)nextLong {
    if (![self hasNext]) {
        NSLog(@"No more input.");
        return 0;
    }
    long long n = 0;
    BOOL minus = NO;
    NSInteger b = [self readByte];
    if (b == '-') {
        minus = YES;
        b = [self readByte];
    }
    if (b < '0' || b > '9') {
        NSLog(@"Invalid input.");
        return 0;
