@interface FastScanner : NSObject
@property (nonatomic, strong) NSInputStream *in;
@property (nonatomic, strong) NSMutableData *buffer;
@property (nonatomic, assign) int ptr;
@property (nonatomic, assign) int buflen;
- (BOOL)hasNextByte;
- (int)readByte;
- (BOOL)isPrintableChar:(int)c;
- (void)skipUnprintable;
- (BOOL)hasNext;
- (NSString *)next;
- (long long)nextLong;
@end

@implementation FastScanner
- (instancetype)init {
    self = [super init];
    if (self) {
        _in = [NSFileHandle fileHandleWithStandardInput];
        _buffer = [NSMutableData dataWithLength:1024];
        _ptr = 0;
        _buflen = 0;
    }
    return self;
}

- (BOOL)hasNextByte {
    if (_ptr < _buflen) {
        return YES;
    } else {
        _ptr = 0;
        [_in readDataOfLength:1024 intoBuffer:_buffer];
        _buflen = [_buffer length];
        if (_buflen <= 0) {
            return NO;
        }
    }
    return YES;
}

- (int)readByte {
    if ([self hasNextByte]) {
        return [_buffer bytes][_ptr++];
    } else {
        return -1;
    }
}

- (BOOL)isPrintableChar:(int)c {
    return c >= 33 && c <= 126;
}

- (void)skipUnprintable {
    while ([self hasNextByte] && ![self isPrintableChar:[self readByte]]) {
        _ptr++;
    }
}

- (BOOL)hasNext {
    [self skipUnprintable];
    return [self hasNextByte];
}

- (NSString *)next {
    if (![self hasNext]) {
        return nil;
    }
    NSMutableString *sb = [NSMutableString string];
    int b = [self readByte];
    while ([self isPrintableChar:b]) {
        [sb appendString:[NSString stringWithFormat:@"%c", b]];
        b = [self readByte];
    }
    return sb;
}

- (long long)nextLong {
    if (![self hasNext]) {
        return 0;
    }
    long long n = 0;
    BOOL minus = NO;
    int b = [self readByte];
    if (b == '-') {
        minus = YES;
        b = [self readByte];
    }
    if (b < '0' || b > '9') {
        return 0;
    }
    while (TRUE) {
        if (b >= '0' && b <= '9') {
            n *= 10;
            n += b - '0';
        } else if (b == -1 || ![self isPrintableChar:b]) {
            return minus ? -n : n;
        } else {
            return 0;
        }
        b = [self readByte];
    }
}
@end

