#import <Foundation/Foundation.h>

typedef struct {
    double x;
    double y;
} Point;

void createConvexHull(List<Point> *points, List<Point> *hull) {
    // Sort points by x-coordinate
    NSSortDescriptor *sortDescriptor = [NSSortDescriptor sortDescriptorWithKey:@"x" ascending:YES];
    [points sortUsingDescriptors:@[sortDescriptor]];

    // Create an empty list for the hull
    *hull = [[NSMutableArray alloc] init];

    // Process the points twice
    for (int k = 0; k < 2; ++k) {
        // Add the first two points to the hull
        [hull addObject:[points objectAtIndex:0]];
        [hull addObject:[points objectAtIndex:1]];

        // Process the remaining points
        for (int i = 2; i < points.count; ++i) {
            Point p = [[points objectAtIndex:i] pointValue];

            // Remove points from the hull until the signed area is positive or negative
            while (true) {
                Point q1 = [[hull objectAtIndex:hull.count - 2] pointValue];
                Point q2 = [[hull objectAtIndex:hull.count - 1] pointValue];
                double s = getSignedArea(q1, q2, p);
                if (k == 0) {
                    if (s < 0) break;
                } else {
                    if (s > 0) break;
                }
                [hull removeLastObject];
                if (hull.count < 2) break;
            }

            // Add the current point to the hull
            [hull addObject:[points objectAtIndex:i]];
        }

        // If this is the first pass, create a new hull for the second pass
        if (k == 0) {
            *hull = [[NSMutableArray alloc] init];
        }
    }

    // Reverse the hull for the second pass
    for (int i = 0; i < hull.count / 2; ++i) {
        Point temp = [[hull objectAtIndex:i] pointValue];
        [hull replaceObjectAtIndex:i withObject:[hull objectAtIndex:hull.count - i - 1]];
        [hull replaceObjectAtIndex:hull.count - i - 1 withObject:temp];
    }
}

double getSignedArea(Point p1, Point p2, Point p3) {
    return (p2.x - p1.x) * (p3.y - p1.y) - (p3.x - p1.x) * (p2.y - p1.y);
}

int main(int argc, const char * argv[]) {
    @autoreleasepool {
        // Read input from standard input
        NSString *input = [NSString stringWithContentsOfFile:@"/dev/stdin" encoding:NSUTF8StringEncoding error:nil];

        // Split input into lines
        NSArray *lines = [input componentsSeparatedByCharactersInSet:[NSCharacterSet newlineCharacterSet]];

        // Process each line
        for (NSString *line in lines) {
            // Split line into points
            NSArray *pointsArray = [line componentsSeparatedByString:@" "];
            NSMutableArray *points = [[NSMutableArray alloc] init];
            for (NSString *pointString in pointsArray) {
                NSArray *coordinates = [pointString componentsSeparatedByString:@","];

                double x = [coordinates[0] doubleValue];
                double y = [coordinates[1] doubleValue];

                Point p = {x, y};
                [points addObject:[NSValue valueWithPoint:p]];
            }

            // Create convex hull
            NSMutableArray *hull = [[NSMutableArray alloc] init];
            createConvexHull(points, &hull);

            // Output the number of points outside the hull
            NSLog(@"%lu", points.count - hull.count + 2);
        }
    }
    return 0;
}

