    return self;
}

@end

@interface FastScanner : NSObject

@property (nonatomic, strong) NSInputStream *in;
@property (nonatomic, strong) NSMutableData *buffer;
@property (nonatomic, assign) int ptr;
@property (nonatomic, assign) int buflen;

- (BOOL)hasNextByte;
- (int)readByte;
- (BOOL)isPrintableChar:(int)c;
- (void)skipUnprintable;
- (BOOL)hasNext;
- (NSString *)next;
- (long long)nextLong;

@end

@implementation FastScanner

- (instancetype)init {
    self = [super init];
    if (self) {
        _in = [[NSInputStream alloc] initWithFileAtPath:@"/dev/stdin"];
        _buffer = [NSMutableData dataWithLength:1024];
        _ptr = 0;
        _buflen = 0;
    }
    return self;
}

- (BOOL)hasNextByte {
    if (_ptr < _buflen) {
        return YES;
    } else {
        _ptr = 0;
        [_in readIntoBuffer:_buffer maxLength:1024];
        _buflen = [_buffer length];
        if (_buflen <= 0) {
            return NO;
        }
    }
    return YES;
}

- (int)readByte {
    if ([self hasNextByte]) {
        return [_buffer bytes][_ptr++];
    } else {
        return -1;
    }
}

- (BOOL)isPrintableChar:(int)c {
    return c >= 33 && c <= 126;
}

- (void)skipUnprintable {
    while ([self hasNextByte] && ![self isPrintableChar:[self readByte]]) {
        _ptr++;
    }
}

- (BOOL)hasNext {
    [self skipUnprintable];
    return [self hasNextByte];
}

- (NSString *)next {
    if (![self hasNext]) {
        [NSException raise:NSInvalidArgumentException format:@"No more input"];
    }
    NSMutableString *sb = [NSMutableString string];
    int b = [self readByte];
    while ([self isPrintableChar:b]) {
        [sb appendString:[NSString stringWithFormat:@"%c", b]];
        b = [self readByte];
    }
    return sb;
}

- (long long)nextLong {
    if (![self hasNext]) {
        [NSException raise:NSInvalidArgumentException format:@"No more input"];
    }
    long long n = 0;
    BOOL minus = NO;
    int b = [self readByte];
    if (b == '-') {
        minus = YES;
        b = [self readByte];
    }
    if (b < '0' || '9' < b) {
        [NSException raise:NSInvalidArgumentException format:@"Invalid input"];
    }
    while (TRUE) {
        if ('0' <= b && b <= '9') {
            n *= 10;
            n += b - '0';
        } else if (b == -1 || ![self isPrintableChar:b]) {
            return minus ? -n : n;
        } else {
            [NSException raise:NSInvalidArgumentException format:@"Invalid input"];
        }
        b = [self readByte];
    }
}

@end

int main(int argc, const char * argv[]) {
    @autoreleasepool {
        FastScanner *sc = [[FastScanner alloc] init];
        NSFileHandle *out = [NSFileHandle fileHandleWithStandardOutput];

        while (TRUE) {
            long long n = [sc nextLong];
            if (n == 0) {
                break;
            }
            NSMutableArray<Point *> *points = [NSMutableArray array];
            for (int i = 0; i < n; i++) {
                NSString *str = [sc next];
                NSArray<NSString *> *tmp = [str componentsSeparatedByString:@","];

                double x = [tmp[0] doubleValue];
                double y = [tmp[1] doubleValue];
                Point *p = [[Point alloc] initWithX:x y:y];
                [points addObject:p];
            }

            NSMutableArray<Point *> *hull = [NSMutableArray array];

            NSArray<Point *> *sortedPoints = [points sortedArrayUsingComparator:^NSComparisonResult(Point *p1, Point *p2) {
                if (p1.x < p2.x) {
                    return NSOrderedAscending;
                } else if (p1.x > p2.x) {
                    return NSOrderedDescending;
                } else {
                    return NSOrderedSame;
                }
            }];

            for (int k = 0; k < 2; ++k) {
                [hull addObject:sortedPoints[0]];
                [hull addObject:sortedPoints[1]];
                for (int i = 2; i < [sortedPoints count]; ++i) {
                    Point *p = sortedPoints[i];
                    for (;;) {
                        Point *q1 = hull[hull.count - 2];
                        Point *q2 = hull[hull.count - 1];
                        double s = (q2.x - q1.x) * (p.y - q1.y) - (p.x - q1.x) * (q2.y - q1.y);
                        if (k == 0) {
                            if (s < 0) {
                                break;
                            }
                        } else {
                            if (s > 0) {
                                break;
                            }
                        }
                        [hull removeLastObject];
                        if (hull.count < 2) {
                            break;
                        }
                    }
                    [hull addObject:p];
                }
                if (k == 0) {
                    hull = [NSMutableArray arrayWithArray:hull];
                }
            }

            for (int i = 0; i < hull.count; ++i) {
                Point *p = hull[hull.count - i - 1];
                [hull addObject:p];
            }

            long long result = [points count] - [hull count] + 2;
            [out writeData:[NSString stringWithFormat:@"%lld\n", result].dataUsingEncoding:NSUTF8StringEncoding]];
        }
    }
    return 0;
}

