double getTheta(CGPoint p1, CGPoint p2) {
    double dx = p2.x - p1.x;
    double ax = dx >= 0 ? dx : -dx;
    double dy = p2.y - p1.y;
    double ay = dy >= 0 ? dy : -dy;

    double t = (ax + ay == 0) ? 0 : dy / (ax + ay);
    if (dx < 0) {
        t = 2 - t;
    }
    else if (dy < 0) {
        t += 4;
    }
    return t * 90.0;
}

