        if (n == 0) break;
        NSMutableArray<NSValue *> *plist = [NSMutableArray array];
        for (NSInteger i = 0; i < n; i++) {
            NSString *input = [[NSApplication sharedApplication] nextEventMatchingMask:NSAnyEventMask untilDate:nil inMode:NSDefaultRunLoopMode dequeue:YES].charactersIgnoringModifiers;
            NSArray *a = [input componentsSeparatedByString:@","]; 
            double x = [a[0] doubleValue];
            double y = [a[1] doubleValue];
            NSValue *point = [NSValue valueWithCGPoint:CGPointMake(x, y)];
            [plist addObject:point];
        }
        NSArray<NSValue *> *res = [self convexHull:plist];
        NSLog(@"%ld", n - [res count]);
    }
}

- (NSArray<NSValue *> *)convexHull:(NSArray<NSValue *> *)plist {
    NSInteger n = [plist count];
    NSComparator comparator = ^(id obj1, id obj2) {
        NSValue *o1 = (NSValue *)obj1;
        NSValue *o2 = (NSValue *)obj2;
        CGPoint p1 = [o1 CGPointValue];
        CGPoint p2 = [o2 CGPointValue];
        if (p1.x < p2.x) return NSOrderedAscending;
        else if (p1.x > p2.x) return NSOrderedDescending;
        else if (p1.y < p2.y) return NSOrderedAscending;
        else if (p1.y > p2.y) return NSOrderedDescending;
        else return NSOrderedSame;
    };
    [plist sortUsingComparator:comparator];
    NSInteger k = 0;
    NSMutableArray<NSValue *> *qs = [NSMutableArray array];
    for (NSInteger i = 0; i < n; i++) {
        while (k > 1 && CGLineCreateWithPoints([qs[k-2] CGPointValue], [qs[k-1] CGPointValue]).relativeCCW([plist[i] CGPointValue]) > 0) {
            k--;
        }
        [qs addObject:plist[i]];
        k++;
    }
    for (NSInteger i = n - 2, t = k; i >= 0; i--) {
        while (k > t && CGLineCreateWithPoints([qs[k-2] CGPointValue], [qs[k-1] CGPointValue]).relativeCCW([plist[i] CGPointValue]) > 0) {
            k--;
        }
        [qs addObject:plist[i]];
        k++;
    }
    NSArray<NSValue *> *res = [qs subarrayWithRange:NSMakeRange(0, k-1)];
    return res;
}

