#import <Foundation/Foundation.h>

int ccw(double x1, double y1, double x2, double y2, double x3, double y3) {
    x2 -= x1; x3 -= x1; y2 -= y1; y3 -= y1;
    double c = x2 * y3 - x3 * y2;
    if (c > 0) return +1;
    if (c < 0) return -1;
    if (x2 * x3 + y2 * y3 < 0) return +2;
    if (x3 * x3 + y3 * y3 - x2 * x2 - y2 * y2 > 0) return -2;
    return 0;
}

double** convexHull(double** ps, int n, int* chSize) {
    int k = 0;
    qsort(ps, n, sizeof(double*), ^(const void* a, const void* b) {
        double* x1 = *(double**)a;
        double* y1 = *(double**)a + 1;
        double* x2 = *(double**)b;
        double* y2 = *(double**)b + 1;
        double x = *x1 - *x2;
        double y = *y1 - *y2;
        if (x != 0) return x > 0 ? 1 : -1;
        if (y != 0) return y > 0 ? 1 : -1;
        return 0;
    });
    double** ch = malloc(2 * n * sizeof(double*));
    for (int i = 0; i < n; ch[k++] = ps[i++]) {
        while (k >= 2 && ccw(ch[k - 2][0], ch[k - 2][1], ch[k - 1][0], ch[k - 1][1], ps[i][0], ps[i][1]) <= 0) {
            k--;
        }
    }
    for (int i = n - 2, t = k + 1; i >= 0; ch[k++] = ps[i--]) {
        while (k >= t && ccw(ch[k - 2][0], ch[k - 2][1], ch[k - 1][0], ch[k - 1][1], ps[i][0], ps[i][1]) <= 0) {
            k--;
        }
    }
    *chSize = k - 1;
    return ch;
}

