    char c;
    while ([stream hasBytesAvailable]) {
        [stream read:&c maxLength:1];
        if (c == '\n') {
            break;
        }
        [buffer appendString:[NSString stringWithFormat:@"%c", c]];
    }
    return buffer;
}

