#import <Foundation/Foundation.h>

@interface FastScanner : NSObject

- (instancetype)init;
- (BOOL)hasNext;
- (NSString *)next;
- (long long)nextLong;

@end

@implementation FastScanner

- (instancetype)init {
    self = [super init];
    if (self) {
        self.inputStream = [NSInputStream inputStreamWithFileAtPath:@"/dev/stdin"];
        [self.inputStream open];
    }
    return self;
}

- (BOOL)hasNext {
    while ([self.inputStream hasBytesAvailable]) {
        NSData *data = [self.inputStream readDataOfLength:1];
        char c = [data getBytes:&c length:1][0];
        if (c != '\n' && c != '\r' && c != ' ') {
            return YES;
        }
    }
    return NO;
}

- (NSString *)next {
    NSMutableString *result = [NSMutableString string];
    while ([self.inputStream hasBytesAvailable]) {
        NSData *data = [self.inputStream readDataOfLength:1];
        char c = [data getBytes:&c length:1][0];
        if (c == '\n' || c == '\r' || c == ' ') {
            break;
        }
        [result appendString:[NSString stringWithFormat:@"%c", c]];
    }
    return result;
}

- (long long)nextLong {
    long long result = 0;
    BOOL negative = NO;
    while ([self.inputStream hasBytesAvailable]) {
        NSData *data = [self.inputStream readDataOfLength:1];
        char c = [data getBytes:&c length:1][0];
        if (c == '-') {
            negative = YES;
            continue;
        }
        if (c >= '0' && c <= '9') {
            result = result * 10 + (c - '0');
        } else {
            break;
        }
    }
    return negative ? -result : result;
}

@end

int main(int argc, const char * argv[]) {
    @autoreleasepool {
        FastScanner *scanner = [[FastScanner alloc] init];

        int list[12][100000];
        for (int i = 0; i < 12; i++) {
            for (int j = 0; j < 100000; j++) {
                list[i][j] = 0;
            }
        }

        for (int i = 0; i < 12; i++) {
            for (int j = 0; j < 100000; j++) {
                if (i == 0) {
                    list[i][j] = 0;
                } else {
                    list[i][j] = list[i-1][j];
                    for (int k = 0; k < 10; k++) {
                        list[i][j] += list[i-1][j-k*i];
                    }
                }
            }
        }

        while ([scanner hasNext]) {
            long long n = [scanner nextLong];
            long long s = [scanner nextLong];
            NSLog(@"%lld", list[n+1][s]);
        }
    }
    return 0;
}

