@interface FastScanner : NSObject
@property (nonatomic, strong) NSData *data;
@property (nonatomic, assign) NSUInteger ptr;
@property (nonatomic, assign) NSUInteger buflen;
- (instancetype)initWithData:(NSData *)data;
- (BOOL)hasNextByte;
- (int)readByte;
- (BOOL)isPrintableChar:(int)c;
- (void)skipUnprintable;
- (BOOL)hasNext;
- (NSString *)next;
- (long long)nextLong;
@end

@implementation FastScanner

- (instancetype)initWithData:(NSData *)data {
    self = [super init];
    if (self) {
        _data = data;
        _ptr = 0;
        _buflen = 0;
    }
    return self;
}

- (BOOL)hasNextByte {
    if (_ptr < _buflen) {
        return YES;
    } else {
        _ptr = 0;
        _buflen = [_data length];
        if (_buflen <= 0) {
            return NO;
        }
    }
    return YES;
}

- (int)readByte {
    if ([self hasNextByte]) {
        return [_data bytes][_ptr++];
    } else {
        return -1;
    }
}

- (BOOL)isPrintableChar:(int)c {
    return c >= 33 && c <= 126;
}

- (void)skipUnprintable {
    while ([self hasNextByte] && ![self isPrintableChar:[self readByte]]) {
        _ptr++;
    }
}

- (BOOL)hasNext {
    [self skipUnprintable];
    return [self hasNextByte];
}

- (NSString *)next {
    if (![self hasNext]) {
        NSException *exception = [NSException exceptionWithName:@"NoSuchElementException" reason:@"No more elements" userInfo:nil];
        @throw exception;
    }
    NSMutableString *sb = [NSMutableString string];
    int b = [self readByte];
    while ([self isPrintableChar:b]) {
        [sb appendFormat:@"%c", b];
        b = [self readByte];
    }
    return sb;
}

- (long long)nextLong {
    if (![self hasNext]) {
        NSException *exception = [NSException exceptionWithName:@"NoSuchElementException" reason:@"No more elements" userInfo:nil];
        @throw exception;
    }
    long long n = 0;
    BOOL minus = NO;
    int b = [self readByte];
    if (b == '-') {
        minus = YES;
        b = [self readByte];
    }
    if (b < '0' || b > '9') {
        NSException *exception = [NSException exceptionWithName:@"NumberFormatException" reason:@"Invalid number format" userInfo:nil];
        @throw exception;
    }
    while (YES) {
        if (b >= '0' && b <= '9') {
            n *= 10;
            n += b - '0';
        } else if (b == -1 || ![self isPrintableChar:b]) {
            return minus ? -n : n;
        } else {
            NSException *exception = [NSException exceptionWithName:@"NumberFormatException" reason:@"Invalid number format" userInfo:nil];
            @throw exception;
        }
        b = [self readByte];
    }
}

@end

