@interface Prim : NSObject

@property (nonatomic, assign) NSInteger V;
@property (nonatomic, assign) NSInteger E;
@property (nonatomic, strong) NSMutableArray *edges;

- (instancetype)initWithV:(NSInteger)V E:(NSInteger)E;
- (void)setFrom:(NSInteger)from to:(NSInteger)to cost:(NSInteger)cost;
- (NSInteger)run;

@end

@implementation Prim

- (instancetype)initWithV:(NSInteger)V E:(NSInteger)E {
    self = [super init];
    if (self) {
        self.V = V;
        self.E = E;
        self.edges = [NSMutableArray array];
        for (NSInteger i = 0; i < V; i++) {
            [self.edges addObject:[NSMutableArray array]];
        }
    }
    return self;
}

- (void)setFrom:(NSInteger)from to:(NSInteger)to cost:(NSInteger)cost {
    Edge *edge = [[Edge alloc] initWithTo:to cost:cost];
    [[self.edges objectAtIndex:from] addObject:edge];
}

- (NSInteger)run {
    BOOL *done = calloc(self.V, sizeof(BOOL));
    NSPointerArray *q = [NSPointerArray array];
    Edge *edge = [[Edge alloc] initWithTo:0 cost:0];
    [q addObject:edge];
    NSInteger costSum = 0;
    while (![q count]) {
        edge = [q objectAtIndex:0];
        if (done[edge.to]) {
            continue;
        }
        done[edge.to] = YES;
        costSum += edge.cost;
        for (Edge *e in [self.edges objectAtIndex:edge.to]) {
            [q addObject:e];
        }
    }
    free(done);
    return costSum;
}

@end

