            [self.edges addObject:array];
        }
    }
    return self;
}

- (void)setFrom:(int)from to:(int)to cost:(int)cost {
    NSMutableArray<NSNumber *> *array = self.edges[from];
    [array addObject:@(to)];
    [array addObject:@(cost)];
}

- (int)run {
    BOOL *done = (BOOL *)malloc(sizeof(BOOL) * self.V);
    memset(done, 0, sizeof(BOOL) * self.V);
    NSMutableArray<Edge *> *q = [NSMutableArray arrayWithCapacity:0];
    [q addObject:[[Edge alloc] initWithT:0 W:0]];
    int costSum = 0;
    while (q.count > 0) {
        Edge *e = [q objectAtIndex:0];
        [q removeObjectAtIndex:0];
        if (done[e.t]) {
            continue;
        }
        done[e.t] = YES;
        costSum += e.w;
        for (int i = 0; i < self.edges[e.t].count; i += 2) {
            int to = [self.edges[e.t][i] intValue];
            int cost = [self.edges[e.t][i + 1] intValue];
            Edge *edge = [[Edge alloc] initWithT:to W:cost];
            [q addObject:edge];
        }
    }
    free(done);
    return costSum;
}

